var _ = ginkgo.It("LifecycleCloseoutPolicyLoopCloseoutObservesOpenLoopObligation", func() {
	decision := lifecycleLoopCloseoutDecision("completed", true)

	if !decision.Handled {
		ginkgo.Fail("expected loop closeout to handle open loop obligation", 1)
	}

	if decision.Gate.Gate != autonomy.GateLoop ||
		decision.Gate.Decision != autonomy.PolicyObserve ||
		decision.Gate.InvariantID != "loop.repeated_call" ||
		decision.Gate.ReasonCode != "completed_without_loop_fuse" ||
		decision.Gate.Source != "runner_loop_closeout" {
		ginkgo.Fail(fmt.Sprintf("unexpected loop closeout decision: %#v", decision.Gate), 1)
	}
})

var _ = ginkgo.It("LifecycleCloseoutPolicyLoopCloseoutSkipsClosedLoopObligation", func() {
	decision := lifecycleLoopCloseoutDecision("completed", false)

	if decision.Handled {
		ginkgo.Fail(fmt.Sprintf("closed loop obligation should not emit closeout decision: %#v", decision), 1)
	}
})

var _ = ginkgo.It("LifecycleCloseoutPolicyLoopCloseoutPreservesStopReason", func() {
	decision := lifecycleLoopCloseoutDecision("model_error", true)

	if !decision.Handled || decision.Gate.ReasonCode != "model_error" {
		ginkgo.Fail(fmt.Sprintf("expected non-completed stop reason to pass through, got %#v", decision), 1)
	}
})

var _ = ginkgo.It("LifecycleCloseoutPolicyBudgetCloseoutCarriesRunPolicyState", func() {
	policy := RunPolicy{
		MaxToolSteps:       7,
		MaxModelCalls:      3,
		MaxContextMessages: 11,
		MaxContextChars:    4096,
	}

	decision := lifecycleBudgetCloseoutDecision(policy, runnerMetrics{ToolCalls: 7, ModelCalls: 2}, "tool_step_budget_exhausted", true)

	if !decision.Handled {
		ginkgo.Fail("expected budget closeout to handle every run", 1)
	}

	if decision.Gate.Gate != autonomy.GateBudget ||
		decision.Gate.Decision != autonomy.PolicyStop ||
		decision.Gate.InvariantID != "budget.run_policy" ||
		decision.Gate.ReasonCode != "tool_step_budget_exhausted" ||
		decision.Gate.Source != "runner_budget_gate" {
		ginkgo.Fail(fmt.Sprintf("unexpected budget gate decision: %#v", decision.Gate), 1)
	}

	if decision.Gate.Budget == nil {
		ginkgo.Fail("budget closeout should carry budget state", 1)
	}

	if decision.Gate.Budget.MaxToolSteps != 7 ||
		decision.Gate.Budget.UsedToolSteps != 7 ||
		decision.Gate.Budget.MaxModelCalls != 3 ||
		decision.Gate.Budget.UsedModelCalls != 2 ||
		decision.Gate.Budget.MaxContextMessages != 11 ||
		decision.Gate.Budget.MaxContextChars != 4096 ||
		!decision.Gate.Budget.Exhausted ||
		decision.Gate.Budget.ExhaustionReason != "tool_step_budget_exhausted" {
		ginkgo.Fail(fmt.Sprintf("unexpected budget state: %#v", decision.Gate.Budget), 1)
	}
})

var _ = ginkgo.It("LifecycleCloseoutPolicyBudgetCloseoutDefaultsBlankStopReason", func() {
	decision := lifecycleBudgetCloseoutDecision(RunPolicy{}, runnerMetrics{}, "", false)

	if !decision.Handled || decision.Gate.Decision != autonomy.PolicyObserve || decision.Gate.ReasonCode != "completed" {
		ginkgo.Fail(fmt.Sprintf("unexpected default budget closeout: %#v", decision), 1)
	}

	if decision.Gate.Budget == nil || decision.Gate.Budget.Exhausted || decision.Gate.Budget.ExhaustionReason != "" {
		ginkgo.Fail(fmt.Sprintf("unexpected default budget state: %#v", decision.Gate.Budget), 1)
	}
})

