var _ = ginkgo.It("ModelCallReadinessPolicyStopsOnOperationalModelCallLimit", func() {
	decision := modelCallReadinessBeforeModelCall(ModelCallReadinessPolicyInput{
		Policy:  RunPolicy{MaxOperationalModelCalls: 2},
		Metrics: runnerMetrics{startedAt: time.Now(), ModelCalls: 2},
	})

	if !decision.Stop || !decision.BudgetExhausted || decision.StopReason != "operational_model_call_limit_exceeded" {
		ginkgo.Fail(fmt.Sprintf("unexpected operational model-call stop decision: %#v", decision), 1)
	}

	if decision.CloseoutMode != noToolsCloseoutDeterministicRequired || !strings.Contains(decision.CloseoutPrompt, "Operational model-call limit is exhausted") {
		ginkgo.Fail(fmt.Sprintf("operational model-call stop should require deterministic closeout with budget prompt, got %#v", decision), 1)
	}
})

