var _ = ginkgo.It("RunnerAutonomyRecorderEmitsTurnPhaseContractPresentation", func() {
	t := ginkgo.GinkgoT()
	var runEvents []RunEvent

	runner := newRunnerRunFixture(&Runner{
		AgentName: "main",
		OnEvent: func(event RunEvent) {
			runEvents = append(runEvents, event)
		},
	})
	brief := workerruntime.WorkerRuntimeBrief{
		Lane:              "plan-execute",
		TaskFamily:        PlanThenExecutePlannerTaskFamily,
		Contract:          "submit_plan",
		PermissionProfile: "guarded_workspace_write",
		RequiredEditPaths: []string{"a.go"},
		AllowedTools:      []string{"read_file", "submit_plan"},
	}
	results := []workspace.ToolResult{
		readFileSourceWindowResult("a.go", 1, 10, 10, "1:package a\n"),
	}
	recorder := newRunnerAutonomyRecorder(runner, RunPolicy{}, brief, results)

	if recorder == nil {
		ginkgo.Fail("newRunnerAutonomyRecorder returned nil", 1)
	}

	recorder.emitContractStarted(brief)

	contract := deriveTurnPhaseContract(TurnPhaseContractInput{
		ContractID:         recorder.contract.ContractID,
		ModelCallID:        recorder.contract.ContractID + ":model_call_1",
		Step:               1,
		Brief:              brief,
		Results:            results,
		BaseAllowedTools:   []string{"submit_plan"},
		TextualToolParser:  true,
		VerificationStatus: "not_required",
	})
	modelProtocol, ok := runner.compileModelProtocolProjection(brief, results, contract, RunPolicy{}, true)

	if !ok {
		ginkgo.Fail("expected model protocol projection", 1)
	}

	modelProtocol = recorder.bindModelProtocolProjection(modelProtocol)
	recorder.emitTurnPhaseContract(contract, modelProtocol)

	events := decodeRunnerAutonomyEventsForTest(t, runEvents)

	var presented autonomy.Event

	for _, event := range events {
		if event.Type == autonomy.EventContractPresented &&
			event.Lifecycle != nil &&
			event.Lifecycle.TurnPhaseContract != nil {

			presented = event
			break
		}
	}

	if presented.EventID == "" {
		ginkgo.Fail(fmt.Sprintf("expected contract_presented turn phase event, got %#v", events), 1)
	}

	phase := presented.Lifecycle.TurnPhaseContract
	if phase.SchemaVersion != turnPhaseContractSchemaVersion ||
		phase.PhaseID != string(contractcompile.TurnPhaseSubmitReadyTextual) ||
		phase.ProtocolHash != modelProtocol.ProtocolHash ||
		!slices.Contains(phase.ActionPolicy.AllowedActionClasses, actionSubmitPlan) ||
		!slices.Contains(phase.RuntimeCall.ExpressibleActionClasses, actionSourceSatisfied) {

		ginkgo.Fail(fmt.Sprintf("unexpected turn phase payload: %#v", phase), 1)
	}

	if presented.Lifecycle.ProtocolHash != modelProtocol.ProtocolHash ||
		presented.Lifecycle.ModelProtocol == nil ||
		presented.Lifecycle.ModelProtocol.ProtocolHash != modelProtocol.ProtocolHash {

		ginkgo.Fail(fmt.Sprintf("contract_presented missing model protocol hash: %#v", presented.Lifecycle), 1)
	}
	expectedActivePhaseID := recorder.plannerCompile.Protocol.PhaseID
	if recorder.activeTurnContract.ContractID != recorder.contract.ContractID {
		ginkgo.Fail(fmt.Sprintf("active turn contract id = %q, want %q", recorder.activeTurnContract.ContractID, recorder.contract.ContractID), 1)
	}
	if recorder.activeTurnContract.ProtocolHash != recorder.activeAuthority.ProtocolHash {
		ginkgo.Fail(fmt.Sprintf("active turn protocol hash = %q, want %q", recorder.activeTurnContract.ProtocolHash, recorder.activeAuthority.ProtocolHash), 1)
	}
	if recorder.activeTurnContract.PhaseID != expectedActivePhaseID {
		ginkgo.Fail(fmt.Sprintf("active turn phase id = %q, want %q", recorder.activeTurnContract.PhaseID, expectedActivePhaseID), 1)
	}
	if !recorder.activeTurnContract.HasActiveAuthority() {
		ginkgo.Fail(fmt.Sprintf("active turn contract projection not active: %#v", recorder.activeTurnContract), 1)
	}

	report := autonomy.AuditEvents(events, autonomy.EventAuditOptions{})
	if report.TurnPhaseCoverage.Total != 1 || len(report.TurnPhaseCoverage.Contradictions) != 0 {
		ginkgo.Fail(fmt.Sprintf("expected clean turn phase audit coverage, got %#v", report.TurnPhaseCoverage), 1)
	}
})

var _ = ginkgo.It("RunnerAutonomyPlannerContractProtocolAndGatesShareCompiledAuthority", func() {
	t := ginkgo.GinkgoT()
	var runEvents []RunEvent

	runner := newRunnerRunFixture(&Runner{
		AgentName: "main",
		OnEvent: func(event RunEvent) {
			runEvents = append(runEvents, event)
		},
	})
	brief := workerruntime.WorkerRuntimeBrief{
		Lane:              "plan-execute",
		TaskFamily:        PlanThenExecutePlannerTaskFamily,
		Contract:          "submit_plan",
		PermissionProfile: "guarded_workspace_write",
		RequiredEditPaths: []string{"a.go"},
		AllowedTools:      []string{"read_file", "code_navigate", "submit_plan"},
		RequiredTools:     []string{"submit_plan"},
	}
	results := []workspace.ToolResult{
		readFileSourceWindowResult("a.go", 1, 10, 10, "1:package a\n"),
	}
	policy := RunPolicy{MaxToolSteps: 2, MaxModelCalls: 1}
	recorder := newRunnerAutonomyRecorder(runner, policy, brief, results)

	if recorder == nil {
		ginkgo.Fail("newRunnerAutonomyRecorder returned nil", 1)
	}

	if !recorder.hasPlannerCompile {
		ginkgo.Fail("plan-execute planner recorder should retain compiled contractcompile result", 1)
	}

	binding := recorder.activeAuthority
	if binding.ContractID != recorder.plannerCompile.ActiveAuthority.ContractID ||
		binding.RuntimeContractID != recorder.plannerCompile.ActiveAuthority.RuntimeContractID ||
		binding.ProtocolHash != recorder.plannerCompile.ActiveAuthority.ProtocolHash ||
		binding.ActiveInvariantID != contractcompile.InvariantActiveAuthority {

		ginkgo.Fail(fmt.Sprintf("recorder should expose compile result active authority, got %#v want %#v", binding, recorder.plannerCompile.ActiveAuthority), 1)
	}

	if recorder.contract.Scope.InvocationKind != autonomy.InvocationPhase ||
		recorder.contract.Scope.TaskFamily != contractcompile.InvocationPlanExecutePlanner ||
		recorder.contract.Scope.Phase != contractcompile.DefaultPlannerPhase {

		ginkgo.Fail(fmt.Sprintf("planner recorder should use compiled phase contract scope, got %#v", recorder.contract.Scope), 1)
	}

	recorder.emitContractStarted(brief)

	phase := deriveTurnPhaseContract(TurnPhaseContractInput{
		ContractID:         binding.ContractID,
		ModelCallID:        binding.ContractID + ":model_call_1",
		Step:               1,
		Brief:              brief,
		Results:            results,
		BaseAllowedTools:   []string{"read_file", "code_navigate", "submit_plan"},
		TextualToolParser:  true,
		VerificationStatus: "not_required",
	})
	protocol, ok := runner.compileModelProtocolProjection(brief, results, phase, policy, true)

	if !ok {
		ginkgo.Fail("expected model protocol projection", 1)
	}

	protocol = recorder.bindModelProtocolProjection(protocol)
	if protocol.ContractID != recorder.contract.ContractID {
		ginkgo.Fail(fmt.Sprintf("model protocol should cite compiled recorder contract %q, got %q", recorder.contract.ContractID, protocol.ContractID), 1)
	}

	recorder.emitTurnPhaseContract(phase, protocol)
	recorder.markModelProtocolPresented(protocol)
	recorder.emitCompletionGateAttempt(autonomy.PolicyReject, "required_obligations_open", results, 0)

	events := decodeRunnerAutonomyEventsForTest(t, runEvents)

	var compiledID, compiledRuntimeID, compiledProtocolHash, compiledInvariantID, presentedID, presentedProtocolID, presentedProtocolHash, presentedInvariantID, gateID, gateProtocolHash, gateInvariantID string

	for _, event := range events {
		switch event.Type {
		case autonomy.EventContractCompiled:
			compiledID = event.ContractID
			if event.Lifecycle == nil || event.Lifecycle.Summary == nil || event.Lifecycle.Summary.ContractID != recorder.contract.ContractID {
				ginkgo.Fail(fmt.Sprintf("contract_compiled summary should carry compiled contract id: %#v", event.Lifecycle), 1)
			}

			compiledProtocolHash = event.Lifecycle.ProtocolHash
			compiledInvariantID = event.Lifecycle.InvariantID

			for _, source := range event.Lifecycle.Summary.AuthoritySources {
				if source == binding.RuntimeContractID {
					compiledRuntimeID = source
				}
			}
		case autonomy.EventContractPresented:
			if event.Lifecycle != nil && event.Lifecycle.ModelProtocol != nil {
				presentedID = event.ContractID
				presentedProtocolID = event.Lifecycle.ModelProtocol.ContractID
				presentedProtocolHash = event.Lifecycle.ModelProtocol.ProtocolHash
				presentedInvariantID = event.Lifecycle.ModelProtocol.ActiveInvariantID
			}
		case autonomy.EventGateDecision:
			if event.Gate != nil && event.Gate.Gate == autonomy.GateCompletion {
				gateID = event.ContractID
				gateProtocolHash = event.Gate.ProtocolHash
				gateInvariantID = event.Gate.InvariantID
			}
		}
	}

	if compiledID == "" || presentedID == "" || gateID == "" {
		ginkgo.Fail(fmt.Sprintf("missing compiled/presented/gate events: compiled=%q presented=%q gate=%q events=%#v", compiledID, presentedID, gateID, events), 1)
	}

	if compiledRuntimeID != binding.RuntimeContractID ||
		compiledProtocolHash != binding.ProtocolHash ||
		compiledInvariantID != binding.ActiveInvariantID {

		ginkgo.Fail(fmt.Sprintf("contract_started did not expose active authority binding: runtime=%q protocol=%q invariant=%q binding=%#v", compiledRuntimeID, compiledProtocolHash, compiledInvariantID, binding), 1)
	}

	for label, got := range map[string]string{
		"contract_compiled":        compiledID,
		"contract_presented":       presentedID,
		"model_protocol_contract":  presentedProtocolID,
		"completion_gate_contract": gateID,
	} {
		if got != recorder.contract.ContractID {
			ginkgo.Fail(fmt.Sprintf("%s contract id = %q, want compiled recorder id %q", label, got, recorder.contract.ContractID), 1)
		}
	}

	if presentedProtocolHash == "" ||
		compiledProtocolHash != presentedProtocolHash ||
		gateProtocolHash != presentedProtocolHash ||
		gateProtocolHash != protocol.ProtocolHash {

		ginkgo.Fail(fmt.Sprintf("protocol hash drift: compiled=%q presented=%q gate=%q protocol=%q", compiledProtocolHash, presentedProtocolHash, gateProtocolHash, protocol.ProtocolHash), 1)
	}

	if presentedInvariantID != binding.ActiveInvariantID || gateInvariantID == "" {
		ginkgo.Fail(fmt.Sprintf("model protocol/gate events should carry active authority invariant, presented=%q gate=%q binding=%#v", presentedInvariantID, gateInvariantID, binding), 1)
	}
})

var _ = ginkgo.It("RunnerAutonomyPlannerAuthorityIgnoresStalePhaseContractID", func() {
	t := ginkgo.GinkgoT()
	var runEvents []RunEvent

	runner := newRunnerRunFixture(&Runner{
		AgentName: "main",
		OnEvent: func(event RunEvent) {
			runEvents = append(runEvents, event)
		},
	})
	brief := workerruntime.WorkerRuntimeBrief{
		Lane:              "plan-execute",
		TaskFamily:        PlanThenExecutePlannerTaskFamily,
		Contract:          "submit_plan",
		PermissionProfile: "guarded_workspace_write",
		RequiredEditPaths: []string{"a.go"},
		AllowedTools:      []string{"read_file", "submit_plan"},
	}
	results := []workspace.ToolResult{{Tool: "read_file", Summary: "Read f1 a.go lines 1-10 (total lines: 10)"}}
	recorder := newRunnerAutonomyRecorder(runner, RunPolicy{}, brief, results)

	if recorder == nil {
		ginkgo.Fail("newRunnerAutonomyRecorder returned nil", 1)
	}

	recorder.emitContractStarted(brief)

	staleID := "contract_stale_phase"
	phase := deriveTurnPhaseContract(TurnPhaseContractInput{
		ContractID:         staleID,
		ModelCallID:        staleID + ":model_call_1",
		Step:               1,
		Brief:              brief,
		Results:            results,
		BaseAllowedTools:   []string{"submit_plan"},
		TextualToolParser:  true,
		VerificationStatus: "not_required",
	})
	protocol, ok := runner.compileModelProtocolProjection(brief, results, phase, RunPolicy{}, true)

	if !ok {
		ginkgo.Fail("expected model protocol projection", 1)
	}

	protocol = recorder.bindModelProtocolProjection(protocol)
	recorder.emitTurnPhaseContract(phase, protocol)
	if recorder.activeTurnContract.ContractID != recorder.contract.ContractID ||
		recorder.activeTurnContract.ProtocolHash != recorder.activeAuthority.ProtocolHash ||
		recorder.activeTurnContract.Canonical.ContractID != recorder.contract.ContractID ||
		recorder.activeTurnContract.Protocol.ProtocolHash != recorder.activeAuthority.ProtocolHash ||
		recorder.activeTurnContract.ActiveAuthority.ActiveInvariantID != contractcompile.InvariantActiveAuthority ||
		len(recorder.activeTurnContract.ObligationIDs) == 0 {

		ginkgo.Fail(fmt.Sprintf("active turn contract should be projected from compiled canonical contract: %#v", recorder.activeTurnContract), 1)
	}
	recorder.markModelProtocolPresented(protocol)
	recorder.emitCompletionGateAttempt(autonomy.PolicyReject, "required_obligations_open", results, 0)

	events := decodeRunnerAutonomyEventsForTest(t, runEvents)
	for _, event := range events {
		switch event.Type {
		case autonomy.EventContractPresented:
			if event.ContractID != recorder.contract.ContractID {
				ginkgo.Fail(fmt.Sprintf("presented event adopted stale contract id %q, want %q", event.ContractID, recorder.contract.ContractID), 1)
			}

			if event.Lifecycle == nil || event.Lifecycle.ModelProtocol == nil {
				continue
			}

			if event.Lifecycle.ModelProtocol.ContractID != recorder.contract.ContractID {
				ginkgo.Fail(fmt.Sprintf("model protocol adopted stale contract id %q, want %q", event.Lifecycle.ModelProtocol.ContractID, recorder.contract.ContractID), 1)
			}

			if event.Lifecycle.ModelProtocol.ProtocolHash != recorder.activeAuthority.ProtocolHash {
				ginkgo.Fail(fmt.Sprintf("model protocol hash = %q, want compiled binding %q", event.Lifecycle.ModelProtocol.ProtocolHash, recorder.activeAuthority.ProtocolHash), 1)
			}
		case autonomy.EventGateDecision:
			if event.Gate != nil && event.Gate.Gate == autonomy.GateCompletion {
				if event.ContractID != recorder.contract.ContractID {
					ginkgo.Fail(fmt.Sprintf("gate event adopted stale contract id %q, want %q", event.ContractID, recorder.contract.ContractID), 1)
				}

				if event.Gate.ProtocolHash != recorder.activeAuthority.ProtocolHash {
					ginkgo.Fail(fmt.Sprintf("gate protocol hash = %q, want compiled binding %q", event.Gate.ProtocolHash, recorder.activeAuthority.ProtocolHash), 1)
				}
			}
		}
	}
})

