var _ = ginkgo.It("PlanExecuteHistoryPendingModelProtocolUsesCanonicalReadAction", func() {
	runner := newRunnerRunFixture(&Runner{})
	brief := workerruntime.WorkerRuntimeBrief{
		Lane:              "plan-execute",
		TaskFamily:        PlanThenExecutePlannerTaskFamily,
		Contract:          "submit_plan",
		PermissionProfile: "guarded_workspace_write",
		RequiredEditPaths: []string{"a.go"},
		RequiredEvidence:  []string{string(workerruntime.RequiredEvidenceGitHistoryRationale)},
		AllowedTools: []string{
			"read_file",
			"context_impact",
			"harness_feedback",
			"history_range",
			"history_symbol",
			"blame_range",
			"submit_plan",
		},
	}
	results := []workspace.ToolResult{
		readFileSourceWindowResult("a.go", 1, 10, 10, "1:package a\n"),
	}
	phase := deriveTurnPhaseContract(TurnPhaseContractInput{
		Brief:             brief,
		Results:           results,
		BaseAllowedTools:  brief.AllowedTools,
		TextualToolParser: true,
		ToolTransportMode: "textual",
	})

	if phase.PhaseID != contractcompile.TurnPhaseHistoryPending {
		ginkgo.Fail(fmt.Sprintf("phase = %q, want %q", phase.PhaseID, contractcompile.TurnPhaseHistoryPending), 1)
	}

	phase.AllowedTools = textutil.Unique(append(phase.AllowedTools, "blame_range", "context_impact", "harness_feedback"))
	phase.ActionPolicy.CallableToolNames = textutil.Unique(append(phase.ActionPolicy.CallableToolNames, "blame_range", "context_impact", "harness_feedback"))

	protocol, ok := runner.compileModelProtocolProjection(brief, results, phase, RunPolicy{}, true)

	if !ok {
		ginkgo.Fail("expected history-pending model protocol projection to compile", 1)
	}

	if !slices.Contains(protocol.CallableActionClasses, actionRead) {
		ginkgo.Fail(fmt.Sprintf("history-pending protocol should expose history tools as read actions: %#v", protocol.CallableActionClasses), 1)
	}

	for _, tool := range []string{"blame_range", "context_impact", "harness_feedback", "history_range", "history_symbol"} {
		if !slices.Contains(protocol.VisibleTools, tool) {
			ginkgo.Fail(fmt.Sprintf("history-pending protocol should preserve visible planner tool %s: %#v", tool, protocol.VisibleTools), 1)
		}

		if !slices.Contains(protocol.CallableTools, tool) {
			ginkgo.Fail(fmt.Sprintf("history-pending protocol should preserve callable planner tool %s: %#v", tool, protocol.CallableTools), 1)
		}
	}

	if slices.Contains(protocol.VisibleTools, "submit_plan") || slices.Contains(protocol.CallableTools, "submit_plan") {
		ginkgo.Fail(fmt.Sprintf("history-pending protocol must not expose submit_plan before history evidence, visible=%#v callable=%#v", protocol.VisibleTools, protocol.CallableTools), 1)
	}

	if slices.Contains(protocol.StructuredSchemaNames, "submit_plan") {
		ginkgo.Fail(fmt.Sprintf("history-pending protocol must not expose submit_plan schema before history evidence: %#v", protocol.StructuredSchemaNames), 1)
	}

	if !slices.Equal(protocol.PendingGitHistoryPaths, []string{"a.go"}) {
		ginkgo.Fail(fmt.Sprintf("pending git history paths = %#v, want a.go", protocol.PendingGitHistoryPaths), 1)
	}

	if len(protocol.CompletedGitHistoryPaths) != 0 {
		ginkgo.Fail(fmt.Sprintf("completed git history paths should be empty before history evidence: %#v", protocol.CompletedGitHistoryPaths), 1)
	}

	if slices.Contains(protocol.CallableActionClasses, "history") {
		ginkgo.Fail(fmt.Sprintf("history-pending protocol should not expose non-canonical history action class: %#v", protocol.CallableActionClasses), 1)
	}

	if slices.Contains(protocol.InvalidActionClasses, actionRead) {
		ginkgo.Fail(fmt.Sprintf("history-pending protocol should not invalidate read action class: %#v", protocol.InvalidActionClasses), 1)
	}
})

