var _ = ginkgo.It("RunnerAutonomyRecorderRejectedCompletionEmitsGuardFriction", func() {
	t := ginkgo.GinkgoT()
	var runEvents []RunEvent

	runner := newRunnerRunFixture(&Runner{
		AgentName: "main",
		OnEvent: func(event RunEvent) {
			runEvents = append(runEvents, event)
		},
		RuntimeBrief: workerruntime.WorkerRuntimeBrief{
			Lane:              "plan-execute",
			TaskFamily:        PlanThenExecutePlannerTaskFamily,
			Contract:          "submit_plan",
			PermissionProfile: "guarded_workspace_write",
			RequiredEditPaths: []string{"a.go"},
			AllowedTools:      []string{"read_file", "submit_plan"},
			RequiredTools:     []string{"submit_plan"},
		},
	})
	results := []workspace.ToolResult{{Tool: "read_file", Summary: "Read f1 a.go lines 1-10 (total lines: 10)"}}
	recorder := newRunnerAutonomyRecorder(runner, RunPolicy{MaxToolSteps: 2}, runner.state.runtimeBrief, results)

	if recorder == nil {
		ginkgo.Fail("newRunnerAutonomyRecorder returned nil", 1)
	}

	recorder.emitContractStarted(runner.state.runtimeBrief)

	phase := deriveTurnPhaseContract(TurnPhaseContractInput{
		ContractID:         recorder.contract.ContractID,
		ModelCallID:        recorder.contract.ContractID + ":model_call_1",
		Step:               1,
		Brief:              runner.state.runtimeBrief,
		Results:            results,
		BaseAllowedTools:   []string{"submit_plan"},
		TextualToolParser:  true,
		VerificationStatus: "not_required",
	})
	protocol, ok := runner.compileModelProtocolProjection(runner.state.runtimeBrief, results, phase, RunPolicy{MaxToolSteps: 2}, false)

	if !ok {
		ginkgo.Fail("expected plan-execute model protocol projection", 1)
	}

	recorder.emitTurnPhaseContract(phase, protocol)
	recorder.emitCompletionGateAttempt(autonomy.PolicyReject, "required_obligations_open", results, 0)

	events := decodeRunnerAutonomyEventsForTest(t, runEvents)

	var (
		friction           *autonomy.ContractGuardFrictionEvent
		completionGate     *autonomy.ContractGateEvent
		completionDecision *autonomy.ContractCompletionEvent
	)

	for _, event := range events {
		if event.Type == autonomy.EventGuardFriction {
			friction = event.GuardFriction
		}

		if event.Type == autonomy.EventGateDecision && event.Gate != nil && event.Gate.Gate == autonomy.GateCompletion {
			completionGate = event.Gate
		}

		if event.Type == autonomy.EventCompletionGateDecision {
			completionDecision = event.Completion
		}
	}

	if friction == nil {
		ginkgo.Fail(fmt.Sprintf("expected guard friction event, got event roles=%#v", eventRolesFor(runEvents)), 1)
	}

	if completionGate == nil || completionGate.ProtocolHash != "" {
		ginkgo.Fail(fmt.Sprintf("completion gate must not claim a model-visible protocol hash without prompt presentation: %#v", completionGate), 1)
	}

	if completionDecision == nil {
		ginkgo.Fail(fmt.Sprintf("expected completion decision event: %#v", completionDecision), 1)
	}

	if completionDecision.ProtocolHash == "" {
		ginkgo.Fail(fmt.Sprintf("completion decision must carry stored protocol hash for audit correlation: %#v", completionDecision), 1)
	}

	if friction.GuardSurface != autonomy.GuardFrictionSurfaceCompletionGate ||
		friction.Decision != autonomy.GuardFrictionDecisionReject ||
		friction.FirstInvalidAction != actionFinalAnswer {

		ginkgo.Fail(fmt.Sprintf("unexpected completion friction classification: %#v", friction), 1)
	}

	if friction.ProtocolHash == "" || !friction.ModelContractVisible {
		ginkgo.Fail(fmt.Sprintf("completion friction must claim model-visible protocol when one was stored: protocol_hash=%q model_contract_visible=%v", friction.ProtocolHash, friction.ModelContractVisible), 1)
	}

	if !slices.Contains(friction.SafeAlternatives, actionRead) ||
		!slices.Contains(friction.SafeAlternatives, actionSourceSatisfied) ||
		!slices.Contains(friction.SafeAlternatives, actionBlocker) {

		ginkgo.Fail(fmt.Sprintf("friction should carry safe action alternatives: %#v", friction.SafeAlternatives), 1)
	}

	if strings.Contains(strings.Join(friction.EvidenceRefs, " "), "raw_prompt") {
		ginkgo.Fail(fmt.Sprintf("friction evidence refs leaked raw prompt marker: %#v", friction.EvidenceRefs), 1)
	}

	report := autonomy.AuditEvents(events, autonomy.EventAuditOptions{})
	if report.GuardFrictionCoverage.Total != 1 ||
		report.GuardFrictionCoverage.GuardSurfaceCounts[string(autonomy.GuardFrictionSurfaceCompletionGate)] != 1 {

		ginkgo.Fail(fmt.Sprintf("expected audit to group completion-gate friction, got %#v", report.GuardFrictionCoverage), 1)
	}
})

var _ = ginkgo.It("RunnerAutonomyFrictionFallbackUsesPhaseSafeActionAlternatives", func() {
	phase := TurnPhaseContract{
		PhaseID:          contractcompile.TurnPhaseImplementationWriteReady,
		TerminalOutcomes: []string{"<<QUESTION>>:"},
		AllowedTools:     []string{"read_file", "search_content", "apply_patch"},
		ActionPolicy: TurnActionClassPolicy{
			AllowedActionClasses: []string{actionRead, actionSearch, actionPerEditWrite, actionBlocker},
			InvalidActionClasses: []string{actionFinalAnswer, actionVerify},
			CallableToolNames:    []string{"read_file", "search_content", "apply_patch"},
		},
		RuntimeCall: RuntimeCallContract{
			ExpressibleActionClasses: []string{actionRead, actionSearch, actionPerEditWrite, actionBlocker},
		},
	}

	got := runnerAutonomyFrictionSafeAlternatives(contractcompile.ModelProtocolProjection{}, phase, false)

	for _, want := range []string{actionRead, actionSearch, actionPerEditWrite, actionBlocker} {
		if !slices.Contains(got, want) {
			ginkgo.Fail(fmt.Sprintf("safe alternatives = %#v, want %q", got, want), 1)
		}
	}
	if slices.Contains(got, "<<QUESTION>>:") {
		ginkgo.Fail(fmt.Sprintf("fallback safe alternatives should use action classes instead of terminal-only outcomes: %#v", got), 1)
	}
})

