func rawGateString(values map[string]any, key string) string {
	if values == nil {
		return ""
	}

	value, _ := values[key].(string)

	return strings.TrimSpace(value)
}

func rawGateStringSlice(values map[string]any, key string) []string {
	if values == nil {
		return nil
	}

	raw, _ := values[key].([]any)
	out := make([]string, 0, len(raw))

	for _, value := range raw {
		if text, ok := value.(string); ok && strings.TrimSpace(text) != "" {
			out = append(out, strings.TrimSpace(text))
		}
	}

	return out
}

func rawGateObservedFacts(values map[string]any) []string {
	if values == nil {
		return nil
	}

	raw, _ := values["observed_facts"].([]any)
	out := make([]string, 0, len(raw))

	for _, value := range raw {
		if fact, ok := value.(string); ok && strings.TrimSpace(fact) != "" {
			out = append(out, strings.TrimSpace(fact))
		}
	}

	return out
}

func rawObservedFactsContain(facts []string, want string) bool {
	for _, fact := range facts {
		if fact == want {
			return true
		}
	}

	return false
}

func rawObservedFactsContainPrefix(facts []string, prefix string) bool {
	for _, fact := range facts {
		if strings.HasPrefix(fact, prefix) {
			return true
		}
	}

	return false
}

func countObligationKind(obligations []autonomy.Obligation, kind autonomy.ObligationKind) int {
	count := 0

	for _, obligation := range obligations {
		if obligation.Kind == kind {
			count++
		}
	}

	return count
}

func hasPathRole(roles []autonomy.PathRole, kind autonomy.PathRoleKind, pattern string) bool {
	for _, role := range roles {
		if role.Role == kind && role.PathPattern == pattern {
			return true
		}
	}

	return false
}

func containsAutonomyCapability(values []autonomy.Capability, want autonomy.Capability) bool {
	for _, value := range values {
		if value == want {
			return true
		}
	}

	return false
}

func hasAutonomyObligationEvent(events []autonomy.Event, eventType autonomy.EventType, obligationID string) bool {
	for _, event := range events {
		if event.Type == eventType && event.Obligation != nil && event.Obligation.ObligationID == obligationID {
			return true
		}
	}

	return false
}

func hasUnresolvedAutonomyObligation(report autonomy.EventAuditReport, obligationID string) bool {
	for _, ref := range report.ObligationCoverage.UnresolvedObligations {
		if ref.ObligationID == obligationID {
			return true
		}
	}

	return false
}

func mustAutonomyPolicyEvent(t ginkgo.FullGinkgoTInterface, events []autonomy.Event, eventType autonomy.EventType, toolName string, result string) autonomy.Event {
	t.Helper()

	for _, event := range events {
		if event.Type != eventType || event.Policy == nil {
			continue
		}

		if toolName != "" && event.Policy.ToolName != toolName {
			continue
		}

		if result != "" && event.Policy.Result != result {
			continue
		}

		return event
	}

	ginkgo.Fail(fmt.Sprintf("missing policy event type=%q tool=%q result=%q in %#v", eventType, toolName, result, events), 1)

	return autonomy.Event{}
}

func mustAutonomyPolicyEventByInvariant(t ginkgo.FullGinkgoTInterface, events []autonomy.Event, eventType autonomy.EventType, invariantID string, result string) autonomy.Event {
	t.Helper()

	for _, event := range events {
		if event.Type != eventType || event.Policy == nil {
			continue
		}

		if event.Policy.InvariantID == invariantID && (result == "" || event.Policy.Result == result) {
			return event
		}
	}

	ginkgo.Fail(fmt.Sprintf("missing policy event type=%q invariant=%q result=%q in %#v", eventType, invariantID, result, events), 1)

	return autonomy.Event{}
}

func mustAutonomyPolicyEventByInvariantAndReason(t ginkgo.FullGinkgoTInterface, events []autonomy.Event, eventType autonomy.EventType, invariantID string, reasonCode string) autonomy.Event {
	t.Helper()

	for _, event := range events {
		if event.Type != eventType || event.Policy == nil {
			continue
		}

		if event.Policy.InvariantID != invariantID {
			continue
		}

		if event.Policy.ReasonCode != reasonCode {
			continue
		}

		return event
	}

	ginkgo.Fail(fmt.Sprintf("missing policy event type=%q invariant=%q reason=%q in %#v", eventType, invariantID, reasonCode, events), 1)

	return autonomy.Event{}
}

func policyEventPaths(policy *autonomy.ContractPolicyEvent) []string {
	if policy == nil {
		return nil
	}

	seen := make(map[string]struct{}, len(policy.PathRoles))

	var paths []string

	for _, match := range policy.PathRoles {
		if _, ok := seen[match.Path]; ok || match.Path == "" {
			continue
		}

		seen[match.Path] = struct{}{}
		paths = append(paths, match.Path)
	}

	return paths
}

func hasAuthoritySource(sources []autonomy.AuthoritySource, kind string, ref string, freshness autonomy.Freshness) bool {
	for _, source := range sources {
		if source.Kind == kind && source.Ref == ref && source.Freshness == freshness {
			return true
		}
	}

	return false
}

func collectRunnerEvents(events *[]RunEvent) func(RunEvent) {
	return func(event RunEvent) {
		*events = append(*events, event)
	}
}

func findEvent(events []RunEvent, role string) *RunEvent {
	for i := range events {
		if events[i].Role == role {
			return &events[i]
		}
	}

	return nil
}

var _ = ginkgo.It("EmitBriefAuditCapturesContractShape", func() {
	var events []RunEvent

	runner := newRunnerRunFixture(&Runner{
		OnEvent: collectRunnerEvents(&events),
		RuntimeBrief: workerruntime.WorkerRuntimeBrief{
			Lane:              "implement",
			TaskFamily:        "implementation",
			Contract:          "implementation_result",
			PermissionProfile: "guarded_workspace_write",
			Constraints:       []string{"exact_anchor_implementation"},
			RequiredEditPaths: []string{"a.go", "b.go"},
			RequiredEditSnippets: []plancontract.RequiredEditSnippet{
				{Path: "a.go", Content: "old"},
				{Path: "a.go", Content: "second snippet"},
				{Path: "b.go", Content: "new"},
			},
			TargetPacket: []string{"line one", "line two"},
			Readiness: &workerruntime.ReadinessState{
				ReadyToWrite:        true,
				ClosedClaims:        []string{"required_edit_paths_define_write_scope"},
				FurtherReadsRequire: "named_gap",
			},
		},
	})

	runner.emitBriefAudit(runner.state.runtimeBrief, nil)

	event := findEvent(events, "brief_audit")
	if event == nil {
		ginkgo.Fail("expected brief_audit event", 1)
	}

	var payload briefAuditEvent

	if err := json.Unmarshal([]byte(event.Content), &payload); err != nil {
		ginkgo.Fail(fmt.Sprintf("brief_audit payload not valid JSON: %v", err), 1)
	}

	if payload.RequiredEditSnippetsCount != 3 {
		ginkgo.Fail(fmt.Sprintf("snippet count: want 3, got %d", payload.RequiredEditSnippetsCount), 1)
	}

	if got := payload.RequiredEditSnippetPaths; len(got) != 2 || got[0] != "a.go" || got[1] != "b.go" {
		ginkgo.Fail(fmt.Sprintf("snippet paths should dedupe: %v", got), 1)
	}

	if !payload.ExactAnchorImplActive {
		ginkgo.Fail("exact_anchor_implementation_active should be true when constraint is set", 1)
	}

	if !payload.ReadinessReadyToWrite {
		ginkgo.Fail("readiness_ready_to_write should mirror brief readiness", 1)
	}

	if payload.TargetPacketLines != 2 {
		ginkgo.Fail(fmt.Sprintf("target_packet_lines: want 2, got %d", payload.TargetPacketLines), 1)
	}

	if payload.TargetPacketBytes == 0 {
		ginkgo.Fail("target_packet_bytes should be non-zero for a populated packet", 1)
	}
})

