var _ = ginkgo.It("RunnerExecutionStateApplyResultVerificationResetsVerificationGuards", func() {
	state := newRunnerExecutionState(false, 0)

	state.writesSinceVerification = 3

	budget := newRunnerRequestBudgetState(2)

	budget.readCallsSinceWrite = 4

	req := workspace.ToolRequest{Tool: "shell", Command: "go test ./..."}
	result := shellCommandResultForTest("go test ./...", "", "exit status 1")

	update := state.applyResult(req, result, "", nil, &budget)

	if !state.verificationAttempted {
		ginkgo.Fail("verificationAttempted = false, want true", 1)
	}

	if state.writesSinceVerification != 0 {
		ginkgo.Fail(fmt.Sprintf("writesSinceVerification = %d, want 0", state.writesSinceVerification), 1)
	}

	if !update.ResetVerificationGuards {
		ginkgo.Fail("ResetVerificationGuards = false, want true", 1)
	}

	if update.VerificationState != "failed" {
		ginkgo.Fail(fmt.Sprintf("VerificationState = %q, want failed", update.VerificationState), 1)
	}

	if update.VerificationDetail != "exit status 1" {
		ginkgo.Fail(fmt.Sprintf("VerificationDetail = %q, want exit status 1", update.VerificationDetail), 1)
	}

	if budget.readCallsSinceWrite != 0 {
		ginkgo.Fail(fmt.Sprintf("readCallsSinceWrite = %d, want 0", budget.readCallsSinceWrite), 1)
	}
})

