func newModelErrorClient(err error, modelCalls int) *llamamocks.MockLLMClient {
	ginkgo.GinkgoHelper()
	client := llamamocks.NewMockLLMClient(gomock.NewController(ginkgo.GinkgoT()))
	client.EXPECT().SupportsNativeTools().Return(false).AnyTimes()
	client.EXPECT().Backend().Return("test").AnyTimes()
	client.EXPECT().CompleteChatMessage(gomock.Any(), gomock.Any(), gomock.Any()).Return(llama.ChatMessage{}, err).MinTimes(1).MaxTimes(modelCalls)
	return client
}

