var _ = ginkgo.It("ShouldForceAnswerForPostCompletionVerificationCountsAndCutsOff", func() {
	runner := newRunnerRunFixture(&Runner{
		RuntimeBrief: workerruntime.WorkerRuntimeBrief{
			TaskFamily:           "implementation",
			Contract:             "implementation_result",
			PermissionProfile:    "guarded_workspace_write",
			RequiredEditPaths:    []string{"a.txt", "b.txt"},
			VerificationContract: "tests_passed_or_failed_or_skipped_with_blocker",
		},
	})
	// All required paths written.
	_, firstWrite := committedMutationResultForTest("a.txt")
	_, secondWrite := committedMutationResultForTest("b.txt")
	installMutationReceiptForTest(runner, firstWrite)
	installMutationReceiptForTest(runner, secondWrite)
	verification := shellCommandResultForTest("git diff --check -- a.txt b.txt", "", "")
	verification.Facts.VerificationEvidence = []toolfacts.VerificationEvidence{{
		Kind:  toolfacts.VerificationEvidenceGitDiffCheck,
		Paths: []string{"a.txt", "b.txt"},
	}}
	results := []workspace.ToolResult{
		firstWrite,
		secondWrite,
		verification,
	}
	counter := 0
	read := workspace.ToolRequest{Tool: "read_file", Path: "a.txt"}
	// First three calls increment the counter but do not yet trip.
	for i := 1; i <= postCompletionVerificationCutoff; i++ {
		if runner.shouldForceAnswerForPostCompletionVerification(read, results, &counter) {
			ginkgo.Fail(fmt.Sprintf("force-answer fired prematurely on call %d", i), 1)
		}

		if counter != i {
			ginkgo.Fail(fmt.Sprintf("counter want %d, got %d", i, counter), 1)
		}
	}

	// The next non-write call must trip the cutoff.
	if !runner.shouldForceAnswerForPostCompletionVerification(read, results, &counter) {
		ginkgo.Fail(fmt.Sprintf("force-answer should fire after %d non-write calls", postCompletionVerificationCutoff+1), 1)
	}
})

