var _ = ginkgo.It("RunnerCompactionSummaryPreservesMergedSourceCoverage", func() {
	t := ginkgo.GinkgoT()
	root := t.TempDir()
	catalogLines := make([]string, 517)
	for i := range catalogLines {
		catalogLines[i] = fmt.Sprintf("// catalog line %d", i+1)
	}
	vocabularyLines := make([]string, 338)
	for i := range vocabularyLines {
		vocabularyLines[i] = fmt.Sprintf("// vocabulary line %d", i+1)
	}
	writeRunnerTestFile(t, root, "internal/runtime/workerruntime/catalog.go", strings.Join(catalogLines, "\n")+"\n")
	writeRunnerTestFile(t, root, "internal/runtime/workerruntime/vocabulary.go", strings.Join(vocabularyLines, "\n")+"\n")
	manager := workspace.NewManager(config.Workspace{Root: root, CWD: root, EnableWrites: true, MaxOutputBytes: 4 << 20})
	manager.SetPermissionRules(map[string][]toolpolicy.Rule{
		workspace.ToolNameReadFile: {{Pattern: "**", Decision: toolpolicy.Allow}},
	})
	runner := newRunnerRunFixture(&Runner{
		AgentName: "main",
		Workspace: manager,
		RuntimeBrief: workerruntime.WorkerRuntimeBrief{
			TaskFamily:        "implementation",
			Contract:          "implementation_result",
			PermissionProfile: "guarded_workspace_write",
			AllowedEditPaths:  []string{"internal/runtime/workerruntime/catalog.go"},
			TargetRefs:        []string{"internal/runtime/workerruntime/catalog.go"},
			RequiredEvidence:  []string{"changed_paths_or_noop_reason", "verification_status"},
		},
	})
	readWindow := func(path string, start, end int) workspace.ToolResult {
		result := manager.Execute(context.Background(), workspace.ToolRequest{
			Tool: workspace.ToolNameReadFile, Path: path, StartLine: start, EndLine: end,
		})
		if result.Error != "" || len(result.SourceWindows()) == 0 {
			ginkgo.Fail(fmt.Sprintf("read source window %s:%d-%d: %#v", path, start, end, result), 1)
		}
		return result
	}
	var results []workspace.ToolResult
	for start := 1; start <= 517; start += 80 {
		end := min(start+79, 517)
		results = append(results, readWindow("internal/runtime/workerruntime/catalog.go", start, end))
	}
	for start := 1; start <= 200; start += 80 {
		end := min(start+79, 200)
		results = append(results, readWindow("internal/runtime/workerruntime/vocabulary.go", start, end))
	}

	summary := runner.runnerCompactionSummary(RunPolicy{}, nil, results)

	for _, want := range []string{
		"Source coverage already read",
		"internal/runtime/workerruntime/catalog.go: lines 1-517; total lines 517; complete file read",
		"internal/runtime/workerruntime/vocabulary.go: lines 1-200; total lines 338",
	} {
		if !strings.Contains(summary, want) {
			ginkgo.Fail(fmt.Sprintf("expected compaction summary to contain %q, got:\n%s", want, summary), 1)
		}
	}
})

