var _ = ginkgo.It("RunnerRequestBudgetFingerprintDecisionWarnsThenBlocks", func() {
	t := ginkgo.GinkgoT()
	state := newRunnerRequestBudgetState(2)
	req := workspace.ToolRequest{Tool: "read_file", Path: "README.md"}
	fingerprint := "read_file|README.md"

	state.noteFingerprint(fingerprint)
	state.noteFingerprint(fingerprint)

	decision := attachLoopPolicyDecision(state.fingerprintDecision(RunPolicy{FingerprintNudgeAt: 2}, req, fingerprint))
	if !decision.Handled || decision.Nudge == "" || decision.EventRole != "fingerprint_nudge" {
		ginkgo.Fail(fmt.Sprintf("expected fingerprint nudge decision, got %#v", decision), 1)
	}
	assertLoopPolicyDecision(t, decision, autonomy.PolicyObserve, "fingerprint_nudge")

	state.noteFingerprint(fingerprint)

	decision = attachLoopPolicyDecision(state.fingerprintDecision(RunPolicy{FingerprintNudgeAt: 2}, req, fingerprint))
	if !decision.Handled || decision.ForceAnswerReason != "fingerprint_hard_block_exhausted" {
		ginkgo.Fail(fmt.Sprintf("expected hard block after repeated warned fingerprint, got %#v", decision), 1)
	}
	assertLoopPolicyDecision(t, decision, autonomy.PolicyStop, "fingerprint_hard_block")
})

var _ = ginkgo.It("PermissionDecisionFromAutonomyDoesNotReportObserveOnlyAsDeny", func() {
	for _, decision := range []autonomy.ToolPolicyDecision{autonomy.PolicyAllow, autonomy.PolicyObserve, autonomy.PolicyNudge} {
		if got := permissionDecisionFromAutonomy(decision); got != toolpolicy.Allow {
			ginkgo.Fail(fmt.Sprintf("%s mapped to %q, want %q", decision, got, toolpolicy.Allow), 1)
		}
	}

	if got := permissionDecisionFromAutonomy(autonomy.PolicyReject); got != toolpolicy.Deny {
		ginkgo.Fail(fmt.Sprintf("reject mapped to %q, want %q", got, toolpolicy.Deny), 1)
	}
})

func assertObserveOnlyLoopPolicyLegacyPermissionAllowed(t ginkgo.FullGinkgoTInterface, events []RunEvent) {
	t.Helper()

	allowCount := 0
	for _, event := range events {
		if event.Role != "permission_decision" || !strings.Contains(event.Content, `"rule":"runner_loop_policy"`) {
			continue
		}
		if strings.Contains(event.Content, `"decision":"deny"`) {
			ginkgo.Fail(fmt.Sprintf("observe-only loop policy nudge must not serialize as legacy deny: %s", event.Content), 1)
		}
		if strings.Contains(event.Content, `"decision":"allow"`) {
			allowCount++
		}
	}

	if allowCount == 0 {
		ginkgo.Fail(fmt.Sprintf("expected observe-only loop policy nudge to emit legacy allow permission_decision; events=%s", formatRunEventsForTest(events)), 1)
	}
}

var _ = ginkgo.It("RunnerRequestBudgetNudgesWithoutBlockingZeroHitSearchFamily", func() {
	t := ginkgo.GinkgoT()
	state := newRunnerRequestBudgetState(2)
	first := workspace.ToolRequest{Tool: "search_content", Path: ".", Pattern: "pkey.KeyArrowUp"}
	state.noteZeroHitSearch(first, "search_content|.|pkey.KeyArrowUp", workspace.ToolResult{
		Tool:    "search_content",
		Summary: `No content matches for "pkey.KeyArrowUp"`,
	})

	second := workspace.ToolRequest{Tool: "search_content", Path: ".", Pattern: "pkey.KeyArrowDown"}
	decision := attachLoopPolicyDecision(state.fingerprintDecision(RunPolicy{}, second, "search_content|.|pkey.KeyArrowDown"))

	if !decision.Handled || decision.EventRole != "zero_hit_family_nudge" || decision.Nudge == "" {
		ginkgo.Fail(fmt.Sprintf("expected same-family zero-hit nudge, got %#v", decision), 1)
	}
	assertLoopPolicyDecision(t, decision, autonomy.PolicyObserve, "zero_hit_family_nudge")

	state.noteZeroHitSearch(second, "search_content|.|pkey.KeyArrowDown", workspace.ToolResult{
		Tool:    "search_content",
		Summary: `No content matches for "pkey.KeyArrowDown"`,
	})

	third := workspace.ToolRequest{Tool: "search_content", Path: ".", Pattern: "key arrow"}

	decision = attachLoopPolicyDecision(state.fingerprintDecision(RunPolicy{}, third, "search_content|.|key arrow"))
	if decision.Handled {
		ginkgo.Fail(fmt.Sprintf("related zero-hit searches are advisory evidence, not execution authority; got %#v", decision), 1)
	}
})

var _ = ginkgo.It("WriteReadyNudgeActiveDefersRejectionRetry", func() {
	t := ginkgo.GinkgoT()
	state := newRunnerRequestBudgetState(2)

	state.writeReadyNudgeActive = true

	req := workspace.ToolRequest{Tool: "search_content", Path: "internal/surfaces/tui/app"}
	fingerprint := "search_content|internal/surfaces/tui/app"

	state.fingerprint.rejected[fingerprint] = rejectedFingerprint{Tool: req.Tool, Summary: "Chained search rejected"}
	state.fingerprint.rejectedRetries = make(map[string]int)

	decision := attachLoopPolicyDecision(state.fingerprintDecision(RunPolicy{}, req, fingerprint))
	if !decision.Handled {
		ginkgo.Fail("expected rejection retry to be handled", 1)
	}
	assertLoopPolicyDecision(t, decision, autonomy.PolicyObserve, "rejection_retry_deferred_to_write_ready")

	if decision.ForceAnswerReason != "" {
		ginkgo.Fail(fmt.Sprintf("expected nudge (not force-answer) when writeReadyNudgeActive, got ForceAnswerReason=%q", decision.ForceAnswerReason), 1)
	}

	if decision.EventRole != "rejection_retry_deferred_to_write_ready" {
		ginkgo.Fail(fmt.Sprintf("expected rejection_retry_deferred_to_write_ready event, got %q", decision.EventRole), 1)
	}

	if decision.Nudge == "" {
		ginkgo.Fail("expected a nudge message when writeReadyNudgeActive is true", 1)
	}

	t.Logf("nudge: %s", decision.Nudge)
})

// TestRejectionRetryNudgeThenBlock verifies the nudge-then-block pattern:
// first retry of a rejected fingerprint gets a nudge, second gets force-answered.
var _ = ginkgo.It("RejectionRetryNudgeThenBlock", func() {
	t := ginkgo.GinkgoT()
	state := newRunnerRequestBudgetState(2)
	req := workspace.ToolRequest{Tool: "list_files", Path: "."}
	fingerprint := "list_files|."

	state.fingerprint.rejected[fingerprint] = rejectedFingerprint{Tool: req.Tool, Summary: "Broad inspection blocked"}
	state.fingerprint.rejectedRetries = make(map[string]int)

	// First retry: nudge
	d1 := attachLoopPolicyDecision(state.fingerprintDecision(RunPolicy{}, req, fingerprint))
	if !d1.Handled || d1.Nudge == "" {
		ginkgo.Fail(fmt.Sprintf("expected nudge on first retry, got %#v", d1), 1)
	}
	assertLoopPolicyDecision(t, d1, autonomy.PolicyObserve, "rejection_retry_nudge")

	if d1.ForceAnswerReason != "" {
		ginkgo.Fail(fmt.Sprintf("expected nudge (not force-answer) on first retry, got ForceAnswerReason=%q", d1.ForceAnswerReason), 1)
	}

	t.Log("first retry: nudge")

	// Second retry: blocked
	d2 := attachLoopPolicyDecision(state.fingerprintDecision(RunPolicy{}, req, fingerprint))
	if !d2.Handled || d2.ForceAnswerReason != "rejection_retry_blocked" {
		ginkgo.Fail(fmt.Sprintf("expected force-answer on second retry, got %#v", d2), 1)
	}
	assertLoopPolicyDecision(t, d2, autonomy.PolicyStop, "rejection_retry_blocked")

	t.Log("second retry: blocked")
})

// TestNoteWriteProgressClearsWriteReadyNudgeAndRejectionState verifies
// that noteWriteProgress clears writeReadyNudgeActive and stale fingerprint
// state from the prior workspace evidence epoch.
var _ = ginkgo.It("NoteWriteProgressClearsWriteReadyNudgeAndRejectionState", func() {
	state := newRunnerRequestBudgetState(2)

	state.writeReadyNudgeActive = true
	state.fingerprint.rejected["fp"] = rejectedFingerprint{Summary: "test rejection"}
	state.fingerprint.rejectedRetries = map[string]int{"fp": 3}
	state.fingerprint.zeroHit["search"] = "no matches"
	state.fingerprint.zeroHitFamily["search-family"] = zeroHitFamilyState{Count: 2, NudgeFired: true}

	state.noteWriteProgress()

	if state.writeReadyNudgeActive {
		ginkgo.Fail("writeReadyNudgeActive should be false after noteWriteProgress", 1)
	}

	if _, ok := state.fingerprint.rejected["fp"]; ok {
		ginkgo.Fail("rejected fingerprints should be cleared after noteWriteProgress", 1)
	}

	if _, ok := state.fingerprint.rejectedRetries["fp"]; ok {
		ginkgo.Fail("rejectedRetries should be cleared after noteWriteProgress", 1)
	}

	if len(state.fingerprint.zeroHit) != 0 || len(state.fingerprint.zeroHitFamily) != 0 {
		ginkgo.Fail(fmt.Sprintf("zero-hit fingerprints from the prior mutation epoch should be cleared: exact=%#v family=%#v", state.fingerprint.zeroHit, state.fingerprint.zeroHitFamily), 1)
	}
})

func assertLoopPolicyDecision(t ginkgo.FullGinkgoTInterface, decision runnerRequestBudgetDecision, wantDecision autonomy.ToolPolicyDecision, wantReason string) {
	t.Helper()

	if decision.Policy.ContractID != autonomy.ContractPackLoopRepeatedCall {
		ginkgo.Fail(fmt.Sprintf("expected loop contract pack %q, got %#v", autonomy.ContractPackLoopRepeatedCall, decision.Policy), 1)
	}
	if decision.Policy.InvariantID != loopPolicyInvariantRepeatedCall {
		ginkgo.Fail(fmt.Sprintf("expected invariant %q, got %#v", loopPolicyInvariantRepeatedCall, decision.Policy), 1)
	}
	if decision.Policy.Decision != wantDecision {
		ginkgo.Fail(fmt.Sprintf("expected policy decision %q, got %#v", wantDecision, decision.Policy), 1)
	}
	if decision.Policy.ReasonCode != wantReason {
		ginkgo.Fail(fmt.Sprintf("expected reason %q, got %#v", wantReason, decision.Policy), 1)
	}
}

