var _ = ginkgo.It("ShellSanityCommandsCountAsVerification", func() {
	req := workspace.ToolRequest{Tool: "shell", Command: "git diff --check"}
	if !workspace.AnalyzeVerificationRequest(req).Attempted {
		ginkgo.Fail("git diff --check should count as a verification request after writes", 1)
	}

	commandOnly := shellCommandResultForTest("git diff --check", "", "")
	if !hasSuccessfulVerificationResult([]workspace.ToolResult{commandOnly}) {
		ginkgo.Fail("a successful git diff --check should remain an observed verification result", 1)
	}
	if observed := workspace.AnalyzePostWriteVerificationResult(commandOnly, []string{"untracked.txt"}); observed.Successful || len(observed.CoveredPendingPaths) != 0 || observed.Coverage != workspace.VerificationCoverageUnresolved {

		ginkgo.Fail(fmt.Sprintf("git diff --check without producer-owned inspected paths must not cover a pending write: %#v", observed), 1)
	}

	gitCheck := shellCommandResultForTest("git diff --check", "", "")
	gitCheck.Facts.VerificationEvidence = []toolfacts.VerificationEvidence{{
		Kind:  toolfacts.VerificationEvidenceGitDiffCheck,
		Paths: []string{"tracked.txt"},
	}}
	if !hasSuccessfulVerificationResult([]workspace.ToolResult{gitCheck}) {
		ginkgo.Fail("git diff --check with producer-owned inspected paths should count as successful verification", 1)
	}

	state := newRunnerExecutionState(false, 0)

	state.writesSinceVerification = 2

	if state.shouldRequireVerification(req, workerruntime.WorkerRuntimeBrief{VerificationContract: "tests_passed_or_failed_or_skipped_with_blocker"}) {
		ginkgo.Fail("post-write verification gate should allow git diff --check", 1)
	}

	if !workspace.AnalyzeVerificationRequest(workspace.ToolRequest{Tool: "source_sanity", Path: "native/tests/test_cart_system.cpp"}).Attempted {
		ginkgo.Fail("source_sanity should count as a verification request", 1)
	}

	if !hasSuccessfulVerificationResult([]workspace.ToolResult{{Tool: "source_sanity", Summary: "Source sanity passed", Output: "native/tests/test_cart_system.cpp: no warnings or errors via cpp_diagnostics"}}) {
		ginkgo.Fail("compiler-backed source_sanity should count as verification", 1)
	}
})

