var _ = ginkgo.It("PatchHygieneDoesNotSatisfySourceEditCompletion", func() {
	const target = "native/tests/test_cart_system.cpp"
	runner := newRunnerRunFixture(&Runner{
		RuntimeBrief: workerruntime.WorkerRuntimeBrief{
			TaskFamily:           "implementation",
			Contract:             "implementation_result",
			VerificationContract: "tests_passed_or_failed_or_skipped_with_blocker",
		},
	})
	_, write := committedMutationResultForTest(target)
	installMutationReceiptForTest(runner, write)
	patchHygiene := shellCommandResultForTest("git diff --check -- "+target, "", "")
	patchHygiene.Facts.VerificationEvidence = []toolfacts.VerificationEvidence{{
		Kind:  toolfacts.VerificationEvidenceGitDiffCheck,
		Paths: []string{target},
	}}
	observedPatchHygiene := workspace.AnalyzePostWriteVerificationResult(patchHygiene, []string{target})
	gomega.Expect(observedPatchHygiene.Successful).To(gomega.BeTrue())
	gomega.Expect(observedPatchHygiene.PatchHygieneOnly).To(gomega.BeTrue())
	gomega.Expect(observedPatchHygiene.CoveredPendingPaths).To(gomega.Equal([]string{target}))

	results := []workspace.ToolResult{
		write,
		patchHygiene,
	}

	result, rejected := runner.mutationCompletionRejection("Changed paths:\n- "+target+"\n\nVerification: git diff --check passed.", results)
	gomega.Expect(rejected).To(gomega.BeTrue())
	gomega.Expect(result.Error).To(gomega.ContainSubstring("patch hygiene"))
	envelope, typed := completionGateRecoveryEnvelopeFromResult(result)
	gomega.Expect(typed).To(gomega.BeTrue())
	gomega.Expect(envelope.InvariantID).To(gomega.Equal(completionGateInvariantSemanticVerification))
	gomega.Expect(envelope.RecoveryKind).To(gomega.Equal(completionGateViolationVerification))
	gomega.Expect(envelope.PendingPaths).To(gomega.Equal([]string{target}))

	diagnostics := workspace.ToolResult{
		Tool:    "cpp_diagnostics",
		Summary: "Collected C++ diagnostics for 1 file(s).",
		Output:  target + ": no warnings or errors",
		Facts:   &toolfacts.ToolResultFacts{DiagnosticEvidencePaths: []string{target}},
	}
	gomega.Expect(workspace.AnalyzePostWriteVerificationResult(diagnostics, []string{target}).Successful).To(gomega.BeTrue())
	results = append(results, diagnostics)
	result, rejected = runner.mutationCompletionRejection("Changed paths:\n- "+target+"\n\nVerification: cpp_diagnostics passed.", results)
	gomega.Expect(rejected).To(gomega.BeFalse(), "compiler-backed diagnostics should satisfy source edit completion: %#v", result)
})

var _ = ginkgo.It("MutationCompletionGateRejectsBlockersNoneBeforeSourceVerification", func() {
	const target = "internal/labels/labels.go"
	runner := newRunnerRunFixture(&Runner{
		RuntimeBrief: workerruntime.WorkerRuntimeBrief{
			TaskFamily:           "implementation",
			Contract:             "implementation_result",
			VerificationContract: "tests_passed_or_failed_or_skipped_with_blocker",
		},
	})
	_, write := committedMutationResultForTest(target)
	installMutationReceiptForTest(runner, write)
	answer := "Changed paths:\n- " + target + "\n\nVerification: not run.\n\nBlockers: none."
	patchHygiene := shellCommandResultForTest("git diff --check -- "+target, "", "")
	patchHygiene.Facts.VerificationEvidence = []toolfacts.VerificationEvidence{{
		Kind:  toolfacts.VerificationEvidenceGitDiffCheck,
		Paths: []string{target},
	}}

	cases := []struct {
		name          string
		results       []workspace.ToolResult
		wantReason    string
		wantInvariant string
	}{
		{
			name: "patch hygiene only",
			results: []workspace.ToolResult{
				write,
				patchHygiene,
			},
			wantReason:    "patch hygiene",
			wantInvariant: completionGateInvariantSemanticVerification,
		},
		{
			name: "generic source sanity fallback",
			results: []workspace.ToolResult{
				write,
				{Tool: "source_sanity", Summary: "Source sanity passed for 1 file(s) (1 generic fallback)", Output: target + ": generic delimiter sanity passed via generic_source_sanity"},
			},
			wantReason:    "latest successful write",
			wantInvariant: completionGateInvariantPostWriteVerification,
		},
		{
			name: "failed verification",
			results: []workspace.ToolResult{
				write,
				shellCommandResultForTest("go test ./...", "", target+":4: undefined: missing"),
			},
			wantReason:    "latest successful write",
			wantInvariant: completionGateInvariantPostWriteVerification,
		},
	}
	for _, tc := range cases {
		ginkgo.By(tc.name, func() {
			result, rejected := runner.mutationCompletionRejection(answer, tc.results)
			gomega.Expect(rejected).To(gomega.BeTrue())
			gomega.Expect(result.Error).To(gomega.ContainSubstring(tc.wantReason))
			envelope, typed := completionGateRecoveryEnvelopeFromResult(result)
			gomega.Expect(typed).To(gomega.BeTrue())
			gomega.Expect(envelope.InvariantID).To(gomega.Equal(tc.wantInvariant))
			gomega.Expect(envelope.RecoveryKind).To(gomega.Equal(completionGateViolationVerification))
			gomega.Expect(envelope.PendingPaths).To(gomega.Equal([]string{target}))
		})
	}
})

