func writeRunnerTestFile(t ginkgo.FullGinkgoTInterface, root string, path string, content string) {
	t.Helper()

	abs := filepath.Join(root, filepath.FromSlash(path))
	if err := os.MkdirAll(filepath.Dir(abs), 0o755); err != nil {
		ginkgo.Fail(fmt.Sprintf("mkdir %s: %v", filepath.Dir(abs), err), 1)
	}

	if err := os.WriteFile(abs, []byte(content), 0o644); err != nil {
		ginkgo.Fail(fmt.Sprintf("write %s: %v", abs, err), 1)
	}
}

func initRunnerTestGitRepo(t ginkgo.FullGinkgoTInterface, root string) {
	t.Helper()

	ctx := context.Background()
	if _, err := gitstate.CombinedOutputText(ctx, root, "init"); err != nil {
		t.Skipf("git unavailable for diff-backed completion gate test: %v", err)
	}

	for _, args := range [][]string{
		{"config", "user.email", "test@example.com"},
		{"config", "user.name", "Test User"},
		{"add", "."},
		{"commit", "-m", "initial"},
	} {
		if _, err := gitstate.CombinedOutputText(ctx, root, args...); err != nil {
			ginkgo.Fail(fmt.Sprintf("git %s: %v", strings.Join(args, " "), err), 1)
		}
	}
}

