var _ = ginkgo.It("NoopWriteDoesNotCreatePendingVerification", func() {
	t := ginkgo.GinkgoT()
	root := t.TempDir()
	if err := writeTestFile(root, "temp.md", "temporary\n"); err != nil {
		ginkgo.Fail(fmt.Sprintf("write delete fixture: %v", err), 1)
	}
	manager := workspace.NewManager(config.Workspace{Root: root, CWD: root, EnableWrites: true})
	deleteResult := manager.Execute(context.Background(), workspace.ToolRequest{
		Tool:    workspace.ToolNameApplyPatch,
		Content: "*** Begin Patch\n*** Delete File: temp.md\n*** End Patch\n",
	})
	if deleteResult.Error != "" || deleteResult.CommitReceipt() == nil {
		ginkgo.Fail(fmt.Sprintf("produce delete mutation receipt: %#v", deleteResult), 1)
	}
	results := []workspace.ToolResult{
		deleteResult,
		{Tool: workspace.ToolNameApplyPatch, Summary: "apply_patch made no new changes (all sections were redundant)", Output: "skipped redundant delete temp.md"},
		{Tool: workspace.ToolNameSourceSanity, Summary: "Source sanity unavailable", Error: "stat temp.md: no such file or directory"},
	}
	brief := workerruntime.WorkerRuntimeBrief{
		TaskFamily:           "implementation",
		Contract:             "implementation_result",
		VerificationContract: "not_required_for_text_mutations",
	}

	if hasPendingVerificationAfterWrites(results, brief) {
		ginkgo.Fail("redundant no-op write after non-source delete must not create a verification obligation", 1)
	}

	if failed, ok := failedVerificationAfterLatestWrite(results, brief); ok {
		ginkgo.Fail(fmt.Sprintf("source_sanity failure after no-op duplicate delete must not count as failed post-write verification: %#v", failed), 1)
	}

	runner := newRunnerRunFixture(&Runner{Workspace: manager, RuntimeBrief: brief})
	installMutationReceiptForTest(runner, deleteResult)
	answer := "Deleted `temp.md`.\n\nChanged paths:\n- temp.md\n\nVerification: not required for this text mutation; source_sanity is inapplicable to the deleted non-source file."
	if result, rejected := runner.mutationCompletionRejection(answer, results); rejected {
		ginkgo.Fail(fmt.Sprintf("delete closeout should pass after no-op duplicate patch and missing-file source_sanity, got %#v", result), 1)
	}
})

