var _ = ginkgo.It("EscalateCompletionGateMessageTiers", func() {
	base := "workspace changes are present, but no successful verification result is present."

	// Tier 0 (first rejection): pass through unchanged.
	if got := escalateCompletionGateMessageWithSourceRecovery(base, 0, false, false); got != base {
		ginkgo.Fail(fmt.Sprintf("first rejection should pass through; got: %s", got), 1)
	}

	// Tier 1 (second rejection): report the exact total-attempt position.
	got := escalateCompletionGateMessageWithSourceRecovery(base, 1, false, false)
	for _, want := range []string{"[gate retry attempt 2]", "no successful verification result", "active completion contract"} {
		if !strings.Contains(got, want) {
			ginkgo.Fail(fmt.Sprintf("tier 1 expected to contain %q, got: %s", want, got), 1)
		}
	}

	// Tier 2 (third rejection): report the terminal budget position.
	got = escalateCompletionGateMessageWithSourceRecovery(base, 2, false, false)
	for _, want := range []string{"[gate retry attempt 3]", "active completion contract"} {
		if !strings.Contains(got, want) {
			ginkgo.Fail(fmt.Sprintf("tier 2 expected to contain %q, got: %s", want, got), 1)
		}
	}
	if strings.Contains(got, "tools disable") {
		ginkgo.Fail(fmt.Sprintf("tier 2 must not threaten tool disable; got: %s", got), 1)
	}

	// Empty base: no escalation (defensive).
	if got := escalateCompletionGateMessageWithSourceRecovery("", 5, false, false); got != "" {
		ginkgo.Fail(fmt.Sprintf("empty base should pass through unchanged, got: %q", got), 1)
	}

	// ── Non-source-grounding messages still get generic text ──────
	normalMsg := "the final answer did not satisfy the active blocker check; continue with concrete writes or a per-path blocker reason."
	got = escalateCompletionGateMessageWithSourceRecovery(normalMsg, 1, false, false)
	for _, want := range []string{"[gate retry attempt 2]", "valid recovery"} {
		if !strings.Contains(got, want) {
			ginkgo.Fail(fmt.Sprintf("non-source-grounding tier 1 expected to contain %q, got: %s", want, got), 1)
		}
	}
	got = escalateCompletionGateMessageWithSourceRecovery(normalMsg, 2, false, false)
	for _, want := range []string{"[gate retry attempt 3]", "valid recovery"} {
		if !strings.Contains(got, want) {
			ginkgo.Fail(fmt.Sprintf("non-source-grounding tier 2 expected to contain %q, got: %s", want, got), 1)
		}
	}
})

