var _ = ginkgo.It("TextualToolProtocolEntriesPrioritizeWriteAliasExamples", func() {
	brief := workerruntime.WorkerRuntimeBrief{
		AllowedTools: []string{
			"read_file",
			"code_navigate",
			"source_sanity",
			"context_status",
			"context_query",
			"context_zoom",
			"context_pack",
			"context_impact",
			"discovery_query",
			"structural_search",
			"mkdir",
			"edit_file",
			"write_file",
			"append_file",
			"apply_patch",
		},
		RequiredTools: []string{workspace.RequiredToolEditFileOrApplyPatch, workspace.RequiredToolSemanticDiscoveryOrNarrowReadForNamedGap},
		ToolManifest: workspace.BuildToolManifest([]string{
			"read_file",
			"code_navigate",
			"source_sanity",
			"context_status",
			"context_query",
			"context_zoom",
			"context_pack",
			"context_impact",
			"discovery_query",
			"structural_search",
			"mkdir",
			"edit_file",
			"write_file",
			"append_file",
			"apply_patch",
		}),
	}

	entries := textualToolProtocolEntries(brief)
	if len(entries) > 8 {
		ginkgo.Fail(fmt.Sprintf("expected textual protocol entries to honor cap, got %d entries", len(entries)), 1)
	}

	if len(entries) < 5 {
		ginkgo.Fail(fmt.Sprintf("expected write examples to be selected, got %#v", entries), 1)
	}

	for _, want := range []string{"edit_file", "write_file", "append_file", "apply_patch"} {
		found := false

		for _, entry := range entries {
			if entry.Tool != want {
				continue
			}

			found = true

			if strings.Contains(entry.Request, "relative/file") || strings.Contains(entry.Request, "replacement text") {
				ginkgo.Fail(fmt.Sprintf("%s textual protocol request should not expose placeholder JSON: %s", want, entry.Request), 1)
			}

			if !strings.Contains(strings.ToLower(entry.Purpose), "description") {
				ginkgo.Fail(fmt.Sprintf("%s textual protocol guidance must include description: %s", want, entry.Purpose), 1)
			}
		}

		if !found {
			ginkgo.Fail(fmt.Sprintf("expected textual protocol entries to include %s before read examples, got %#v", want, entries), 1)
		}
	}
})

var _ = ginkgo.It("PinnedPathsFromToolResultsRejectsToolJSONFragments", func() {
	paths := newToolResultEvidenceProjection([]workspace.ToolResult{
		{
			Tool:    "go_move_declarations",
			Summary: `Blocked go_move_declarations with path:"internal/surfaces/tui/app/analysis_agents.go" and moves: {destination:"internal/surfaces/tui/app/orchestration.go", pattern:"tag:foo"}.`,
			Output:  `{"tool":"go_move_declarations","path":"internal/surfaces/tui/app/analysis_agents.go:12:3","moves":[{"destination":"internal/surfaces/tui/app/implementation.go"}]}`,
			Error:   "internal/surfaces/tui/app/analysis_agents.go:12:3: move was outside approval scope",
		},
	}).pinnedPaths(8)

	if !slices.Contains(paths, "internal/surfaces/tui/app/analysis_agents.go") {
		ginkgo.Fail(fmt.Sprintf("expected source path to be pinned, got %#v", paths), 1)
	}

	for _, forbidden := range []string{"internal/surfaces/tui/app/orchestration.go", "internal/surfaces/tui/app/implementation.go"} {
		if slices.Contains(paths, forbidden) {
			ginkgo.Fail(fmt.Sprintf("destination path %s must not be pinned as context, got %#v", forbidden, paths), 1)
		}
	}

	for _, path := range paths {
		if strings.ContainsAny(path, "\"'\\{}[],:") {
			ginkgo.Fail(fmt.Sprintf("pinned path should be normalized, got %#v in %#v", path, paths), 1)
		}
	}
})

var _ = ginkgo.It("BuildRunnerNextActionStateKeepsAuthorizedDuplicateReadOutOfInvalidActions", func() {
	req := workspace.ToolRequest{Tool: "read_file", Path: "internal/surfaces/tui/app/app.go"}
	result := workspace.ToolResult{
		Tool:    "read_file",
		Summary: "Implementation bootstrap already inspected this target",
		Error:   "internal/surfaces/tui/app/app.go has already been read in the implementation bootstrap; use edit_file or a narrow line range instead",
		Output:  "internal/surfaces/tui/app/app.go: already inspected",
	}
	state, _ := buildRunnerNextActionStateWithAllowedToolsAndContract(
		"implement",
		3,
		"pre_execute_guard",
		req,
		result,
		[]workspace.ToolResult{result},
		true,
		workerruntime.WorkerRuntimeBrief{},
		nil,
	)

	if state.Lane != "implement" || state.Step != 3 || state.LastTool != "read_file" || state.LastTarget != "internal/surfaces/tui/app/app.go" {
		ginkgo.Fail(fmt.Sprintf("unexpected state identity: %#v", state), 1)
	}

	if !strings.Contains(strings.Join(state.Constraints, "\n"), "declaration_moves_forbidden") {
		ginkgo.Fail(fmt.Sprintf("expected declaration move constraint, got %#v", state.Constraints), 1)
	}

	if !strings.Contains(strings.Join(state.Constraints, "\n"), "bootstrap_evidence_available") {
		ginkgo.Fail(fmt.Sprintf("expected bootstrap evidence constraint, got %#v", state.Constraints), 1)
	}

	if strings.Contains(strings.Join(state.InvalidNextActions, "\n"), "duplicate_read_file_on_bootstrapped_target") {
		ginkgo.Fail(fmt.Sprintf("authorized duplicate read must not be declared invalid, got %#v", state.InvalidNextActions), 1)
	}

	actions := strings.Join(state.NextValidActions, "\n")
	if !strings.Contains(actions, "approved-target write capability") {
		ginkgo.Fail(fmt.Sprintf("expected edit guidance, got %#v", state.NextValidActions), 1)
	}

	if !strings.Contains(actions, "narrow range read") {
		ginkgo.Fail(fmt.Sprintf("expected narrow read guidance, got %#v", state.NextValidActions), 1)
	}
})

var _ = ginkgo.It("RunnerEmitsNextActionStateWithoutStrategyInvalidationAfterPreExecuteGuard", func() {
	t := ginkgo.GinkgoT()
	root := t.TempDir()
	if err := writeTestFile(root, "README.md", "hello\n"); err != nil {
		ginkgo.Fail(fmt.Sprintf("write seed file: %v", err), 1)
	}

	replies := []string{
		"```tool\n{\"tool\":\"read_file\",\"path\":\"README.md\"}\n```",
		"Blocked by the read guard.",
	}

	type requestPayload struct {
		Messages []llama.ChatMessage `json:"messages"`
	}

	var payloads []requestPayload

	requests := 0
	server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		defer ginkgo.GinkgoRecover()
		if requests >= len(replies) {
			ginkgo.Fail("unexpected extra chat request", 1)
		}

		var payload requestPayload

		if err := json.NewDecoder(r.Body).Decode(&payload); err != nil {
			ginkgo.Fail(fmt.Sprintf("decode request: %v", err), 1)
		}

		payloads = append(payloads, payload)

		reply := replies[requests]
		requests++

		_ = json.NewEncoder(w).Encode(map[string]any{
			"choices": []map[string]any{{
				"message": map[string]string{"content": reply},
			}},
		})
	}))

	defer server.Close()

	var (
		states           []runnerNextActionState
		feedback         []runnerFailureFeedbackPacket
		stepInstructions []string
	)

	runner := newRunnerRunFixture(&Runner{
		Client: llama.NewClient(server.URL, time.Second),
		Workspace: workspace.NewManager(config.Workspace{
			Root:         root,
			CWD:          root,
			EnableShell:  true,
			EnableWrites: true,
		}),
		Policy: RunPolicy{MaxToolSteps: 2, MaxNoProgressTurns: 2},
		PreExecute: func(step int, req workspace.ToolRequest) *workspace.ToolResult {
			if req.Tool != "read_file" {
				return nil
			}

			return &workspace.ToolResult{
				Tool:    req.Tool,
				Summary: "Implementation bootstrap already inspected this target",
				Error:   "README.md has already been read in the implementation bootstrap; approved-target write capability or a narrow line range remains available",
			}
		},
		OnEvent: func(event RunEvent) {
			switch event.Role {
			case "next_action_state":
				var state runnerNextActionState

				if err := json.Unmarshal([]byte(event.Content), &state); err != nil {
					ginkgo.Fail(fmt.Sprintf("decode next action state %q: %v", event.Content, err), 1)
				}

				states = append(states, state)
			case "failure_feedback":
				var packet runnerFailureFeedbackPacket

				if err := json.Unmarshal([]byte(event.Content), &packet); err != nil {
					ginkgo.Fail(fmt.Sprintf("decode failure feedback %q: %v", event.Content, err), 1)
				}

				feedback = append(feedback, packet)
			case "step_instruction":
				stepInstructions = append(stepInstructions, event.Content)
			default:
				return
			}
		},
	})

	answer, err := runner.runner.Run(
		context.Background(),
		[]llama.ChatMessage{{Role: "user", Content: "read README.md"}},
		llama.ChatOptions{},
		nil,
		nil,
		nil,
	)
	if err != nil {
		ginkgo.Fail(fmt.Sprintf("Run: %v", err), 1)
	}

	if answer != "Blocked by the read guard." {
		ginkgo.Fail(fmt.Sprintf("unexpected answer %q", answer), 1)
	}

	if len(states) != 1 {
		ginkgo.Fail(fmt.Sprintf("expected one next_action_state event, got %#v", states), 1)
	}

	state := states[0]
	if state.Reason != "pre_execute_guard" || state.LastTool != "read_file" || state.LastTarget != "README.md" {
		ginkgo.Fail(fmt.Sprintf("unexpected state: %#v", state), 1)
	}

	if !strings.Contains(strings.Join(state.NextValidActions, "\n"), "approved-target write capability") {
		ginkgo.Fail(fmt.Sprintf("expected edit guidance, got %#v", state.NextValidActions), 1)
	}

	if len(feedback) != 1 {
		ginkgo.Fail(fmt.Sprintf("expected one failure feedback packet, got %#v", feedback), 1)
	}

	if feedback[0].FailureClass != "guard_rejection" {
		ginkgo.Fail(fmt.Sprintf("expected frontier failure class, got %#v", feedback[0]), 1)
	}

	if !slices.Contains(feedback[0].DoNotRepeat, "same read_file request on README.md") {
		ginkgo.Fail(fmt.Sprintf("expected exact rejected request in do-not-repeat actions, got %#v", feedback[0]), 1)
	}

	if slices.Contains(feedback[0].InvalidNext, "duplicate_read_file_on_bootstrapped_target") {
		ginkgo.Fail(fmt.Sprintf("authorized duplicate reads must remain outside invalid-next authority, got %#v", feedback[0]), 1)
	}

	if len(stepInstructions) != 0 {
		ginkgo.Fail(fmt.Sprintf("step_instruction events were removed — expected none, got %#v", stepInstructions), 1)
	}

	if len(payloads) < 2 {
		ginkgo.Fail(fmt.Sprintf("expected second model request after guard, got %d", len(payloads)), 1)
	}

	var stepInstructionCount int

	for _, message := range payloads[1].Messages {
		if strings.Contains(message.Content, "[frontier step instruction]") {
			stepInstructionCount++
		}

		if strings.Contains(message.Content, "[failure feedback packet]") {
			ginkgo.Fail(fmt.Sprintf("second model request should not contain failure feedback packet: %q", message.Content), 1)
		}
	}

	if stepInstructionCount > 1 {
		ginkgo.Fail(fmt.Sprintf("expected at most one persisted frontier step instruction, got %d", stepInstructionCount), 1)
	}
})

var _ = ginkgo.It("RunnerPreservesReasoningContentBetweenToolTurns", func() {
	t := ginkgo.GinkgoT()
	root := t.TempDir()
	if err := writeTestFile(root, "README.md", "hello\n"); err != nil {
		ginkgo.Fail(fmt.Sprintf("write seed file: %v", err), 1)
	}

	type requestPayload struct {
		Messages []llama.ChatMessage `json:"messages"`
	}

	var payloads []requestPayload

	replies := []string{
		"{\"choices\":[{\"message\":{\"role\":\"assistant\",\"reasoning_content\":\"tool-call reasoning\",\"content\":\"```tool\\n{\\\"tool\\\":\\\"read_file\\\",\\\"path\\\":\\\"README.md\\\"}\\n```\"}}]}",
		`{"choices":[{"message":{"role":"assistant","content":"Done."}}]}`,
	}
	server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		defer ginkgo.GinkgoRecover()
		var payload requestPayload

		if err := json.NewDecoder(r.Body).Decode(&payload); err != nil {
			ginkgo.Fail(fmt.Sprintf("decode request: %v", err), 1)
		}

		payloads = append(payloads, payload)
		if len(payloads) > len(replies) {
			ginkgo.Fail("unexpected extra chat request", 1)
		}

		_, _ = w.Write([]byte(replies[len(payloads)-1]))
	}))

	defer server.Close()

	enableThinking := true

	var thinkingEvents []runnerThinkingTrace

	runner := newRunnerRunFixture(&Runner{
		Client: llama.NewClient(server.URL, time.Second),
		Workspace: workspace.NewManager(config.Workspace{
			Root: root,
			CWD:  root,
		}),
		Policy: RunPolicy{MaxToolSteps: 3, MaxNoProgressTurns: 2},
		OnEvent: func(event RunEvent) {
			if event.Role != "thinking_trace" {
				return
			}

			var trace runnerThinkingTrace

			if err := json.Unmarshal([]byte(event.Content), &trace); err != nil {
				ginkgo.Fail(fmt.Sprintf("decode thinking trace %q: %v", event.Content, err), 1)
			}

			thinkingEvents = append(thinkingEvents, trace)
		},
	})

	answer, err := runner.runner.Run(
		context.Background(),
		[]llama.ChatMessage{{Role: "user", Content: "read README.md"}},
		llama.ChatOptions{Model: "model", EnableThinking: &enableThinking, PreserveThinking: true, MaxTokens: 128},
		nil,
		nil,
		nil,
	)
	if err != nil {
		ginkgo.Fail(fmt.Sprintf("Run: %v", err), 1)
	}

	if answer != "Done." {
		ginkgo.Fail(fmt.Sprintf("unexpected answer %q", answer), 1)
	}

	if len(payloads) != 2 {
		ginkgo.Fail(fmt.Sprintf("expected two model requests, got %d", len(payloads)), 1)
	}

	var foundPreserved bool

	for _, message := range payloads[1].Messages {
		if message.Role == "assistant" && message.ReasoningContent == "tool-call reasoning" {
			foundPreserved = true
			break
		}
	}

	if !foundPreserved {
		ginkgo.Fail(fmt.Sprintf("expected second request to include prior assistant reasoning_content, got %#v", payloads[1].Messages), 1)
	}

	var sawPreservedTrace bool

	for _, trace := range thinkingEvents {
		if trace.ReasoningChars > 0 && trace.PreservedInHistory {
			sawPreservedTrace = true
			break
		}
	}

	if !sawPreservedTrace {
		ginkgo.Fail(fmt.Sprintf("expected thinking_trace to report preserved reasoning, got %#v", thinkingEvents), 1)
	}
})

