var _ = ginkgo.It("ReadOnlyChildTaskPermissionPolicyDeniesWritesAndAllowsReads", func() {
	policy := readOnlyChildTaskPermissionPolicy()
	if decision := permissionPolicyDecision(nil, policy, workspace.ToolRequest{Tool: "edit_file", Path: "README.md"}); decision.Decision != toolpolicy.Deny {
		ginkgo.Fail(fmt.Sprintf("edit_file decision = %q, want deny", decision.Decision), 1)
	}

	if decision := permissionPolicyDecision(nil, policy, workspace.ToolRequest{Tool: "read_file", Path: "README.md"}); decision.Decision != toolpolicy.Allow {
		ginkgo.Fail(fmt.Sprintf("read_file decision = %q, want allow", decision.Decision), 1)
	}

	if decision := permissionPolicyDecision(nil, policy, workspace.ToolRequest{Tool: workspace.ToolNameShell, Command: "git diff -- README.md"}); decision.Decision != toolpolicy.Allow {
		ginkgo.Fail(fmt.Sprintf("git diff decision = %q, want allow", decision.Decision), 1)
	}

	for _, command := range []string{"git diff --output=/tmp/patch", "git diff --output /tmp/patch"} {
		if decision := permissionPolicyDecision(nil, policy, workspace.ToolRequest{Tool: workspace.ToolNameShell, Command: command}); decision.Decision != toolpolicy.Deny {
			ginkgo.Fail(fmt.Sprintf("%q decision = %q, want deny; snapshot=%#v", command, decision.Decision, decision), 1)
		}
	}

	if decision := permissionPolicyDecision(nil, policy, workspace.ToolRequest{Tool: "task", Prompt: "nested"}); decision.Decision != toolpolicy.Deny {
		ginkgo.Fail(fmt.Sprintf("task decision = %q, want deny", decision.Decision), 1)
	}
})

