var _ = ginkgo.It("FailureFeedbackPacketKeepsRepeatedActionClosureBiased", func() {
	results := []workspace.ToolResult{{
		Tool:    "discovery_query",
		Summary: "Ran architecture_boundary discovery query",
		Output:  `{"artifact_path":".idiom/discovery/queries/query.json","evidence":[{"path":"internal/runtime/agent/runner_core.go","excerpt":"result := r.runChildTask(ctx, req, opts)"},{"path":"internal/runtime/agent/implementation_flow.go","excerpt":"You are a read-only delegated child task."}]}`,
	}}
	req := workspace.ToolRequest{Tool: "read_file", Path: "internal/runtime/agent/implementation_flow.go"}
	result := workspace.ToolResult{
		Tool:    "read_file",
		Summary: "Repeated tool request rejected",
		Error:   "you just ran the same tool request. Either answer with what you already know, or take one materially different narrow step that names the exact missing claim it closes.",
	}
	packet := buildRunnerFailureFeedbackPacketWithAllowedToolsAndTransport(
		"child:explorer",
		3,
		"tool_rejected",
		req,
		result,
		results,
		false,
		workerruntime.WorkerRuntimeBrief{
			TaskFamily: "delegated_read_only",
			Objective:  "Explain how this harness uses subagents.",
		},
		nil,
		PlanExecutePlanningTransport{TextualToolParser: true},
		implementationCompletionState{}, planThenExecutePathAuthority{})

	joined := strings.Join(append(append([]string{}, packet.RequiredNext...), packet.ValidNext...), "\n")

	for _, want := range []string{
		"answer from the current evidence",
		"one exact tool-shaped follow-up",
		"concrete missing claim",
	} {
		if !strings.Contains(joined, want) {
			ginkgo.Fail(fmt.Sprintf("expected closure-biased failure feedback to contain %q, got %#v", want, packet), 1)
		}
	}

	for _, forbidden := range []string{"search_files on a discovered path or pattern", "use a targeted read-only shell search"} {
		if strings.Contains(joined, forbidden) {
			ginkgo.Fail(fmt.Sprintf("failure feedback should not reintroduce broad fallback %q, got %#v", forbidden, packet), 1)
		}
	}
})

var _ = ginkgo.It("DebugLogEvidenceSatisfiedAfterSingleHitAndReadWindow", func() {
	t := ginkgo.GinkgoT()
	root := t.TempDir()
	if err := writeTestFile(root, "logs/llama-server.log", "context setup\nrequest exceeds context\n"); err != nil {
		ginkgo.Fail(fmt.Sprintf("write log fixture: %v", err), 1)
	}
	manager := workspace.NewManager(config.Workspace{Root: root, CWD: root})
	logRead := manager.Execute(context.Background(), workspace.ToolRequest{
		Tool: workspace.ToolNameReadFile, Path: "logs/llama-server.log", StartLine: 1, EndLine: 2,
	})
	if logRead.Error != "" || logRead.Facts == nil || len(logRead.Facts.DiagnosticLogReads) == 0 {
		ginkgo.Fail(fmt.Sprintf("read typed log window: %#v", logRead), 1)
	}
	if paths := newToolResultEvidenceRecord(logRead).ReadPaths(); !slices.Equal(paths, []string{"logs/llama-server.log"}) {
		ginkgo.Fail(fmt.Sprintf("typed diagnostic-log fact did not project its canonical read path: %#v", paths), 1)
	}
	brief := workerruntime.WorkerRuntimeBrief{TaskFamily: "debug_logs", Contract: "direct_answer", PermissionProfile: "read_only_workspace", Objective: "Inspect the newest debug log for why the run failed."}
	results := []workspace.ToolResult{
		{
			Tool:    "search_content",
			Summary: "Found 1 matching line at logs/llama-server.log:2.",
			Output:  "f3 logs/llama-server.log:2:request exceeds context\ncontext:\n1:context setup",
		},
		logRead,
	}

	if !debugLogEvidenceSatisfied(brief, results) {
		ginkgo.Fail(fmt.Sprintf("expected debug-log evidence to be satisfied for %#v", results), 1)
	}
})

var _ = ginkgo.It("DiagnosticLogIntentDistinguishesSourceFeatureQuestions", func() {
	sourceQuestion := strings.Join([]string{
		"Investigate what \"debug log redacted mode\" does in this codebase.",
		"Where is redacted mode defined for debug logging?",
		"What configuration or flag controls it?",
		"What does it do when enabled and where is the redaction logic applied?",
		"Search broadly in Go files and debug log configuration types.",
	}, "\n")
	if objectiveRequestsDiagnosticLogInspection(sourceQuestion) {
		ginkgo.Fail("debug-log mode source feature question must not activate diagnostic-log artifact scope", 1)
	}

	if !objectiveRequestsDiagnosticLogInspection("Inspect the newest debug log for why the run failed.") {
		ginkgo.Fail("newest debug log failure request should still activate diagnostic-log artifact scope", 1)
	}

	optionalLogsQuestion := "Read-only RCA request: investigate the reported TUI behavior bug where pressing up/down arrow keys no longer updates the input. Use repository evidence and newest relevant logs if available. Do not edit files."
	if !objectiveRequestsDiagnosticLogInspection(optionalLogsQuestion) {
		ginkgo.Fail("optional logs source-RCA question should still be recognized as mentioning diagnostic logs", 1)
	}

	if !objectiveTreatsDiagnosticLogsAsOptionalEvidence(optionalLogsQuestion) {
		ginkgo.Fail("optional logs source-RCA question should mark logs as supporting evidence, not exclusive scope", 1)
	}
})

