var _ = ginkgo.It("ForcedCompletionTreatsXMLToolMarkupAsToolRequest", func() {
	t := ginkgo.GinkgoT()
	root := t.TempDir()
	if err := writeTestFile(root, "README.md", "hello\n"); err != nil {
		ginkgo.Fail(fmt.Sprintf("write seed file: %v", err), 1)
	}

	replies := []string{
		`{"tool":"read_file","path":"README.md"}`,
		"<tool_call>\n<function=read_file>\n<parameter=path>README.md</parameter>\n</function>\n</tool_call>",
		"README.md was inspected and contains the gathered evidence needed for this answer.",
	}
	requests := 0
	server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		defer ginkgo.GinkgoRecover()
		if requests >= len(replies) {
			ginkgo.Fail("unexpected extra chat request", 1)
		}

		reply := replies[requests]
		requests++

		_ = json.NewEncoder(w).Encode(map[string]any{
			"choices": []map[string]any{{
				"message": map[string]string{"content": reply},
			}},
		})
	}))

	defer server.Close()

	runner := newRunnerRunFixture(&Runner{
		Client: llama.NewClient(server.URL, time.Second),
		Workspace: workspace.NewManager(config.Workspace{
			Root: root,
			CWD:  root,
		}),
		Policy: RunPolicy{MaxToolSteps: 1, MaxNoProgressTurns: 2},
	})

	answer, err := runner.runner.Run(
		context.Background(),
		[]llama.ChatMessage{{Role: "user", Content: "inspect once then answer"}},
		llama.ChatOptions{},
		nil,
		nil,
		nil,
	)
	if err != nil {
		ginkgo.Fail(fmt.Sprintf("Run: %v", err), 1)
	}

	if strings.Contains(answer, "<tool_call>") || !strings.Contains(answer, "README.md was inspected") {
		ginkgo.Fail(fmt.Sprintf("expected repaired prose answer instead of XML tool markup, got:\n%s", answer), 1)
	}

	if strings.Contains(answer, "Partial findings") {
		ginkgo.Fail(fmt.Sprintf("expected normal evidence answer without partial-findings banner, got:\n%s", answer), 1)
	}

	if requests != len(replies) {
		ginkgo.Fail(fmt.Sprintf("expected invalid final answer retry, got %d requests", requests), 1)
	}
})

