var _ = ginkgo.It("ScopedImplementationFinalModelSlotKeepsReadsVisibleBeforeBudgetExhaustion", func() {
	t := ginkgo.GinkgoT()
	root := t.TempDir()
	if err := writeTestFile(root, "a.txt", "before\nmore\n"); err != nil {
		ginkgo.Fail(fmt.Sprintf("write a: %v", err), 1)
	}

	requests := 0
	thirdRequestChecked := false
	thirdToolNames := []string{}
	server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		defer ginkgo.GinkgoRecover()
		var body struct {
			Tools []llama.Tool `json:"tools,omitempty"`
		}

		if err := json.NewDecoder(r.Body).Decode(&body); err != nil {
			ginkgo.Fail(fmt.Sprintf("decode request body: %v", err), 1)
		}

		requests++
		switch requests {
		case 1:
			_ = json.NewEncoder(w).Encode(map[string]any{
				"choices": []map[string]any{{"message": map[string]string{"content": `{"tool":"read_file","path":"a.txt","start_line":1,"end_line":1}`}}},
			})
		case 2:
			_ = json.NewEncoder(w).Encode(map[string]any{
				"choices": []map[string]any{{"message": map[string]string{"content": `{"tool":"read_file","path":"a.txt","start_line":2,"end_line":2}`}}},
			})
		case 3:
			thirdRequestChecked = true

			for _, tool := range body.Tools {
				thirdToolNames = append(thirdToolNames, tool.Function.Name)
			}

			for _, want := range []string{"read_file", "code_navigate"} {
				if !slices.Contains(thirdToolNames, want) {
					ginkgo.Fail(fmt.Sprintf("final available model slot must keep genuine discovery tool %q visible, got %#v", want, thirdToolNames), 1)
				}
			}

			_ = json.NewEncoder(w).Encode(map[string]any{
				"choices": []map[string]any{{"message": map[string]string{"content": `{"tool":"read_file","path":"a.txt","start_line":1,"end_line":2}`}}},
			})
		default:
			ginkgo.Fail(fmt.Sprintf("unexpected extra chat request %d", requests), 1)
		}
	}))

	defer server.Close()

	var sawLastChance bool

	runner := newRunnerRunFixture(&Runner{
		Client: llama.NewClient(server.URL, time.Second),
		Workspace: workspace.NewManager(config.Workspace{
			Root:         root,
			CWD:          root,
			EnableWrites: true,
		}),
		Policy: RunPolicy{MaxToolSteps: 8, MaxNoProgressTurns: 8, MaxOperationalModelCalls: 3},
		RuntimeBrief: workerruntime.WorkerRuntimeBrief{
			TaskFamily:           "implementation",
			Contract:             "implementation_result",
			PermissionProfile:    "guarded_workspace_write",
			VerificationContract: "not_required_for_text_mutations",
			RequiredEditPaths:    []string{"a.txt"},
			AllowedTools:         []string{"read_file", "search_content", "code_navigate", "write_file", "edit_file", "apply_patch"},
		},
		OnEvent: func(event RunEvent) {
			if event.Role == "implementation_scoped_last_chance_write_only" {
				sawLastChance = true
			}
		},
	})

	answer, err := runner.runner.Run(
		context.Background(),
		[]llama.ChatMessage{{Role: "user", Content: "Update a.txt."}},
		llama.ChatOptions{},
		nil,
		nil,
		nil,
	)
	if err != nil {
		ginkgo.Fail(fmt.Sprintf("Run: %v", err), 1)
	}

	if !thirdRequestChecked {
		ginkgo.Fail("expected third model call to exercise final available model slot", 1)
	}

	if sawLastChance {
		ginkgo.Fail("final available model slot must not activate implementation_scoped_last_chance_write_only", 1)
	}

	for _, want := range []string{
		"<<QUESTION>>: implementation closeout reached",
		"Changed paths: none",
		"required edit path(s) not changed: a.txt",
	} {
		if !strings.Contains(answer, want) {
			ginkgo.Fail(fmt.Sprintf("expected deterministic incomplete-implementation blocker to contain %q, got %q", want, answer), 1)
		}
	}

	if requests != 3 {
		ginkgo.Fail(fmt.Sprintf("expected exactly three model requests, got %d", requests), 1)
	}
})

