var _ = ginkgo.It("WriteReadyPacketAllowsReadOnCompletedRequiredPathWithGap", func() {
	t := ginkgo.GinkgoT()
	// Multi-file scenario: a.txt then b.txt are required. Model writes a.txt,
	// then reads a.txt (now a completed path) with named_gap to set up the
	// b.txt write. Pre-fix this read was rejected because the path dropped
	// out of remainingRequiredEditPaths after the first write. Post-fix the
	// read scope is the brief's full required_edit_paths set, so reads on
	// completed paths within the working set are allowed (when they include
	// named_gap).
	root := t.TempDir()
	for _, path := range []string{"a.txt", "b.txt"} {
		if err := writeTestFile(root, path, "before\n"); err != nil {
			ginkgo.Fail(fmt.Sprintf("write %s: %v", path, err), 1)
		}
	}

	replies := []string{
		`{"tool":"read_file","path":"a.txt","start_line":1,"end_line":1,"named_gap":"current line to replace in a.txt","why_not_answering":"the edit needs current source evidence"}`,
		`{"tool":"edit_file","path":"a.txt","old_text":"before","new_text":"after a","description":"update first required path"}`,
		`{"tool":"read_file","path":"a.txt","start_line":1,"end_line":1,"named_gap":"verify the line a.txt now exposes so b.txt can mirror its structure","why_not_answering":"b.txt's edit must mirror the freshly-landed a.txt content"}`,
		`{"tool":"read_file","path":"b.txt","start_line":1,"end_line":1,"named_gap":"current line to replace in b.txt","why_not_answering":"the edit needs source evidence from the current mutation epoch"}`,
		`{"tool":"edit_file","path":"b.txt","old_text":"before","new_text":"after b","description":"update second required path"}`,
		"Changed paths:\n- a.txt\n- b.txt\nVerification: not required for this test fixture.",
	}

	requests := 0
	server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		defer ginkgo.GinkgoRecover()
		if requests >= len(replies) {
			ginkgo.Fail(fmt.Sprintf("unexpected extra chat request: requests=%d", requests), 1)
		}

		reply := replies[requests]
		requests++

		_ = json.NewEncoder(w).Encode(map[string]any{
			"choices": []map[string]any{{
				"message": map[string]string{"content": reply},
			}},
		})
	}))

	defer server.Close()

	var (
		rejectedReads         int
		completedPathReadRuns int
	)

	runner := newRunnerRunFixture(&Runner{
		Client: llama.NewClient(server.URL, time.Second),
		Workspace: workspace.NewManager(config.Workspace{
			Root:         root,
			CWD:          root,
			EnableWrites: true,
		}),
		Policy: RunPolicy{MaxToolSteps: 12, MaxNoProgressTurns: 8},
		RuntimeBrief: workerruntime.WorkerRuntimeBrief{
			TaskFamily:           "implementation",
			Contract:             "implementation_result",
			PermissionProfile:    "guarded_workspace_write",
			VerificationContract: "not_required_for_text_mutations",
			RequiredEditPaths:    []string{"a.txt", "b.txt"},
			TargetPacket:         []string{"prompt_context:verified_current_state"},
			EvidencePaths:        []string{"a.txt", "b.txt"},
		},
	})

	_, err := runner.runner.Run(
		context.Background(),
		[]llama.ChatMessage{{Role: "user", Content: "Update a.txt and b.txt."}},
		llama.ChatOptions{},
		nil,
		nil,
		func(event ToolResultEvent) {
			if event.Request.Tool == "read_file" {
				if event.Result.Error == "" {
					if event.Request.Path == "a.txt" && strings.Contains(event.Request.NamedGap, "now exposes") {
						completedPathReadRuns++
					}
				} else {
					rejectedReads++
				}
			}
		},
	)
	if err != nil {
		ginkgo.Fail(fmt.Sprintf("Run: %v", err), 1)
	}

	if rejectedReads != 0 {
		ginkgo.Fail(fmt.Sprintf("expected the named-gap read on a.txt (a completed required path) to pass, got %d rejected reads", rejectedReads), 1)
	}

	if completedPathReadRuns != 1 {
		ginkgo.Fail(fmt.Sprintf("expected one successful read on a.txt after the first write, got %d", completedPathReadRuns), 1)
	}

	for path, want := range map[string]string{"a.txt": "after a\n", "b.txt": "after b\n"} {
		got, err := os.ReadFile(filepath.Join(root, path))
		if err != nil {
			ginkgo.Fail(fmt.Sprintf("read %s: %v", path, err), 1)
		}

		if string(got) != want {
			ginkgo.Fail(fmt.Sprintf("%s content = %q, want %q", path, string(got), want), 1)
		}
	}
})

