var _ = ginkgo.It("RunnerRequiresVerificationAfterRepeatedWrites", func() {
	t := ginkgo.GinkgoT()
	root := t.TempDir()
	if err := writeTestFile(root, "README.md", "one\ntwo\nthree\n"); err != nil {
		ginkgo.Fail(fmt.Sprintf("write seed file: %v", err), 1)
	}
	initRunnerTestGitRepo(t, root)

	replies := []string{
		`{"tool":"read_file","path":"README.md","start_line":1,"end_line":3}`,
		`{"tool":"edit_file","path":"README.md","old_text":"one","new_text":"ONE","description":"update first line"}`,
		`{"tool":"read_file","path":"README.md","start_line":1,"end_line":3,"named_gap":"fresh source after the first edit","why_not_answering":"the second edit requires current source evidence"}`,
		`{"tool":"edit_file","path":"README.md","old_text":"two","new_text":"TWO","description":"update second line"}`,
		`{"tool":"read_file","path":"README.md"}`,
		`{"tool":"shell","command":"git diff --check -- README.md","workdir":"."}`,
		`{"tool":"read_file","path":"README.md"}`,
		"Changed paths:\n- README.md\n\nVerification: git diff --check -- README.md passed.",
	}
	requests := 0
	server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		defer ginkgo.GinkgoRecover()
		if requests >= len(replies) {
			ginkgo.Fail("unexpected extra chat request", 1)
		}

		reply := replies[requests]
		requests++

		_ = json.NewEncoder(w).Encode(map[string]any{
			"choices": []map[string]any{{
				"message": map[string]string{"content": reply},
			}},
		})
	}))

	defer server.Close()

	var (
		committedWrites         int
		verificationCompleted   bool
		sawReadWhilePending     bool
		sawPostVerificationRead bool
		resultSummaries         []string
	)

	runner := newRunnerRunFixture(&Runner{
		Client: llama.NewClient(server.URL, time.Second),
		Workspace: workspace.NewManager(config.Workspace{
			Root:                  root,
			CWD:                   root,
			EnableShell:           true,
			EnableWrites:          true,
			CommandTimeoutSeconds: 5,
		}),
		Policy: RunPolicy{MaxToolSteps: 10, MaxNoProgressTurns: 6},
		RuntimeBrief: workerruntime.WorkerRuntimeBrief{
			TaskFamily:           "implementation",
			Contract:             "implementation_result",
			PermissionProfile:    "guarded_workspace_write",
			VerificationContract: "tests_passed_or_failed_or_skipped_with_blocker",
			RequiredEditPaths:    []string{"README.md"},
		},
	})

	answer, err := runner.runner.Run(
		context.Background(),
		[]llama.ChatMessage{{Role: "user", Content: "edit two lines and verify"}},
		llama.ChatOptions{},
		nil,
		nil,
		func(event ToolResultEvent) {
			resultSummaries = append(resultSummaries, event.Result.Summary+"|"+event.Result.Error)
			if workspaceWriteResultCommitted(event.Request, event.Result) {
				committedWrites++
			}

			if event.Request.Tool == workspace.ToolNameShell && event.Result.Error == "" {
				verificationCompleted = true
			}

			if event.Request.Tool == workspace.ToolNameReadFile && event.Result.Error == "" && committedWrites >= 2 {
				if verificationCompleted {
					sawPostVerificationRead = true
				} else {
					sawReadWhilePending = true
				}
			}
		},
	)
	if err != nil {
		ginkgo.Fail(fmt.Sprintf("Run: %v", err), 1)
	}

	if !sawReadWhilePending {
		ginkgo.Fail(fmt.Sprintf("expected an authorized read to execute while final-set verification remained pending; results=%v", resultSummaries), 1)
	}

	if !sawPostVerificationRead {
		ginkgo.Fail(fmt.Sprintf("expected an authorized read to remain callable after verification; results=%v", resultSummaries), 1)
	}

	if !strings.Contains(answer, "README.md") || !strings.Contains(answer, "git diff --check") {
		ginkgo.Fail(fmt.Sprintf("unexpected answer: %q", answer), 1)
	}
})

