var _ = ginkgo.It("RunnerNoProgressCloseoutTelemetryIsNotBudgetExhaustion", func() {
	t := ginkgo.GinkgoT()
	root := t.TempDir()
	if err := writeTestFile(root, "internal/runtime/workerruntime/vocabulary.go", "package workerruntime\n"); err != nil {
		ginkgo.Fail(fmt.Sprintf("write seed: %v", err), 1)
	}

	requests := 0
	server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		defer ginkgo.GinkgoRecover()
		requests++
		if requests > 1 {
			ginkgo.Fail("unexpected extra chat request", 1)
		}

		_ = json.NewEncoder(w).Encode(map[string]any{
			"choices": []map[string]any{{"message": map[string]string{"content": "I cannot complete this."}}},
		})
	}))
	defer server.Close()

	var events []RunEvent
	runner := newRunnerRunFixture(&Runner{
		Client: llama.NewClient(server.URL, time.Second),
		Workspace: workspace.NewManager(config.Workspace{
			Root:         root,
			CWD:          root,
			EnableWrites: true,
		}),
		Policy: RunPolicy{MaxToolSteps: 4, MaxNoProgressTurns: 1, MaxModelCalls: 8},
		RuntimeBrief: workerruntime.WorkerRuntimeBrief{
			TaskFamily:        "implementation",
			Contract:          "implementation_result",
			PermissionProfile: "guarded_workspace_write",
			AllowedTools:      []string{"read_file", "edit_file", "apply_patch", "write_file"},
			AllowedEditPaths:  []string{"internal/runtime/workerruntime/vocabulary.go"},
			TargetRefs:        []string{"internal/runtime/workerruntime/vocabulary.go"},
			RequiredEvidence:  []string{"changed_paths_or_noop_reason", "verification_status"},
		},
		CompletionGate: func(input CompletionGateInput) CompletionGateResult {
			return CompletionGateResult{Summary: "external completion rejected", Error: "no implementation result"}
		},
		OnEvent: func(event RunEvent) {
			events = append(events, event)
		},
	})

	answer, err := runner.runner.Run(context.Background(), []llama.ChatMessage{{Role: "user", Content: "Update the vocabulary file."}}, llama.ChatOptions{}, nil, nil, nil)
	if err != nil {
		ginkgo.Fail(fmt.Sprintf("Run: %v", err), 1)
	}
	for _, want := range []string{
		"<<QUESTION>>: implementation closeout reached",
		"Changed paths: none",
		"no successful write was recorded",
		"no no-op evidence or exact blocker was produced",
	} {
		if !strings.Contains(answer, want) {
			ginkgo.Fail(fmt.Sprintf("expected no-progress implementation closeout to contain %q, got:\n%s", want, answer), 1)
		}
	}

	var ledger runnerBudgetLedger
	if !decodeLastRunEventContent(t, events, "budget_ledger", &ledger) {
		ginkgo.Fail(fmt.Sprintf("missing budget_ledger event: %s", formatRunEventsForTest(events)), 1)
	}
	if ledger.StopReason != "no_progress_budget_exhausted" {
		ginkgo.Fail(fmt.Sprintf("budget ledger stop reason = %q, want no_progress_budget_exhausted", ledger.StopReason), 1)
	}
	if ledger.BudgetExhausted {
		ginkgo.Fail(fmt.Sprintf("no-progress closeout must not report budget exhausted: %#v", ledger), 1)
	}

	var status runnerCompletionStatus
	if !decodeLastRunEventContent(t, events, "completion_status", &status) {
		ginkgo.Fail(fmt.Sprintf("missing completion_status event: %s", formatRunEventsForTest(events)), 1)
	}
	if status.BlockerKind != "no_progress_budget_exhausted" || status.Reason == "user_visible_blocker" {
		ginkgo.Fail(fmt.Sprintf("completion status should preserve host no-progress reason, got %#v", status), 1)
	}

	for _, event := range events {
		if event.Role != "autonomy_event" || !strings.Contains(event.Content, `"source":"runner_budget_gate"`) {
			continue
		}
		if strings.Contains(event.Content, `"exhaustion_reason"`) ||
			strings.Contains(event.Content, `budget_exhaustion_reason`) {
			ginkgo.Fail(fmt.Sprintf("observe-only no-progress budget gate must not report exhaustion reason:\n%s", event.Content), 1)
		}
	}
})

func decodeLastRunEventContent(t ginkgo.FullGinkgoTInterface, events []RunEvent, role string, target any) bool {
	t.Helper()

	for i := len(events) - 1; i >= 0; i-- {
		if events[i].Role != role {
			continue
		}
		if err := json.Unmarshal([]byte(events[i].Content), target); err != nil {
			ginkgo.Fail(fmt.Sprintf("decode %s event %q: %v", role, events[i].Content, err), 1)
		}
		return true
	}

	return false
}

