var _ = ginkgo.It("RunnerReadinessStateRequiresPlannerOwnedSourceSanityAfterPatchHygiene", func() {
	const target = "native/src/example.cpp"
	brief := workerruntime.WorkerRuntimeBrief{
		TaskFamily:           "implementation",
		Contract:             "implementation_result",
		PermissionProfile:    "guarded_workspace_write",
		RequiredEditPaths:    []string{target},
		VerificationContract: "tests_passed_or_failed_or_skipped_with_blocker",
		Constraints:          []string{"planner_owned_verification"},
	}
	run := newRunnerRunFixture(&Runner{RuntimeBrief: brief})
	_, write := committedMutationResultForTest(target)
	installMutationReceiptForTest(run, write)
	// A scripted shell result cannot claim which tracked paths Git actually
	// inspected. Without producer-owned verification evidence, the command is
	// observable but its coverage remains unresolved.
	unscopedPatchHygiene := shellCommandResultForTest("git diff --check -- "+target, "", "")
	gomega.Expect(unscopedPatchHygiene.Facts).NotTo(gomega.BeNil())
	gomega.Expect(unscopedPatchHygiene.Facts.VerificationEvidence).To(gomega.BeEmpty())
	observedPatchHygiene := workspace.AnalyzePostWriteVerificationResult(unscopedPatchHygiene, []string{target})
	gomega.Expect(observedPatchHygiene.Attempted).To(gomega.BeTrue())
	gomega.Expect(observedPatchHygiene.Successful).To(gomega.BeFalse())
	gomega.Expect(observedPatchHygiene.Coverage).To(gomega.Equal(workspace.VerificationCoverageUnresolved))
	gomega.Expect(observedPatchHygiene.CoveredPendingPaths).To(gomega.BeEmpty())

	results := []workspace.ToolResult{
		write,
		unscopedPatchHygiene,
	}
	completion := run.implementationCompletionState(results)

	readiness := runnerReadinessState("main", brief, results, &completion, planThenExecutePathAuthority{})
	gomega.Expect(readiness).NotTo(gomega.BeNil())
	gomega.Expect(readiness.ReadyToAnswer).To(gomega.BeFalse())
	gomega.Expect(readiness.ReadyToVerify).To(gomega.BeFalse())
	gomega.Expect(readiness.OpenObligations).To(gomega.ContainElement("planner_owned_source_lane_sanity_pending"))
	gomega.Expect(readiness.FurtherReadsRequire).To(gomega.BeEmpty(), "pending lane sanity must not reintroduce a read restriction")
})

var _ = ginkgo.It("CompletionGateRequiresVerificationUnlessTheExplicitContractSkipsIt", func() {
	cases := []struct {
		name                 string
		writePath            string
		required             []string
		verificationContract string
		want                 bool
	}{
		{"explicit text-deliverable contract skips markdown verification", "Wrote draft.md", []string{"draft.md"}, "not_required_for_text_mutations", false},
		{"ordinary markdown implementation requires patch hygiene", "Wrote README.md", []string{"README.md"}, "tests_passed_or_failed_or_skipped_with_blocker", true},
		{"unscoped markdown implementation requires patch hygiene", "Wrote README.md", nil, "tests_passed_or_failed_or_skipped_with_blocker", true},
		{"source implementation requires verification", "Wrote main.go", []string{"main.go"}, "tests_passed_or_failed_or_skipped_with_blocker", true},
		{"configuration implementation requires verification", "Wrote config.yaml", []string{"config.yaml"}, "tests_passed_or_failed_or_skipped_with_blocker", true},
	}
	for _, c := range cases {
		ginkgo.By(c.name, func() {
			_, write := committedMutationResultForTest(strings.TrimPrefix(c.writePath, "Wrote "))
			results := []workspace.ToolResult{write}
			brief := workerruntime.WorkerRuntimeBrief{
				VerificationContract: c.verificationContract,
				RequiredEditPaths:    c.required,
			}
			got := postWriteVerificationLedgerForReceipts(
				results,
				brief,
				[]workspace.MutationCommitProjection{write.CommitReceipt().DurableProjection()},
			).Pending()

			if got != c.want {
				ginkgo.Fail(fmt.Sprintf("hasPendingVerificationAfterWrites for %q (required=%v) = %v, want %v", c.writePath, c.required, got, c.want), 1)
			}
		})
	}
})

