var _ = ginkgo.It("RequiredPathCompletionRecoveryAcceptsPathSpecificBlocker", func() {
	t := ginkgo.GinkgoT()
	root := t.TempDir()
	for _, path := range []string{"a.txt", "b.txt"} {
		if err := writeTestFile(root, path, "before\n"); err != nil {
			ginkgo.Fail(fmt.Sprintf("write %s: %v", path, err), 1)
		}
	}

	pathBlocker := "<<QUESTION>>: use the validated task-ledger blocker"
	replies := []string{
		`{"tool":"write_file","path":"a.txt","content":"after a\n","description":"partial required edit"}`,
		`{"tool":"task_ledger","todos":[{"id":"edit-b","content":"Edit b.txt","status":"blocked","paths":["b.txt"],"blocker":{"kind":"approval_required","subject":{"namespace":"workspace_path","id":"b.txt"},"reason":"the provided edit anchor is stale"}}]}`,
		pathBlocker,
	}

	var requests int

	server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		defer ginkgo.GinkgoRecover()
		if requests >= len(replies) {
			ginkgo.Fail("unexpected extra chat request", 1)
		}

		reply := replies[requests]
		requests++

		_ = json.NewEncoder(w).Encode(map[string]any{
			"choices": []map[string]any{{
				"message": map[string]string{"content": reply},
			}},
		})
	}))

	defer server.Close()
	manager := workspace.NewManager(config.Workspace{
		Root:         root,
		CWD:          root,
		EnableWrites: true,
	})
	sourceRead := manager.Execute(context.Background(), workspace.ToolRequest{
		Tool: workspace.ToolNameReadFile, Path: "a.txt", StartLine: 1, EndLine: 20,
	})
	if sourceRead.Error != "" || len(sourceRead.SourceWindows()) == 0 {
		ginkgo.Fail(fmt.Sprintf("produce path-blocker source-window fixture: %#v", sourceRead), 1)
	}

	var (
		completion            runnerCompletionStatus
		repeatedBlockerStatus bool
	)

	runner := newRunnerRunFixture(&Runner{
		Client:     llama.NewClient(server.URL, time.Second),
		Workspace:  manager,
		Policy:     RunPolicy{MaxToolSteps: 8, MaxNoProgressTurns: 6},
		TaskLedger: TaskLedgerPolicy{Required: true},
		RuntimeBrief: workerruntime.WorkerRuntimeBrief{
			TaskFamily:           "implementation",
			Contract:             "implementation_result",
			PermissionProfile:    "guarded_workspace_write",
			VerificationContract: "not_required_for_text_mutations",
			RequiredEditPaths:    []string{"a.txt", "b.txt"},
		},
		SeedResults: []workspace.ToolResult{sourceRead},
		OnEvent: func(event RunEvent) {
			if event.Role != "completion_status" {
				return
			}

			if err := json.Unmarshal([]byte(event.Content), &completion); err != nil {
				ginkgo.Fail(fmt.Sprintf("decode completion status: %v", err), 1)
			}

			if completion.BlockerKind == "completion_gate_required_paths_remaining_repeated" {
				repeatedBlockerStatus = true
			}
		},
	})

	answer, err := runner.runner.Run(
		context.Background(),
		[]llama.ChatMessage{{Role: "user", Content: "Update both required files."}},
		llama.ChatOptions{},
		nil,
		nil,
		nil,
	)
	if err != nil {
		ginkgo.Fail(fmt.Sprintf("Run: %v", err), 1)
	}

	for _, want := range []string{"edit-b", "approval_required", `subject_namespace="workspace_path"`, `subject_id="b.txt"`, "the provided edit anchor is stale"} {
		if !strings.Contains(answer, want) {
			ginkgo.Fail(fmt.Sprintf("expected typed path blocker answer to contain %q, got %q", want, answer), 1)
		}
	}

	if requests != len(replies) {
		ginkgo.Fail(fmt.Sprintf("expected one recovery retry, got %d request(s)", requests), 1)
	}

	if repeatedBlockerStatus {
		ginkgo.Fail("path-specific blocker should not be replaced by repeated completion-gate blocker", 1)
	}

	if completion.BlockerKind != "user_visible_blocker" ||
		!slices.Contains(completion.ChangedPaths, "a.txt") ||
		!slices.Equal(completion.ImplementationState.OpenTaskLedgerObligationIDs, []string{"edit-b"}) ||
		len(completion.ImplementationState.BlockedTaskLedgerItems) != 1 ||
		completion.ImplementationState.BlockedTaskLedgerItems[0].SubjectID != "b.txt" {

		ginkgo.Fail(fmt.Sprintf("expected accepted blocker status for remaining path, got %#v", completion), 1)
	}
})

var _ = ginkgo.It("PlannerCompletionGateResolvesSourceSatisfiedRequiredPaths", func() {
	t := ginkgo.GinkgoT()
	brief := workerruntime.WorkerRuntimeBrief{
		TaskFamily:        PlanThenExecutePlannerTaskFamily,
		Contract:          "implementation_result",
		PermissionProfile: "guarded_workspace_write",
		RequiredEditPaths: []string{"a.txt", "b.txt"},
	}
	runner := newRunnerRunFixture(&Runner{
		RuntimeBrief: brief,
		OnEvent:      func(RunEvent) {},
	})
	recorder := newRunnerAutonomyRecorder(runner, RunPolicy{}, brief, nil)

	if recorder == nil {
		ginkgo.Fail("expected autonomy recorder", 1)
	}

	recorder.emitContractStarted(brief)

	if countObligationKind(recorder.obligations, autonomy.ObligationWrite) != 0 {
		ginkgo.Fail(fmt.Sprintf("compiled planner contract should not carry executor workspace write obligations: %#v", recorder.obligations), 1)
	}

	refs := recorder.obligationIDsForGate(autonomy.GateCompletion)
	resolved, open := recorder.completionGateResolvedAndOpenObligations(runnerAutonomyGateDecision{
		Gate:       autonomy.GateCompletion,
		Decision:   autonomy.PolicyAllow,
		ReasonCode: "plan_source_satisfied_short_circuit",
		TargetRefs: []string{"a.txt:pending", "b.txt:pending"},
	}, refs)

	coverageIDs := plannerCoverageObligationsByPathForTest(t, recorder)
	for _, path := range brief.RequiredEditPaths {
		id := coverageIDs[path]
		if id == "" {
			ginkgo.Fail(fmt.Sprintf("missing planner coverage obligation for %s in %#v", path, recorder.obligations), 1)
		}

		if !slices.Contains(resolved, id) {
			ginkgo.Fail(fmt.Sprintf("source-satisfied closeout should resolve plan coverage obligation %s; resolved=%#v open=%#v", id, resolved, open), 1)
		}

		if slices.Contains(open, id) {
			ginkgo.Fail(fmt.Sprintf("source-satisfied closeout should not leave plan coverage obligation %s open; resolved=%#v open=%#v", id, resolved, open), 1)
		}
	}
})

var _ = ginkgo.It("PlannerCompletionGateResolvesUnscopedSourceSatisfiedFinalOutcome", func() {
	t := ginkgo.GinkgoT()
	brief := workerruntime.WorkerRuntimeBrief{
		TaskFamily:        PlanThenExecutePlannerTaskFamily,
		Contract:          "implementation_result",
		PermissionProfile: "guarded_workspace_write",
	}
	runner := newRunnerRunFixture(&Runner{
		RuntimeBrief: brief,
		OnEvent:      func(RunEvent) {},
	})
	recorder := newRunnerAutonomyRecorder(runner, RunPolicy{}, brief, nil)

	if recorder == nil {
		ginkgo.Fail("expected autonomy recorder", 1)
	}

	recorder.emitContractStarted(brief)

	if countObligationKind(recorder.obligations, autonomy.ObligationWrite) != 0 {
		ginkgo.Fail(fmt.Sprintf("compiled planner contract should not carry generic executor write obligation: %#v", recorder.obligations), 1)
	}

	refs := recorder.obligationIDsForGate(autonomy.GateCompletion)
	resolved, open := recorder.completionGateResolvedAndOpenObligations(runnerAutonomyGateDecision{
		Gate:       autonomy.GateCompletion,
		Decision:   autonomy.PolicyAllow,
		ReasonCode: "plan_source_satisfied_short_circuit",
	}, refs)

	finalAnswerID := obligationIDByKindForTest(t, recorder, autonomy.ObligationFinalAnswer)
	if !slices.Contains(resolved, finalAnswerID) {
		ginkgo.Fail(fmt.Sprintf("unscoped source-satisfied closeout should resolve planner final outcome obligation; resolved=%#v open=%#v", resolved, open), 1)
	}

	if slices.Contains(open, finalAnswerID) {
		ginkgo.Fail(fmt.Sprintf("unscoped source-satisfied closeout should not leave planner final outcome obligation open; resolved=%#v open=%#v", resolved, open), 1)
	}
})

func plannerCoverageObligationsByPathForTest(t ginkgo.FullGinkgoTInterface, recorder *runnerAutonomyRecorder) map[string]string {
	t.Helper()

	ids := make(map[string]string)

	for _, obligation := range recorder.obligations {
		if obligation.Kind != autonomy.ObligationEvidence || obligation.RequiredBy != "submit_plan_required_edit_coverage" {
			continue
		}

		ids[obligation.TargetRef] = obligation.ObligationID
	}

	return ids
}

func obligationIDByKindForTest(t ginkgo.FullGinkgoTInterface, recorder *runnerAutonomyRecorder, kind autonomy.ObligationKind) string {
	t.Helper()

	for _, obligation := range recorder.obligations {
		if obligation.Kind == kind {
			return obligation.ObligationID
		}
	}

	ginkgo.Fail(fmt.Sprintf("missing obligation kind %q in %#v", kind, recorder.obligations), 1)

	return ""
}

