var _ = ginkgo.It("RunnerTargetSourceRejectsWriteBeforeSourceBodyEvidence", func() {
	t := ginkgo.GinkgoT()
	root := t.TempDir()
	if err := writeTestFile(root, "target.go", "package main\n\nconst value = \"before\"\n"); err != nil {
		ginkgo.Fail(fmt.Sprintf("write target: %v", err), 1)
	}

	replies := []string{
		`{"tool":"edit_file","path":"target.go","old_text":"before","new_text":"after","description":"replace value"}`,
		`{"tool":"read_file","path":"target.go","start_line":1,"end_line":3,"named_gap":"source-body evidence before applying requested change"}`,
		`{"tool":"edit_file","path":"target.go","old_text":"before","new_text":"after","description":"replace value after source evidence"}`,
		"Done. Changed target.go; verification not required for this test.",
	}
	requests := 0
	server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		reply := "Done. Changed target.go; verification not required for this test."
		if requests < len(replies) {
			reply = replies[requests]
		}

		requests++

		_ = json.NewEncoder(w).Encode(map[string]any{
			"choices": []map[string]any{{
				"message": map[string]string{"content": reply},
			}},
		})
	}))

	defer server.Close()

	var (
		explicitRead  bool
		typedDeferral bool
	)

	runner := newRunnerRunFixture(&Runner{
		Client: llama.NewClient(server.URL, time.Second),
		Workspace: workspace.NewManager(config.Workspace{
			Root:         root,
			CWD:          root,
			EnableWrites: true,
		}),
		RuntimeBrief: workerruntime.WorkerRuntimeBrief{
			TaskFamily:           "implementation",
			Contract:             "implementation_result",
			PermissionProfile:    "guarded_workspace_write",
			AllowedTools:         []string{"read_file", "search_content", "edit_file"},
			VerificationContract: "not_required_for_text_mutations",
		},
		Policy: RunPolicy{MaxToolSteps: 4, MaxNoProgressTurns: 3},
	})
	onToolResult := func(event ToolResultEvent) {
		if event.Result.Tool == "read_file" && strings.Contains(event.Result.Summary, "target.go") {
			explicitRead = true
		}
		if event.Result.Tool == workspace.ToolNameEditFile && event.Result.Facts != nil &&
			event.Result.Facts.RejectionDisposition == toolfacts.ToolRejectionDeferredByPrerequisite &&
			slices.Equal(event.Result.Facts.PendingSourceBodyPaths, []string{"target.go"}) {

			typedDeferral = true
		}
	}

	if _, err := runner.runner.Run(
		context.Background(),
		[]llama.ChatMessage{{Role: "user", Content: "update target.go"}},
		llama.ChatOptions{},
		nil,
		nil,
		onToolResult,
	); err != nil {
		ginkgo.Fail(fmt.Sprintf("Run: %v", err), 1)
	}

	if !typedDeferral || !explicitRead {
		ginkgo.Fail("expected a typed prerequisite rejection followed by the model's explicit bounded read", 1)
	}

	got, err := os.ReadFile(filepath.Join(root, "target.go"))
	if err != nil {
		ginkgo.Fail(fmt.Sprintf("read target: %v", err), 1)
	}

	if !strings.Contains(string(got), "after") {
		ginkgo.Fail(fmt.Sprintf("fresh write did not execute after explicit source-body evidence:\n%s", got), 1)
	}
})

