var _ = ginkgo.It("RunnerDoesNotSalvageMalformedWriteJSONPrefixInReadOnlyMode", func() {
	t := ginkgo.GinkgoT()
	root := t.TempDir()
	if err := writeTestFile(root, "README.md", "old\n"); err != nil {
		ginkgo.Fail(fmt.Sprintf("write README: %v", err), 1)
	}

	replies := []string{
		`{"tool":"edit_file","path":"README.md","old_text":"old","new_text":"new" - apply this edit`,
		`{"tool":"read_file","path":"README.md","start_line":1,"end_line":1}`,
		"`README.md` remains unchanged and currently contains `old`; the malformed write request was not executed.",
	}
	requests := 0
	server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		defer ginkgo.GinkgoRecover()
		if requests >= len(replies) {
			ginkgo.Fail("unexpected extra chat request", 1)
		}

		reply := replies[requests]
		requests++

		_ = json.NewEncoder(w).Encode(map[string]any{
			"choices": []map[string]any{{
				"message": map[string]string{"content": reply},
			}},
		})
	}))

	defer server.Close()

	var (
		toolRequests     []ToolRequestEvent
		toolParseResults int
	)

	runner := newRunnerRunFixture(&Runner{
		Client: llama.NewClient(server.URL, time.Second),
		Workspace: workspace.NewManager(config.Workspace{
			Root:         root,
			CWD:          root,
			EnableWrites: false,
		}),
		Policy: RunPolicy{MaxToolSteps: 2, MaxNoProgressTurns: 3},
		RuntimeBrief: workerruntime.WorkerRuntimeBrief{
			TaskFamily:        "conversation",
			Contract:          "direct_answer",
			Objective:         "Explain the README.",
			PermissionProfile: "read_only_workspace",
			AllowedTools:      []string{"read_file"},
		},
	})

	answer, err := runner.runner.Run(
		context.Background(),
		[]llama.ChatMessage{{Role: "user", Content: "Explain the README."}},
		llama.ChatOptions{},
		nil,
		func(event ToolRequestEvent) {
			toolRequests = append(toolRequests, event)
		},
		func(event ToolResultEvent) {
			if event.Request.Tool == "tool_parse" || event.Result.Tool == "tool_parse" {
				toolParseResults++
			}
		},
	)
	if err != nil {
		ginkgo.Fail(fmt.Sprintf("Run: %v", err), 1)
	}

	if answer != "`README.md` remains unchanged and currently contains `old`; the malformed write request was not executed." {
		ginkgo.Fail(fmt.Sprintf("unexpected answer %q", answer), 1)
	}

	if toolParseResults != 1 {
		ginkgo.Fail(fmt.Sprintf("malformed write JSON must remain a tool_parse rejection, got %d", toolParseResults), 1)
	}

	if len(toolRequests) != 1 || toolRequests[0].Request.Tool != workspace.ToolNameReadFile {
		ginkgo.Fail(fmt.Sprintf("only the fresh model-authored read may execute after malformed write rejection, got %#v", toolRequests), 1)
	}

	data, err := os.ReadFile(filepath.Join(root, "README.md"))
	if err != nil {
		ginkgo.Fail(fmt.Sprintf("read README: %v", err), 1)
	}

	if string(data) != "old\n" {
		ginkgo.Fail(fmt.Sprintf("read-only malformed write changed workspace: %q", string(data)), 1)
	}
})

