var _ = ginkgo.It("RunnerCountsForcedCompletionUsageInBudgetLedger", func() {
	t := ginkgo.GinkgoT()
	replies := []map[string]any{
		{
			"choices": []map[string]any{{
				"message": map[string]string{"content": "```tool\n{\"tool\":\"pwd\"}\n```"},
			}},
			"usage": map[string]int{"prompt_tokens": 5, "completion_tokens": 2, "total_tokens": 7},
		},
		{
			"choices": []map[string]any{{
				"message": map[string]string{"content": "Forced final."},
			}},
			"usage": map[string]int{"prompt_tokens": 13, "completion_tokens": 3, "total_tokens": 16},
		},
	}

	var requests int

	server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		defer ginkgo.GinkgoRecover()
		if requests >= len(replies) {
			ginkgo.Fail("unexpected extra chat request", 1)
		}

		reply := replies[requests]
		requests++

		_ = json.NewEncoder(w).Encode(reply)
	}))

	defer server.Close()

	var budgetEvent string

	runner := newRunnerRunFixture(&Runner{
		Client: llama.NewClient(server.URL, time.Second),
		Workspace: workspace.NewManager(config.Workspace{
			Root: t.TempDir(),
			CWD:  ".",
		}),
		Policy: RunPolicy{MaxToolSteps: 1, MaxNoProgressTurns: 3},
		OnEvent: func(event RunEvent) {
			if event.Role == "budget_ledger" {
				budgetEvent = event.Content
			}
		},
	})

	answer, err := runner.runner.Run(context.Background(), []llama.ChatMessage{{Role: "user", Content: "pwd then stop"}}, llama.ChatOptions{}, nil, nil, nil)
	if err != nil {
		ginkgo.Fail(fmt.Sprintf("Run: %v", err), 1)
	}

	if answer != "Forced final." {
		ginkgo.Fail(fmt.Sprintf("unexpected answer %q", answer), 1)
	}

	var ledger runnerBudgetLedger

	if err := json.Unmarshal([]byte(budgetEvent), &ledger); err != nil {
		ginkgo.Fail(fmt.Sprintf("decode budget ledger %q: %v", budgetEvent, err), 1)
	}

	if ledger.StopReason != "tool_step_budget_exhausted" || !ledger.BudgetExhausted {
		ginkgo.Fail(fmt.Sprintf("unexpected budget state: %#v", ledger), 1)
	}

	if ledger.UsedModelCalls != 2 || ledger.PromptTokens != 18 || ledger.CompletionTokens != 5 || ledger.TotalTokens != 23 {
		ginkgo.Fail(fmt.Sprintf("expected forced completion usage in budget ledger, got %#v", ledger), 1)
	}
})

