var _ = ginkgo.It("RunnerWorkspaceToolRulesDenyBeforePolicyAllow", func() {
	t := ginkgo.GinkgoT()
	root := t.TempDir()
	secret := "SECRET_SENTINEL_DO_NOT_LEAK"

	if err := os.WriteFile(filepath.Join(root, "secret.txt"), []byte(secret), 0o600); err != nil {
		ginkgo.Fail(fmt.Sprintf("write sentinel: %v", err), 1)
	}

	replies := []string{
		"```tool\n{\"tool\":\"read_file\",\"path\":\"secret.txt\"}\n```",
		"```tool\n{\"tool\":\"read_file\",\"path\":\"secret.txt\"}\n```",
	}

	var requests int

	server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		defer ginkgo.GinkgoRecover()
		if requests >= len(replies) {
			ginkgo.Fail("unexpected extra chat request", 1)
		}

		reply := replies[requests]
		requests++

		_ = json.NewEncoder(w).Encode(map[string]any{
			"choices": []map[string]any{{
				"message": map[string]string{"content": reply},
			}},
		})
	}))

	defer server.Close()

	var (
		permissionEvent  string
		allowEvent       string
		completionStatus string
		leaked           bool
	)

	runner := newRunnerRunFixture(&Runner{
		Client: llama.NewClient(server.URL, time.Second),
		Workspace: workspace.NewManager(config.Workspace{
			Root: root,
			CWD:  root,
			ToolRules: map[string][]config.ToolRule{
				"read_file": {
					{Pattern: "secret.txt", Decision: "deny"},
				},
			},
		}),
		Policy: RunPolicy{MaxToolSteps: 3, MaxNoProgressTurns: 3},
		PermissionPolicy: toolpolicy.Policy{
			Default: toolpolicy.Allow,
		},
		OnEvent: func(event RunEvent) {
			if event.Role == "permission_decision" {
				if strings.Contains(event.Content, `"decision":"deny"`) {
					permissionEvent = event.Content
				}

				if strings.Contains(event.Content, `"decision":"allow"`) {
					allowEvent = event.Content
				}
			}

			if event.Role == "completion_status" {
				completionStatus = event.Content
			}

			if strings.Contains(event.Content, secret) {
				leaked = true
			}
		},
	})

	answer, err := runner.runner.Run(context.Background(), []llama.ChatMessage{{Role: "user", Content: "read secret"}}, llama.ChatOptions{}, nil, nil, nil)
	if err != nil {
		ginkgo.Fail(fmt.Sprintf("Run: %v", err), 1)
	}

	if !strings.Contains(answer, "workspace `tool_rules` deny `read_file`") {
		ginkgo.Fail(fmt.Sprintf("unexpected answer %q", answer), 1)
	}

	if requests != 1 {
		ginkgo.Fail(fmt.Sprintf("workspace deny should close before a second model call, got %d requests", requests), 1)
	}

	if permissionEvent == "" || !strings.Contains(permissionEvent, "workspace.tool_rules") {
		ginkgo.Fail(fmt.Sprintf("expected workspace tool_rules deny event, got %q", permissionEvent), 1)
	}

	if !strings.Contains(completionStatus, `"blocker_kind":"workspace_tool_rules_deny"`) {
		ginkgo.Fail(fmt.Sprintf("expected workspace tool_rules completion status, got %q", completionStatus), 1)
	}

	if allowEvent != "" {
		ginkgo.Fail(fmt.Sprintf("workspace deny must not emit allow permission event: %s", allowEvent), 1)
	}

	if leaked {
		ginkgo.Fail("deny path leaked sentinel content", 1)
	}
})

