var _ = ginkgo.It("WorkspaceWriteResultCommittedRequiresCommitReceipt", func() {
	t := ginkgo.GinkgoT()
	root := t.TempDir()
	writeRunnerTestFile(t, root, "README.md", "before\n")
	manager := workspace.NewManager(config.Workspace{Root: root, CWD: root, EnableWrites: true})
	run := newRunnerRunFixture(&Runner{Workspace: manager, RuntimeBrief: workerruntime.WorkerRuntimeBrief{
		TaskFamily: "implementation", Contract: "implementation_result", PermissionProfile: "guarded_workspace_write",
		AllowedEditPaths: []string{"README.md"},
	}})
	observed := manager.Execute(run.state.ctx, workspace.ToolRequest{Tool: workspace.ToolNameReadFile, Path: "README.md"})
	if observed.Error != "" {
		ginkgo.Fail(fmt.Sprintf("observe README.md before edit: %#v", observed), 1)
	}
	req := workspace.ToolRequest{Tool: "edit_file", Path: "README.md", OldText: "before\n", NewText: "after\n"}
	committed := manager.Execute(run.state.ctx, req)
	if !workspaceWriteResultCommitted(req, committed) {
		ginkgo.Fail("workspace-authored edit receipt should complete the exact-anchor write phase", 1)
	}

	if workspaceWriteResultCommitted(req, workspace.ToolResult{Tool: "edit_file", Summary: "No-op edit for README.md"}) {
		ginkgo.Fail("error-free no-op edit must not arm mutation verification", 1)
	}

	if workspaceWriteResultCommitted(req, workspace.ToolResult{Tool: "edit_file", Summary: "Edit request rejected", Error: "old_text did not appear"}) {
		ginkgo.Fail("failed edit_file result must not release exact-anchor read tools", 1)
	}

	spoofedPartial := workspace.ToolResult{Tool: "apply_patch", Summary: "Patch partially committed", Error: "second operation failed", ChangedPaths: []string{"README.md"}}
	if workspaceWriteResultCommitted(workspace.ToolRequest{Tool: "apply_patch"}, spoofedPartial) {
		ginkgo.Fail("ChangedPaths without a producer receipt must not claim a partial commit", 1)
	}

	if workspaceWriteResultCommitted(workspace.ToolRequest{Tool: "read_file", Path: "README.md"}, workspace.ToolResult{Tool: "read_file", Summary: "Read README.md"}) {
		ginkgo.Fail("read tools must not complete the exact-anchor write phase", 1)
	}
})

var _ = ginkgo.It("ExactAnchorRejectedWritesRemainUnderGlobalLoopPolicyAndCanRecover", func() {
	t := ginkgo.GinkgoT()
	root := t.TempDir()
	if err := writeTestFile(root, "target.txt", "actual\n"); err != nil {
		ginkgo.Fail(fmt.Sprintf("write target: %v", err), 1)
	}

	replies := []string{
		`{"tool":"edit_file","path":"target.txt","old_text":"missing anchor one","new_text":"replacement one\n","description":"bad anchor one"}`,
		`{"tool":"edit_file","path":"target.txt","old_text":"missing anchor two","new_text":"replacement two\n","description":"bad anchor two"}`,
		`{"tool":"edit_file","path":"target.txt","old_text":"missing anchor three","new_text":"replacement three\n","description":"bad anchor three"}`,
		`{"tool":"edit_file","path":"target.txt","old_text":"actual\n","new_text":"replacement\n","description":"apply the current exact anchor"}`,
		"Updated the exact-anchor target.\n\nChanged paths:\n- target.txt\n\nVerification: not run",
	}
	requests := 0
	server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		defer ginkgo.GinkgoRecover()
		if requests >= len(replies) {
			ginkgo.Fail("unexpected extra chat request after exact-anchor recovery", 1)
		}

		reply := replies[requests]
		requests++

		_ = json.NewEncoder(w).Encode(map[string]any{
			"choices": []map[string]any{{"message": map[string]string{"content": reply}}},
		})
	}))

	defer server.Close()

	mgr := workspace.NewManager(config.Workspace{
		Root:         root,
		CWD:          root,
		EnableWrites: true,
	})
	mgr.MarkPathObserved("target.txt")
	sourceRead := mgr.Execute(context.Background(), workspace.ToolRequest{
		Tool: workspace.ToolNameReadFile, Path: "target.txt", StartLine: 1, EndLine: 1,
	})
	if sourceRead.Error != "" || len(sourceRead.SourceWindows()) == 0 {
		ginkgo.Fail(fmt.Sprintf("produce exact-anchor source-window fixture: %#v", sourceRead), 1)
	}

	runner := newRunnerRunFixture(&Runner{
		Client:    llama.NewClient(server.URL, time.Second),
		Workspace: mgr,
		Policy:    RunPolicy{MaxToolSteps: 8, MaxNoProgressTurns: 8},
		RuntimeBrief: workerruntime.WorkerRuntimeBrief{
			TaskFamily:           "implementation",
			Contract:             "implementation_result",
			PermissionProfile:    "guarded_workspace_write",
			VerificationContract: "not_required_for_text_mutations",
			Constraints:          []string{"exact_anchor_implementation"},
			RequiredEditPaths:    []string{"target.txt"},
			TargetRefs:           []string{"target.txt"},
		},
		SeedResults: []workspace.ToolResult{sourceRead},
	})

	answer, err := runner.runner.Run(
		context.Background(),
		[]llama.ChatMessage{{Role: "user", Content: "apply exact anchor edit"}},
		llama.ChatOptions{},
		nil,
		nil,
		nil,
	)
	if err != nil {
		ginkgo.Fail(fmt.Sprintf("Run: %v", err), 1)
	}

	for _, want := range []string{"Updated the exact-anchor target", "Changed paths:\n- target.txt", "Verification: not run"} {
		if !strings.Contains(answer, want) {
			ginkgo.Fail(fmt.Sprintf("expected recovered exact-anchor answer to contain %q, got %q", want, answer), 1)
		}
	}

	if requests != len(replies) {
		ginkgo.Fail(fmt.Sprintf("expected recovery through all %d model replies, got %d request(s)", len(replies), requests), 1)
	}

	content, err := os.ReadFile(filepath.Join(root, "target.txt"))
	if err != nil {
		ginkgo.Fail(fmt.Sprintf("read target: %v", err), 1)
	}

	if string(content) != "replacement\n" {
		ginkgo.Fail(fmt.Sprintf("fresh exact-anchor write should recover after rejected attempts, got %q", content), 1)
	}
})

var _ = ginkgo.It("NormalizeDelegatedReadOnlyPacketStripsTransientHandles", func() {
	packet := "Partial findings from this turn (the budget was reached before a full synthesis):\n\nVerified context:\n- Read f23 internal/runtime/agent/implementation_flow.go lines 1-40\n- The caller is internal/runtime/agent/runner_core.go:574 and the composer lives in internal/runtime/agent/implementation_flow.go``\nf23 internal/runtime/agent/implementation_flow.go\nf7 README.md\n"
	got := normalizeDelegatedReadOnlyPacket(packet)

	if strings.Contains(got, "f23 ") || strings.Contains(got, "f7 ") {
		ginkgo.Fail(fmt.Sprintf("expected transient handles to be stripped, got:\n%s", got), 1)
	}

	if strings.Contains(got, "internal/runtime/agent/runner_core.go:574") || strings.Contains(got, "internal/runtime/agent/implementation_flow.go``") {
		ginkgo.Fail(fmt.Sprintf("expected packet normalization to strip speculative line citations and malformed quotes, got:\n%s", got), 1)
	}

	markdownPathLine := "- `internal/runtime/agent/implementation_flow.go`"
	if normalizedLine := normalizeDelegatedReadOnlyPacket(markdownPathLine); normalizedLine != markdownPathLine {
		ginkgo.Fail(fmt.Sprintf("expected packet normalization to preserve markdown path citations, got %q", normalizedLine), 1)
	}

	for _, want := range []string{"internal/runtime/agent/implementation_flow.go", "internal/runtime/agent/runner_core.go", "internal/runtime/agent/implementation_flow.go", "README.md"} {
		if !strings.Contains(got, want) {
			ginkgo.Fail(fmt.Sprintf("expected normalized packet to retain %q, got:\n%s", want, got), 1)
		}
	}
})

