// Fix 7 (real subagent spawning via the task tool) — exercises
// docs/opencode-fixes-design.md §7. Verifies that the parent's `task` call
// launches an isolated child Runner, that the child actually drives the
// model loop (tool call plus answer), and that the child's intermediate
// messages do not pollute the parent's conversation.
var _ = ginkgo.It("RunnerTaskToolSpawnsIsolatedReadOnlyChild", func() {
	t := ginkgo.GinkgoT()
	root := t.TempDir()
	if err := writeTestFile(root, "src/widget.go", "package widget\n"); err != nil {
		ginkgo.Fail(fmt.Sprintf("seed: %v", err), 1)
	}

	replies := []string{
		`{"tool":"task","agent":"scout","mode":"read_only","prompt":"list .go files under src/"}`,
		`{"tool":"list_files","path":"src"}`,
		`{"tool":"read_file","path":"src/widget.go","start_line":1,"end_line":1}`,
		"The delegated probe read the Go source file under src and found that it declares the widget package, so the requested read-only scan located a concrete Go file.",
		"The scout reported that the delegated probe found a Go source file declaring the widget package.",
		"The scout reported that the delegated probe found a Go source file declaring the widget package.",
	}
	requests := 0
	server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		reply := "The scout reported that the delegated probe found a Go source file declaring the widget package."
		if requests < len(replies) {
			reply = replies[requests]
		}

		requests++

		_ = json.NewEncoder(w).Encode(map[string]any{
			"choices": []map[string]any{{
				"message": map[string]string{"content": reply},
			}},
		})
	}))

	defer server.Close()

	mgr := workspace.NewManager(config.Workspace{
		Root:                root,
		CWD:                 root,
		MaxDirectoryEntries: 64,
	})

	var (
		childRequests, childResults int
		events                      []string
	)

	runner := newRunnerRunFixture(&Runner{
		Client:    llama.NewClient(server.URL, 2*time.Second),
		Workspace: mgr,
		Policy:    RunPolicy{MaxToolSteps: 8, MaxNoProgressTurns: 4},
		OnEvent: func(event RunEvent) {
			if event.Role == "completion_gate" || strings.Contains(event.Role, "critic") || strings.Contains(event.Role, "readiness") {
				events = append(events, event.Role+": "+event.Content)
			}

			switch event.Role {
			case "child_tool_request":
				childRequests++
			case "child_tool_result":
				childResults++
			}
		},
	})

	answer, err := runner.runner.Run(
		context.Background(),
		[]llama.ChatMessage{{Role: "user", Content: "delegate a read-only probe then report"}},
		llama.ChatOptions{},
		nil,
		nil,
		nil,
	)
	if err != nil {
		ginkgo.Fail(fmt.Sprintf("Run: %v; events=%v", err, events), 1)
	}

	if !strings.Contains(answer, "scout") || !strings.Contains(answer, "widget package") {
		ginkgo.Fail(fmt.Sprintf("unexpected parent answer: %q; events=%v", answer, events), 1)
	}

	if childRequests == 0 || childResults == 0 {
		ginkgo.Fail(fmt.Sprintf("expected isolated child tool events to fire (requests=%d results=%d)", childRequests, childResults), 1)
	}

	if requests < 5 || requests > 8 {
		ginkgo.Fail(fmt.Sprintf("expected parent spawn, child steps, and bounded parent final synthesis; got %d requests", requests), 1)
	}
})

var _ = ginkgo.It("RunnerReturnsChildPacketBeforeBroadRediscovery", func() {
	t := ginkgo.GinkgoT()
	root := t.TempDir()
	if err := os.MkdirAll(filepath.Join(root, "internal", "runtime", "agent"), 0o755); err != nil {
		ginkgo.Fail(fmt.Sprintf("mkdir internal/runtime/agent: %v", err), 1)
	}

	if err := os.WriteFile(filepath.Join(root, "internal", "runtime", "agent", "runner_core.go"), []byte("package agent\n\nfunc RunnerHotPath() {}\n"), 0o644); err != nil {
		ginkgo.Fail(fmt.Sprintf("write runner_core.go: %v", err), 1)
	}

	replies := []string{
		`{"tool":"read_file","path":"internal/runtime/agent/runner_core.go"}`,
		`{"tool":"search_files","pattern":"runner","path":"."}`,
		`{"tool":"read_file","path":"internal/runtime/agent/runner_core.go","start_line":1,"end_line":3}`,
		`{"tool":"list_files","path":"."}`,
		`{"tool":"task","agent":"explorer","mode":"read_only","prompt":"Inspect performance evidence in internal/runtime/agent/runner_core.go and report paths."}`,
		`{"tool":"read_file","path":"internal/runtime/agent/runner_core.go","start_line":1,"end_line":3}`,
		"No performance risk stands out in internal/runtime/agent/runner_core.go from the delegated evidence. Confidence: medium.",
		"No performance risk stands out in internal/runtime/agent/runner_core.go from the delegated evidence. Confidence: medium.",
	}
	requests := 0

	var roles []string

	server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		defer ginkgo.GinkgoRecover()
		if requests >= len(replies) {
			ginkgo.Fail(fmt.Sprintf("unexpected extra chat request #%d; roles=%v", requests, roles), 1)
		}

		reply := replies[requests]
		requests++

		_ = json.NewEncoder(w).Encode(map[string]any{
			"choices": []map[string]any{{
				"message": map[string]string{"content": reply},
			}},
		})
	}))

	defer server.Close()

	var (
		sawChildTaskResult        bool
		parentModelCallAfterChild bool
	)

	runner := newRunnerRunFixture(&Runner{
		Client: llama.NewClient(server.URL, 2*time.Second),
		Workspace: workspace.NewManager(config.Workspace{
			Root:                root,
			CWD:                 root,
			MaxDirectoryEntries: 64,
		}),
		Policy: RunPolicy{MaxToolSteps: 8, MaxNoProgressTurns: 6},
		OnEvent: func(event RunEvent) {
			if event.Role == "next_action_state" && strings.Contains(event.Content, `"reason":"child_task_result"`) {
				sawChildTaskResult = true
			}

			if sawChildTaskResult && event.Role == "model_call" && strings.Contains(event.Content, `"agent":"main"`) {
				parentModelCallAfterChild = true
			}
		},
	})

	answer, err := runner.runner.Run(
		context.Background(),
		[]llama.ChatMessage{{Role: "user", Content: "Review performance risks in this workspace."}},
		llama.ChatOptions{},
		nil,
		nil,
		nil,
	)
	if err != nil {
		ginkgo.Fail(fmt.Sprintf("Run: %v", err), 1)
	}

	if answer != "No performance risk stands out in internal/runtime/agent/runner_core.go from the delegated evidence. Confidence: medium." {
		ginkgo.Fail(fmt.Sprintf("unexpected answer after %d/%d requests: %q", requests, len(replies), answer), 1)
	}

	if !parentModelCallAfterChild {
		ginkgo.Fail(fmt.Sprintf("expected parent model synthesis after child task result (saw child result=%t)", sawChildTaskResult), 1)
	}

	if requests != len(replies) {
		ginkgo.Fail(fmt.Sprintf("expected parent to take one post-child decision turn, used %d/%d replies", requests, len(replies)), 1)
	}
})

