var _ = ginkgo.It("DelegatedReadOnlyAnswerReadyAfterDiscoveryQuery", func() {
	results := []workspace.ToolResult{{
		Tool:    "discovery_query",
		Summary: "Discovery query complete",
		Output:  `{"artifact_path":".codex/discovery/impact-analysis.json","evidence":[{"path":"internal/runtime/agent/runner_core.go","excerpt":"task child delegated_read_only"},{"path":"internal/runtime/agent/implementation_flow.go","excerpt":"child task runner"}]}`,
	}}
	runner := newRunnerRunFixture(&Runner{
		AgentName: "child:explorer",
		RuntimeBrief: workerruntime.WorkerRuntimeBrief{
			TaskFamily:        "delegated_read_only",
			Objective:         "Explain child discovery.",
			PermissionProfile: "read_only_workspace",
		},
	})

	// A lone discovery_query should NOT mark readiness — the model
	// must also read at least one source body before the harness
	// restricts further reads.
	ready := runner.delegatedReadOnlyAnswerReadyAfterResult(
		workspace.ToolRequest{Tool: "discovery_query"},
		results[0],
		results,
	)
	if ready {
		ginkgo.Fail("discovery_query alone should not mark readiness without a source body read", 1)
	}

	// After discovery_query + two source body reads, readiness should fire.
	resultsWithRead := append(results,
		readFileSourceWindowResult("internal/runtime/agent/runner_core.go", 1, 200, 200, "package agent\nfunc runChildTask() {}"),
		readFileSourceWindowResult("internal/runtime/agent/implementation_flow.go", 1, 100, 100, "package agent\nfunc handleChildTask() {}"),
	)

	ready = runner.delegatedReadOnlyAnswerReadyAfterResult(
		workspace.ToolRequest{Tool: "read_file"},
		resultsWithRead[2],
		resultsWithRead,
	)

	if !ready {
		ginkgo.Fail("discovery_query plus source body reads should mark readiness", 1)
	}

	mutationRunner := *runner

	mutationRunner.state.runtimeBrief.Contract = "implementation"

	if mutationRunner.delegatedReadOnlyAnswerReadyAfterResult(workspace.ToolRequest{Tool: "discovery_query"}, results[0], results) {
		ginkgo.Fail("did not expect answer-ready shortcut for mutation-required child", 1)
	}

	failingResult := results[0]

	failingResult.Error = "discovery failed"

	if runner.delegatedReadOnlyAnswerReadyAfterResult(workspace.ToolRequest{Tool: "discovery_query"}, failingResult, []workspace.ToolResult{failingResult}) {
		ginkgo.Fail("did not expect answer-ready shortcut after failed discovery", 1)
	}
})

