var _ = ginkgo.It("CompletionGateTaskLedgerProgressRequiresProducerObservedItemContraction", func() {
	ledger := newTaskLedgerStateFixture(TaskLedgerPolicy{Required: true})
	ledger.created = true
	ledger.items = []workspace.TaskLedgerItem{
		{ID: "a", Content: "first", Status: "pending"},
		{ID: "b", Content: "second", Status: "pending"},
	}
	first, rejected := ledger.completionRejection("done", workerruntime.WorkerRuntimeBrief{})
	if !rejected {
		ginkgo.Fail("expected unfinished task ledger rejection", 1)
	}
	envelope, ok := completionGateRecoveryEnvelopeFromResult(first)
	if !ok || !slices.Equal(envelope.PendingObligationIDs, []string{"a", "b"}) {
		ginkgo.Fail(fmt.Sprintf("task ledger producer omitted item obligations: %#v", first), 1)
	}

	state := runnerRunState{}
	state.recordCompletionGateRejection(first)
	success := workspace.ToolResult{Tool: workspace.ToolNameTaskLedger, Summary: "Updated task ledger"}
	if progress := state.observeCompletionGateEvidenceProgress(workspace.ToolRequest{Tool: workspace.ToolNameTaskLedger}, success); progress.MadeProgress() {
		ginkgo.Fail(fmt.Sprintf("successful task_ledger call resolved progress before producer re-evaluation: %#v", progress), 1)
	}
	unrelated := workspace.ToolResult{Tool: workspace.ToolNameReadFile, Paths: []string{"README.md"}}
	if progress := state.observeCompletionGateEvidenceProgress(workspace.ToolRequest{Tool: workspace.ToolNameReadFile, Path: "README.md"}, unrelated); progress.MadeProgress() {
		ginkgo.Fail(fmt.Sprintf("unrelated result advanced task-ledger recovery: %#v", progress), 1)
	}

	ledger.items[0].Status = "completed"
	second, rejected := ledger.completionRejection("done", workerruntime.WorkerRuntimeBrief{})
	if !rejected {
		ginkgo.Fail("expected one remaining task ledger item", 1)
	}
	if prior := state.completionGateRecovery.PriorAttemptsFor(second); prior != 0 {
		ginkgo.Fail(fmt.Sprintf("partial item completion prior attempts = %d, want 0", prior), 1)
	}
	state.recordCompletionGateRejection(second)
	if state.completionGateRecovery.ActiveViolation.AttemptsSinceProgress != 1 ||
		!slices.Equal(state.completionGateRecovery.ActiveViolation.PendingObligationIDs, []string{"b"}) {

		ginkgo.Fail(fmt.Sprintf("task ledger contraction did not reset typed local state: %#v", state.completionGateRecovery), 1)
	}
})

