var _ = ginkgo.It("CompletionGatePathOnlySourceRecoveryRequiresCurrentProducerWindow", func() {
	t := ginkgo.GinkgoT()
	root := t.TempDir()
	path := "target.go"
	if err := writeTestFile(root, path, "package target\n\nconst Value = 1\n"); err != nil {
		ginkgo.Fail(fmt.Sprintf("seed target: %v", err), 1)
	}
	manager := workspace.NewManager(config.Workspace{Root: root, CWD: root, EnableWrites: true})
	ctx := context.Background()
	stale := manager.Execute(ctx, workspace.ToolRequest{Tool: workspace.ToolNameReadFile, Path: path, StartLine: 1, EndLine: 3})
	if stale.Error != "" || len(stale.SourceWindows()) != 1 {
		ginkgo.Fail(fmt.Sprintf("produce source window: %#v", stale), 1)
	}
	write := manager.Execute(ctx, workspace.ToolRequest{
		Tool: workspace.ToolNameEditFile, Path: path,
		OldText: "const Value = 1", NewText: "const Value = 2", Description: "advance source revision",
	})
	if write.Error != "" || write.CommitReceipt() == nil {
		ginkgo.Fail(fmt.Sprintf("advance source revision: %#v", write), 1)
	}

	state := runnerRunState{sourceWindowCurrent: func(evidence toolfacts.SourceWindowEvidence) bool {
		current, err := manager.SourceWindowCurrent(ctx, evidence)
		return err == nil && current
	}}
	state.recordCompletionGateRejection(completionGateRejectionWithRecovery(
		"Completion gate rejected source prerequisite",
		"fresh source body remains required",
		newCompletionGateRecoveryEnvelope(completionGateInvariantPlanAnchorRefresh, completionGateViolationPlanAnchorRefresh, completionGateViolationSourceEvidence, []string{path}),
	))

	if progress := state.observeCompletionGateEvidenceProgress(workspace.ToolRequest{Tool: workspace.ToolNameReadFile, Path: path}, stale); progress.MadeProgress() {
		ginkgo.Fail(fmt.Sprintf("stale producer window advanced source recovery: %#v", progress), 1)
	}
	if got := state.completionGateRecovery.ActiveViolation.AttemptsSinceProgress; got != 1 {
		ginkgo.Fail(fmt.Sprintf("stale window reset the active retry streak: %#v", state.completionGateRecovery), 1)
	}

	fresh := manager.Execute(ctx, workspace.ToolRequest{Tool: workspace.ToolNameReadFile, Path: path, StartLine: 1, EndLine: 3})
	if fresh.Error != "" || len(fresh.SourceWindows()) != 1 {
		ginkgo.Fail(fmt.Sprintf("produce fresh source window: %#v", fresh), 1)
	}
	progress := state.observeCompletionGateEvidenceProgress(workspace.ToolRequest{Tool: workspace.ToolNameReadFile, Path: path}, fresh)
	if !progress.MadeProgress() || !slices.Equal(progress.SatisfiedSourceBodyPaths, []string{path}) || state.completionGateRecovery.ActiveViolation.Class != "" {
		ginkgo.Fail(fmt.Sprintf("fresh producer window did not resolve source recovery: progress=%#v state=%#v", progress, state.completionGateRecovery), 1)
	}
})

