var _ = ginkgo.It("VerificationPlanAuthorizationPreservesWhitespaceInsideQuotedArguments", func() {
	target := "internal/library/dependency.go"
	brief := workerruntime.WorkerRuntimeBrief{VerificationPlan: []string{`go test -run "Test A" ./pkg`}}
	_, write := committedMutationResultForTest(target)
	receipts := []workspace.MutationCommitProjection{write.CommitReceipt().DurableProjection()}

	spoofed := shellCommandResultForTest(`go test -run "Test   A" ./pkg`, "ok\tidiom/pkg [no tests to run]", "")
	if !postWriteVerificationLedgerForReceipts([]workspace.ToolResult{write, spoofed}, brief, receipts).Pending() {
		ginkgo.Fail("quote-internal whitespace change must not inherit VerificationPlan authority", 1)
	}

	interTokenSpacingChanged := shellCommandResultForTest(`go   test -run "Test A" ./pkg`, "ok\tidiom/pkg", "")
	if !postWriteVerificationLedgerForReceipts([]workspace.ToolResult{write, interTokenSpacingChanged}, brief, receipts).Pending() {
		ginkgo.Fail("inter-token whitespace change must not inherit exact VerificationPlan authority", 1)
	}

	exact := shellCommandResultForTest(`  go test -run "Test A" ./pkg  `, "ok\tidiom/pkg", "")
	if ledger := postWriteVerificationLedgerForReceipts([]workspace.ToolResult{write, exact}, brief, receipts); ledger.Pending() {
		ginkgo.Fail(fmt.Sprintf("raw-trimmed exact VerificationPlan command did not clear its obligation: %#v", ledger), 1)
	}

	expansionBrief := workerruntime.WorkerRuntimeBrief{VerificationPlan: []string{`go test -run '$(echo TestA)' ./pkg`}}
	doubleQuoted := shellCommandResultForTest(`go test -run "$(echo TestA)" ./pkg`, "ok\tidiom/pkg [no tests to run]", "")
	if !postWriteVerificationLedgerForReceipts([]workspace.ToolResult{write, doubleQuoted}, expansionBrief, receipts).Pending() {
		ginkgo.Fail("single-quoted and double-quoted shell expansions must not share VerificationPlan authority", 1)
	}

	customBrief := workerruntime.WorkerRuntimeBrief{VerificationPlan: []string{"make verify && ./scripts/check"}}
	custom := shellCommandResultForTest("  make verify && ./scripts/check  ", "verification passed", "")
	if ledger := postWriteVerificationLedgerForReceipts([]workspace.ToolResult{write, custom}, customBrief, receipts); ledger.Pending() {
		ginkgo.Fail(fmt.Sprintf("exact caller-authorized custom verification command did not clear its obligation: %#v", ledger), 1)
	}
})

