var _ = ginkgo.It("CompletionGateRecoveryMessageReplacesPriorState", func() {
	state := runnerRunState{turnMessages: []llama.ChatMessage{{Role: "user", Content: "question"}}}
	first := sourceGroundingUnsupportedDetailReferenceAssessment(sourceReferencesForPaths([]string{"first.go"}))
	second := sourceGroundingUnsupportedDetailReferenceAssessment(sourceReferencesForPaths([]string{"second.go"}))

	for _, assessment := range []sourceGroundingAssessment{first, second} {
		result := annotateSourceGroundingAssessment(workspace.ToolResult{
			Tool:    completionGateToolName,
			Summary: "Completion gate rejected source grounding",
			Error:   assessment.Message(),
		}, assessment)
		state.recordCompletionGateRejection(result)
		state.setCompletionGateRecoveryMessage(assessment.RecoveryPrompt(""))
	}

	count := 0
	for _, message := range state.turnMessages {
		if !strings.HasPrefix(strings.TrimSpace(message.Content), completionGateRecoveryMessageTag) {
			continue
		}
		count++
		if strings.Contains(message.Content, "first.go") || !strings.Contains(message.Content, "second.go") {
			ginkgo.Fail(fmt.Sprintf("recovery message was not replaced with current state: %q", message.Content), 1)
		}
	}
	if count != 1 {
		ginkgo.Fail(fmt.Sprintf("tagged recovery message count = %d, want 1: %#v", count, state.turnMessages), 1)
	}
})

var _ = ginkgo.It("CompletionGateRecoveryUsesActiveStreakAndMonotonicAuditCount", func() {
	result := workspace.ToolResult{Tool: completionGateToolName, Summary: "Rejected", Error: "contract unmet"}
	state := runnerRunState{}
	retryLimit := 2

	for attempt := 1; attempt <= retryLimit+1; attempt++ {
		state.recordCompletionGateRejection(result)
		wantRetry := attempt <= retryLimit
		if got := state.completionGateRecovery.CanRetryActive(retryLimit); got != wantRetry {
			ginkgo.Fail(fmt.Sprintf("attempt %d retry = %t, want %t", attempt, got, wantRetry), 1)
		}
	}
	if got := state.completionGateRecovery.TotalAttempts; got != retryLimit+1 {
		ginkgo.Fail(fmt.Sprintf("total attempts = %d, want %d", got, retryLimit+1), 1)
	}

	different := completionGateRejectionWithRecovery(
		"Mutation completion gate rejected final answer",
		"workspace changes are present, but verification is still required",
		newCompletionGateRecoveryEnvelope(completionGateInvariantPostWriteVerification, "post_write_verification_pending", completionGateViolationVerification, []string{"internal/runtime/agent/runner_core.go"}),
	)
	state.recordCompletionGateRejection(different)
	if state.completionGateRecovery.ActiveViolation.Class != completionGateViolationVerification ||
		state.completionGateRecovery.ActiveViolation.AttemptsSinceProgress != 1 ||
		state.completionGateRecovery.TotalAttempts != retryLimit+2 {

		ginkgo.Fail(fmt.Sprintf("materially different violation did not start a fresh active streak: %#v", state.completionGateRecovery), 1)
	}
})

