var _ = ginkgo.It("CompletionGateRecoveryRestartsLocalStreakOnTypedObligationContraction", func() {
	first := "internal/a.go"
	second := "internal/b.go"
	state := runnerRunState{}

	planEnvelope := newCompletionGateRecoveryEnvelope(completionGateInvariantPlanSubmission, "submit_plan_correction_pending", completionGateViolationPlanSubmission, []string{first, second})
	state.recordCompletionGateRejection(completionGateRejectionWithRecovery("first wording", "plan rejected", planEnvelope))
	state.recordCompletionGateRejection(completionGateRejectionWithRecovery("different wording", "plan still rejected", planEnvelope))
	if state.completionGateRecovery.ActiveViolation.AttemptsSinceProgress != 2 {
		ginkgo.Fail(fmt.Sprintf("unchanged typed obligations did not preserve streak: %#v", state.completionGateRecovery), 1)
	}

	planEnvelope.PendingPaths = []string{second}
	contracted := completionGateRejectionWithRecovery("copy changed again", "only b remains", planEnvelope)
	prior := state.completionGateRecovery.PriorAttemptsFor(contracted)
	if prior != 0 {
		ginkgo.Fail(fmt.Sprintf("strict typed contraction prior attempts = %d, want 0", prior), 1)
	}
	runner := newRunnerRunFixture(&Runner{})
	if escalated := runner.escalateCompletionGateResultMessage(contracted, prior, nil); escalated != contracted.Error {
		ginkgo.Fail(fmt.Sprintf("first post-contraction message was mislabeled as a repeat: %q", escalated), 1)
	}
	state.recordCompletionGateRejection(contracted)
	if state.completionGateRecovery.ActiveViolation.AttemptsSinceProgress != 1 || state.completionGateRecovery.TotalAttempts != 3 {
		ginkgo.Fail(fmt.Sprintf("strict typed contraction did not restart local streak without resetting audit count: %#v", state.completionGateRecovery), 1)
	}

	planEnvelope.PendingPaths = []string{first, second}
	state.recordCompletionGateRejection(completionGateRejectionWithRecovery("expanded", "a returned", planEnvelope))
	if state.completionGateRecovery.ActiveViolation.AttemptsSinceProgress != 2 {
		ginkgo.Fail(fmt.Sprintf("obligation expansion incorrectly counted as progress: %#v", state.completionGateRecovery), 1)
	}
})

