var _ = ginkgo.It("SourceGroundingRetryPreservesEveryTypedRecoveryStrategy", func() {
	runner, controller := newRunnerTurnControllerFixture(&Runner{
		RuntimeBrief: workerruntime.WorkerRuntimeBrief{
			TaskFamily:        string(autonomy.TaskFamilyDirectAnswer),
			Contract:          string(workerruntime.ContractDirectAnswer),
			PermissionProfile: "read_only_workspace",
			AllowedTools:      []string{"read_file", "code_navigate", "search_content"},
		},
	})

	runner.state.currentAllowedTools = []string{"read_file", "code_navigate", "search_content"}
	runner.state.toolSurface = NewActiveSurface([]string{"read_file", "code_navigate", "search_content"}, nil)
	runState := &runner.state
	sourceGroundingAssessment := sourceGroundingUnsupportedDetailReferenceAssessment(sourceReferencesForPaths([]string{"src/graphics/renderer.rs"}))
	sourceGroundingErr := sourceGroundingAssessment.Message()
	sourceGroundingResult := annotateSourceGroundingAssessment(workspace.ToolResult{Tool: "completion_gate", Summary: "Rejected", Error: sourceGroundingErr}, sourceGroundingAssessment)
	sourceGroundingAcceptance := rejectFinalAnswerAcceptanceWithSourceGrounding(newFinalAnswerAcceptance(), sourceGroundingAssessment)
	retried := runner.retryRejectedFinalAnswerForRun(runnerFinalAnswerRetryInput{
		stepNumber: 1,
		assistantMessage: llama.ChatMessage{
			Role:    "assistant",
			Content: "The renderer uses src/graphics/renderer.rs.",
		},
		acceptance: sourceGroundingAcceptance,
		result:     sourceGroundingResult,
		controller: controller,
	})
	if !retried {
		ginkgo.Fail("source-grounding rejection should be retryable", 1)
	}
	for _, tool := range []string{"search_content", "read_file", "code_navigate"} {
		if !slices.Contains(runState.currentAllowedTools, tool) {
			ginkgo.Fail(fmt.Sprintf("typed source-grounding recovery must keep %s callable", tool), 1)
		}
	}
	recoveryMessage := ""
	for _, message := range runState.turnMessages {
		if strings.HasPrefix(strings.TrimSpace(message.Content), completionGateRecoveryMessageTag) {
			recoveryMessage = message.Content
		}
	}
	for _, strategy := range []string{"read one body-readable", "rewrite the answer", "qualify", "materially different", "<<QUESTION>>"} {
		if !strings.Contains(recoveryMessage, strategy) {
			ginkgo.Fail(fmt.Sprintf("typed recovery message dropped strategy %q:\n%s", strategy, recoveryMessage), 1)
		}
	}
	if strings.Contains(recoveryMessage, "next visible action must be exactly one bounded") {
		ginkgo.Fail(fmt.Sprintf("source-grounding recovery still contains the forced-read contradiction:\n%s", recoveryMessage), 1)
	}

	noReadToolRunner, noReadController := newRunnerTurnControllerFixture(&Runner{
		RuntimeBrief: workerruntime.WorkerRuntimeBrief{
			TaskFamily:        string(autonomy.TaskFamilyDirectAnswer),
			Contract:          string(workerruntime.ContractDirectAnswer),
			PermissionProfile: "read_only_workspace",
			AllowedTools:      []string{"search_content"},
		},
	})
	noReadToolRunner.state.currentAllowedTools = []string{"search_content"}
	noReadToolRunner.state.toolSurface = NewActiveSurface([]string{"search_content"}, nil)
	noReadRunState := &noReadToolRunner.state
	retried = noReadToolRunner.retryRejectedFinalAnswerForRun(runnerFinalAnswerRetryInput{
		stepNumber: 1,
		assistantMessage: llama.ChatMessage{
			Role:    "assistant",
			Content: "The renderer uses src/graphics/renderer.rs.",
		},
		acceptance: sourceGroundingAcceptance,
		result:     sourceGroundingResult,
		controller: noReadController,
	})
	if !retried {
		ginkgo.Fail("source-grounding rejection should still be retryable under the generic read-only retry policy", 1)
	}
	if !slices.Contains(noReadRunState.currentAllowedTools, "search_content") {
		ginkgo.Fail("source-grounding retry must keep the only search tool callable when no source-body read tool is available", 1)
	}
})

