var _ = ginkgo.It("RunnerEmitsRecoveryNudgeOnRepeatedSameStemSoftFailures", func() {
	t := ginkgo.GinkgoT()
	root := t.TempDir()
	if err := writeTestFile(root, "internal/runtime/agent/runner_core.go", "package agent\n"); err != nil {
		ginkgo.Fail(fmt.Sprintf("seed: %v", err), 1)
	}

	replies := []string{
		`{"tool":"read_file","path":"internal/llm/llm.go"}`,
		`{"tool":"read_file","path":"internal/llm/openai.go"}`,
		`{"tool":"read_file","path":"internal/llm/qwen.go"}`,
		"Stopped after recovery nudge.",
	}
	requests := 0
	server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		defer ginkgo.GinkgoRecover()
		if requests >= len(replies) {
			ginkgo.Fail("unexpected extra chat request", 1)
		}

		reply := replies[requests]
		requests++

		_ = json.NewEncoder(w).Encode(map[string]any{
			"choices": []map[string]any{{"message": map[string]string{"content": reply}}},
		})
	}))

	defer server.Close()

	mgr := workspace.NewManager(config.Workspace{
		Root:                root,
		CWD:                 root,
		MaxDirectoryEntries: 128,
	})

	var nudgeEmitted bool

	runner := newRunnerRunFixture(&Runner{
		Client:    llama.NewClient(server.URL, 2*time.Second),
		Workspace: mgr,
		Policy:    RunPolicy{MaxToolSteps: 6, MaxNoProgressTurns: 6},
		OnEvent: func(event RunEvent) {
			if event.Role == "rejection_recovery_nudge" {
				nudgeEmitted = true
			}
		},
	})

	answer, err := runner.runner.Run(
		context.Background(),
		[]llama.ChatMessage{{Role: "user", Content: "find the llm package"}},
		llama.ChatOptions{},
		nil,
		nil,
		nil,
	)
	if err != nil {
		ginkgo.Fail(fmt.Sprintf("Run: %v", err), 1)
	}

	if !nudgeEmitted {
		ginkgo.Fail("expected rejection_recovery_nudge after 3 same-stem soft failures", 1)
	}

	if answer != "Stopped after recovery nudge." {
		ginkgo.Fail(fmt.Sprintf("unexpected answer: %q", answer), 1)
	}
})

// TestDoomLoopGateDenyPathStops verifies that when a DoomLoopGate is wired and
// returns false, the runner stops with stop_reason=doom_loop_guard after
// forcing a no-tools closeout from gathered evidence. Proves the gate is
// reachable and its deny path does not return an empty answer.
var _ = ginkgo.It("DoomLoopGateDenyPathStops", func() {
	t := ginkgo.GinkgoT()
	root := t.TempDir()
	if err := writeTestFile(root, "internal/surfaces/tui/app/app.go", "package app\n"); err != nil {
		ginkgo.Fail(fmt.Sprintf("write seed file: %v", err), 1)
	}

	replies := []string{
		`{"tool":"list_files","path":".","recursive":true}`,
		`{"tool":"list_files","path":".","recursive":true}`,
		`{"tool":"list_files","path":".","recursive":true}`,
		"Answered after doom-loop denial.",
	}

	var requests int

	server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		defer ginkgo.GinkgoRecover()
		if requests >= len(replies) {
			ginkgo.Fail(fmt.Sprintf("unexpected extra chat request (%d)", requests), 1)
		}

		reply := replies[requests]
		requests++

		_ = json.NewEncoder(w).Encode(map[string]any{
			"choices": []map[string]any{{
				"message": map[string]string{"content": reply},
			}},
		})
	}))

	defer server.Close()

	mgr := workspace.NewManager(config.Workspace{Root: root, CWD: root})
	if err := mgr.SetMode(workspace.ModeExplore); err != nil {
		ginkgo.Fail(fmt.Sprintf("set explore mode: %v", err), 1)
	}

	gateCalls := 0
	runner := newRunnerRunFixture(&Runner{
		Client:    llama.NewClient(server.URL, time.Second),
		Workspace: mgr,
		Policy:    RunPolicy{MaxNoProgressTurns: 6},
		DoomLoopGate: func(req workspace.ToolRequest, count int) bool {
			gateCalls++

			if count < 3 {
				ginkgo.Fail(fmt.Sprintf("gate invoked with count=%d, expected >=3", count), 1)
			}

			return false
		},
	})

	var stopReason string

	runner.runner.OnEvent = func(event RunEvent) {
		if event.Role == "budget_ledger" {
			var ledger runnerBudgetLedger

			if err := json.Unmarshal([]byte(event.Content), &ledger); err == nil {
				stopReason = ledger.StopReason
			}
		}
	}

	answer, err := runner.runner.Run(
		context.Background(),
		[]llama.ChatMessage{{Role: "user", Content: "loop on broad listing"}},
		llama.ChatOptions{},
		nil,
		nil,
		nil,
	)
	if err != nil {
		ginkgo.Fail(fmt.Sprintf("Run: %v", err), 1)
	}

	if gateCalls != 1 {
		ginkgo.Fail(fmt.Sprintf("expected DoomLoopGate to be called exactly once, got %d", gateCalls), 1)
	}

	if stopReason != "doom_loop_guard" {
		ginkgo.Fail(fmt.Sprintf("expected stop_reason=doom_loop_guard, got %q", stopReason), 1)
	}

	if answer != "Answered after doom-loop denial." {
		ginkgo.Fail(fmt.Sprintf("expected forced closeout answer, got %q", answer), 1)
	}

	if requests != 4 {
		ginkgo.Fail(fmt.Sprintf("expected three loop requests plus one forced closeout, got %d", requests), 1)
	}
})

