// runNudgeScenario drives a canned model transcript against Runner.Run and
// returns the set of emitted event roles. Used by the nudge tests below to
// assert that soft-budget nudges fire the expected number of times without
// recreating the httptest scaffold each time.
func runNudgeScenario(t ginkgo.FullGinkgoTInterface, policy RunPolicy, replies []string) (events []RunEvent, requests int) {
	t.Helper()

	root := t.TempDir()
	if err := writeTestFile(root, "internal/surfaces/tui/app/app.go", "package app\n"); err != nil {
		ginkgo.Fail(fmt.Sprintf("write seed: %v", err), 1)
	}

	if err := writeTestFile(root, "internal/runtime/agent/runner_core.go", "package agent\n"); err != nil {
		ginkgo.Fail(fmt.Sprintf("write seed: %v", err), 1)
	}

	server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		defer ginkgo.GinkgoRecover()
		if requests >= len(replies) {
			ginkgo.Fail(fmt.Sprintf("unexpected extra chat request (%d)", requests), 1)
		}

		reply := replies[requests]
		requests++

		_ = json.NewEncoder(w).Encode(map[string]any{
			"choices": []map[string]any{{"message": map[string]string{"content": reply}}},
		})
	}))
	t.Cleanup(server.Close)

	mgr := workspace.NewManager(config.Workspace{Root: root, CWD: root})
	if err := mgr.SetMode(workspace.ModeExplore); err != nil {
		ginkgo.Fail(fmt.Sprintf("set explore mode: %v", err), 1)
	}

	runner := newRunnerRunFixture(&Runner{
		Client:    llama.NewClient(server.URL, time.Second),
		Workspace: mgr,
		Policy:    policy,
		OnEvent: func(event RunEvent) {
			events = append(events, event)
		},
	})

	_, err := runner.runner.Run(
		context.Background(),
		[]llama.ChatMessage{{Role: "user", Content: "nudge scenario"}},
		llama.ChatOptions{},
		nil,
		nil,
		nil,
	)
	if err != nil {
		ginkgo.Fail(fmt.Sprintf("Run: %v", err), 1)
	}

	return events, requests
}

func countEventsByRole(events []RunEvent, role string) int {
	n := 0

	for _, ev := range events {
		if ev.Role == role {
			n++
		}
	}

	return n
}

