var _ = ginkgo.It("PlanExecuteFailureFeedbackUsesRunStateTransportAfterNativeFallback", func() {
	brief := workerruntime.WorkerRuntimeBrief{
		Lane:              "main",
		TaskFamily:        PlanThenExecutePlannerTaskFamily,
		Contract:          "implementation_result",
		PermissionProfile: "guarded_workspace_write",
		AllowedTools:      []string{workspace.ToolNameSubmitPlan},
		RequiredEditPaths: []string{"a.go"},
	}
	sourceReady := readFileSourceWindowResult("a.go", 1, 10, 10, "1:package a\n")
	results := []workspace.ToolResult{sourceReady}
	runState := &runnerRunState{
		runtimeBrief:                            brief,
		collectedResults:                        append([]workspace.ToolResult(nil), results...),
		currentAllowedTools:                     []string{workspace.ToolNameSubmitPlan},
		planThenExecuteNativeSubmitPlanDisabled: true,
	}

	var nextAction runnerNextActionState
	var failure runnerFailureFeedbackPacket
	var events []RunEvent
	runner := newRunnerRunFixture(&Runner{
		Client:       llama.NewClient("http://example.invalid", time.Second).WithBackend(config.BackendLlama),
		AgentName:    "main",
		RuntimeBrief: brief,
		OnEvent: func(event RunEvent) {
			events = append(events, event)
			switch event.Role {
			case "next_action_state":
				if err := json.Unmarshal([]byte(event.Content), &nextAction); err != nil {
					ginkgo.Fail(fmt.Sprintf("unmarshal next_action_state: %v\n%s", err, event.Content), 1)
				}
			case "failure_feedback":
				if err := json.Unmarshal([]byte(event.Content), &failure); err != nil {
					ginkgo.Fail(fmt.Sprintf("unmarshal failure_feedback: %v\n%s", err, event.Content), 1)
				}
			}
		},
	})
	runner.state = *runState
	recorder := runnerTurnRecorder{
		runner: runner,
	}
	rejected := workspace.ToolResult{
		Tool:    workspace.ToolNameSubmitPlan,
		Summary: "submit_plan rejected after textual fallback",
		Error:   "submit_plan JSON object required",
	}

	recorder.recordWithOptions(2, workspace.ToolRequest{Tool: workspace.ToolNameSubmitPlan}, rejected, "tool_rejected", runnerRecordOptions{})

	if nextAction.RecoveryState == nil {
		ginkgo.Fail(fmt.Sprintf("missing recovery state in next-action event: %#v", events), 1)
	}
	if nextAction.RecoveryState.PhaseID != contractcompile.TurnPhaseSubmitReadyTextual {
		ginkgo.Fail(fmt.Sprintf("next-action phase = %q, want textual fallback phase %q", nextAction.RecoveryState.PhaseID, contractcompile.TurnPhaseSubmitReadyTextual), 1)
	}
	if strings.Contains(nextAction.RecoveryState.RecoveryCardProtocolProjectionID, string(contractcompile.TurnPhaseSubmitReadyNativeRequired)) {
		ginkgo.Fail(fmt.Sprintf("next-action recovery state leaked native projection after fallback: %#v", nextAction.RecoveryState), 1)
	}
	if !strings.Contains(failure.RecoveryCard, string(contractcompile.TurnPhaseSubmitReadyTextual)) {
		ginkgo.Fail(fmt.Sprintf("failure feedback should use textual fallback projection, got:\n%s", failure.RecoveryCard), 1)
	}
	if strings.Contains(failure.RecoveryCard, string(contractcompile.TurnPhaseSubmitReadyNativeRequired)) {
		ginkgo.Fail(fmt.Sprintf("failure feedback leaked native projection after fallback:\n%s", failure.RecoveryCard), 1)
	}
})

var _ = ginkgo.It("RunnerFailureFeedbackUsesForcedNativeTransportForToolParseRecovery", func() {
	brief := workerruntime.WorkerRuntimeBrief{
		Lane:              "main",
		TaskFamily:        "conversation",
		Contract:          "direct_answer",
		PermissionProfile: "read_only_workspace",
		AllowedTools:      []string{workspace.ToolNameSearchContent},
	}
	rejected := workspace.ToolResult{
		Tool:    "tool_parse",
		Summary: "Malformed tool request rejected",
		Error:   "malformed DeepSeek XML tool request",
	}

	packet := buildRunnerFailureFeedbackPacketWithAllowedToolsAndTransport(
		"main",
		14,
		"tool_parse_rejected",
		workspace.ToolRequest{Tool: "tool_parse"},
		rejected,
		nil,
		false,
		brief,
		brief.AllowedTools,
		PlanExecutePlanningTransport{ForceNativeTools: true},
		implementationCompletionState{}, planThenExecutePathAuthority{})

	requiredNext := strings.Join(packet.RequiredNext, "\n")
	if !strings.Contains(requiredNext, "active native tool-call transport") {
		ginkgo.Fail(fmt.Sprintf("forced-native tool_parse feedback required_next did not preserve native transport: %#v", packet.RequiredNext), 1)
	}
	if strings.Contains(requiredNext, "valid JSON tool object") {
		ginkgo.Fail(fmt.Sprintf("forced-native tool_parse feedback still asked for textual JSON: %#v", packet.RequiredNext), 1)
	}
	if strings.Contains(strings.Join(packet.ValidNext, "\n"), "valid JSON tool object") {
		ginkgo.Fail(fmt.Sprintf("forced-native tool_parse valid_next still asked for textual JSON: %#v", packet.ValidNext), 1)
	}
	if strings.Count(strings.Join(packet.ValidNext, "\n"), "active native tool-call transport") != 1 {
		ginkgo.Fail(fmt.Sprintf("forced-native tool_parse valid_next duplicated native guidance: %#v", packet.ValidNext), 1)
	}
	if packet.FailedTool == "tool_parse" {
		ginkgo.Fail(fmt.Sprintf("forced-native tool_parse feedback leaked fake failed tool: %#v", packet), 1)
	}
	if strings.Contains(packet.ResultError, "valid tool call") {
		ginkgo.Fail(fmt.Sprintf("forced-native tool_parse feedback kept generic parser wording: %q", packet.ResultError), 1)
	}
	if strings.Contains(strings.Join(packet.DoNotRepeat, "\n"), "same tool_parse request") {
		ginkgo.Fail(fmt.Sprintf("forced-native tool_parse feedback leaked fake repeat target: %#v", packet.DoNotRepeat), 1)
	}
	if strings.Contains(packet.RecoveryCard, "tool=tool_parse") || strings.Contains(packet.RecoveryCard, "action_class=tool_parse") {
		ginkgo.Fail(fmt.Sprintf("forced-native tool_parse recovery card leaked fake tool/action:\n%s", packet.RecoveryCard), 1)
	}
})

