	if err := writeTestFile(root, rejectedPath, "package workerruntime\n"); err != nil {
		ginkgo.Fail(fmt.Sprintf("write rejected target fixture: %v", err), 1)
	}
	manager := workspace.NewManager(config.Workspace{Root: root, CWD: root, EnableWrites: true})
