// TestTargetWriteReadyStagedNudgeSurfacesBasePrompt verifies that
// the nudge output includes the concrete sourced-path info from
// basePrompt when it is provided.
var _ = ginkgo.It("CompleteWithoutMoreToolsInjectsToolResultForDanglingToolCalls", func() {
	t := ginkgo.GinkgoT()
	messages := []llama.ChatMessage{
		{Role: "user", Content: "test"},
		{Role: "assistant", ToolCalls: []llama.ToolCall{{
			ID:       "call_dangling_1",
			Type:     "function",
			Function: llama.ToolCallFunc{Name: "search_content", Arguments: `{"pattern":"test"}`},
		}}},
	}
	root := t.TempDir()
	ws := workspace.NewManager(config.Workspace{Root: root, CWD: root})

	type requestMessage struct {
		Role       string           `json:"role"`
		Content    string           `json:"content,omitempty"`
		ToolCallID string           `json:"tool_call_id,omitempty"`
		ToolCalls  []llama.ToolCall `json:"tool_calls,omitempty"`
	}
	type requestPayload struct {
		Messages []requestMessage `json:"messages"`
	}

	var got requestPayload
	server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		defer ginkgo.GinkgoRecover()
		if err := json.NewDecoder(r.Body).Decode(&got); err != nil {
			ginkgo.Fail(fmt.Sprintf("decode request: %v", err), 1)
		}
		_, _ = w.Write([]byte(`{"choices":[{"message":{"role":"assistant","content":"final answer from evidence"}}]}`))
	}))
	defer server.Close()

	runner := newRunnerRunFixture(&Runner{
		Workspace: ws,
		Client:    llama.NewClient(server.URL, time.Second),
		RuntimeBrief: workerruntime.WorkerRuntimeBrief{
			TaskFamily:        "conversation",
			Contract:          "direct_answer",
			PermissionProfile: "read_only_workspace",
			Objective:         "answer from gathered evidence",
		},
	})

	answer, err := runner.completeWithoutMoreToolsWithReasonMode(context.Background(), messages, llama.ChatOptions{}, nil, "tools are now disabled", nil, noToolsCloseoutModelAllowed)
	if err != nil {
		ginkgo.Fail(fmt.Sprintf("completeWithoutMoreToolsWithReasonMode: %v", err), 1)
	}
	if answer != "final answer from evidence" {
		ginkgo.Fail(fmt.Sprintf("answer = %q", answer), 1)
	}

	if len(got.Messages) < 4 {
		ginkgo.Fail(fmt.Sprintf("request messages = %#v, want repaired tool-call pair and forced answer prompt", got.Messages), 1)
	}
	if got.Messages[1].Role != "assistant" || len(got.Messages[1].ToolCalls) != 1 {
		ginkgo.Fail(fmt.Sprintf("message[1] should be assistant tool_calls, got %#v", got.Messages), 1)
	}
	if got.Messages[2].Role != "tool" || got.Messages[2].ToolCallID != "call_dangling_1" {
		ginkgo.Fail(fmt.Sprintf("dangling assistant tool_call must be followed by synthetic tool result, got %#v", got.Messages), 1)
	}
	if got.Messages[3].Role != "system" || !strings.Contains(strings.ToLower(got.Messages[3].Content), "tools are now disabled") {
		ginkgo.Fail(fmt.Sprintf("forced answer prompt should follow repaired tool result, got %#v", got.Messages), 1)
	}
})

var _ = ginkgo.It("CompletionGateRejectsTextualXMLToolMarkup", func() {
	// Real payloads from live DeepSeek sessions that emitted XML
	// instead of proper tool calls or prose.
	xmlPayloads := []string{
		// DeepSeek's n_tool_calls format
		`<n_tool_calls>
<n_invoke name="code_navigate">
<n_parameter name="capability" string="true">find_symbol</n_parameter>
<n_parameter name="path" string="true">internal/runtime/agent</n_parameter>
</n_invoke>
</n_tool_calls>`,
		// Bare open tag
		"<n_tool_calls>",
		// DeepSeek janus format
		`<janus_tool_calls>
<janus_invoke name="read_file">
<janus_parameter name="path" string="true">internal/runtime/agent/runner_core.go</janus_parameter>
</janus_invoke>
</janus_tool_calls>`,
		// Generic invoke XML
		`<invoke name="context_pack">
<parameter name="task" string="true">find validation</parameter>
</invoke>`,
		// Mixed prose with XML - the model might wrap XML in text
		"Let me check that.\n\n<n_tool_calls>\n<n_invoke name=\"search_content\">\n</n_invoke>\n</n_tool_calls>",
		// tool_call XML variant
		`<tool_call>
<function name="read_file">
<parameter name="path">test.go</parameter>
</function>
</tool_call>`,
	}

	runner := newRunnerRunFixture(&Runner{
		RuntimeBrief: workerruntime.WorkerRuntimeBrief{
			TaskFamily:        "conversation",
			Contract:          "direct_answer",
			PermissionProfile: "read_only_workspace",
			Objective:         "answer the user's question",
		},
	})

	for i, payload := range xmlPayloads {
		result, rejected := runner.completionGateRejection(payload, nil, 0, nil, false)
		if !rejected {
			ginkgo.Fail(fmt.Sprintf("payload %d: expected XML to be rejected, got accepted\npayload: %s", i, payload[:min(len(payload), 100)]), 1)

			continue
		}

		if result.Tool != "completion_gate" {
			ginkgo.Fail(fmt.Sprintf("payload %d: expected tool='completion_gate', got %q", i, result.Tool), 1)
		}

		if !strings.Contains(result.Error, "XML") && !strings.Contains(result.Error, "markup") {
			ginkgo.Fail(fmt.Sprintf("payload %d: expected error to mention XML/markup, got: %s", i, result.Error), 1)
		}
	}
})

