// TestMissingRequiredEvidenceEnforcesTargetLocation verifies that
// the target_location evidence label is structurally enforced.
var _ = ginkgo.It("MissingRequiredEvidenceEnforcesTargetLocation", func() {
	// Answer with no file paths, no changed paths in results
	missing := missingRequiredEvidence(
		[]string{"target_location"},
		newFinalEvidenceProjection("no paths here", nil, implementationCompletionState{}),
	)
	if len(missing) != 1 || missing[0] != "target_location" {
		ginkgo.Fail(fmt.Sprintf("expected missing=[target_location], got %v", missing), 1)
	}

	// Answer with a file path — satisfied
	missing = missingRequiredEvidence(
		[]string{"target_location"},
		newFinalEvidenceProjection("the code is in internal/runtime/agent/runner_core.go", nil, implementationCompletionState{}),
	)
	if len(missing) != 1 {
		ginkgo.Fail(fmt.Sprintf("an unbacked path claim must not satisfy target_location, got missing=%v", missing), 1)
	}

	missing = missingRequiredEvidence(
		[]string{"target_location"},
		newFinalEvidenceProjection("the code is in internal/runtime/agent/runner_core.go", []workspace.ToolResult{
			readFileSourceWindowResult("internal/runtime/agent/runner_core.go", 1, 2, 2, "1:package agent\n2:func run() {}"),
		}, implementationCompletionState{}),
	)
	if len(missing) != 0 {
		ginkgo.Fail(fmt.Sprintf("producer-observed target path should satisfy target_location, got missing=%v", missing), 1)
	}
})

