func newParseFailureControllerFixture(t ginkgo.FullGinkgoTInterface) (runnerTurnController, *[]RunEvent) {
	t.Helper()

	root := t.TempDir()
	runEvents := []RunEvent{}
	brief := workerruntime.WorkerRuntimeBrief{
		Lane:              "plan-execute",
		TaskFamily:        PlanThenExecutePlannerTaskFamily,
		Contract:          "submit_plan",
		PermissionProfile: "guarded_workspace_write",
		AllowedTools:      []string{"submit_plan"},
		RequiredTools:     []string{"submit_plan"},
	}
	runner, controller := newRunnerTurnControllerFixture(&Runner{
		AgentName:    "main",
		RuntimeBrief: brief,
		Workspace: workspace.NewManager(config.Workspace{
			Root: root,
			CWD:  root,
		}),
		OnEvent: func(event RunEvent) {
			runEvents = append(runEvents, event)
		},
	})
	autonomyRecorder := newRunnerAutonomyRecorder(runner, RunPolicy{}, brief, nil)
	if autonomyRecorder == nil {
		ginkgo.Fail("newRunnerAutonomyRecorder returned nil", 1)
	}
	autonomyRecorder.emitContractStarted(brief)
	runner.state.autonomyRecorder = autonomyRecorder

	return *controller, &runEvents
}

func parseFailurePolicyAndFrictionForTest(t ginkgo.FullGinkgoTInterface, runEvents []RunEvent) (*autonomy.ContractPolicyEvent, string, *autonomy.ContractGuardFrictionEvent) {
	t.Helper()

	events := decodeRunnerAutonomyEventsForTest(t, runEvents)
	var (
		policy        *autonomy.ContractPolicyEvent
		policyEventID string
		friction      *autonomy.ContractGuardFrictionEvent
	)
	for _, event := range events {
		if event.Type == autonomy.EventToolPolicyResult {
			policy = event.Policy
			policyEventID = event.EventID
		}
		if event.Type == autonomy.EventGuardFriction {
			friction = event.GuardFriction
		}
	}
	return policy, policyEventID, friction
}

var _ = ginkgo.It("RunnerTurnControllerRejectToolRecordsRejectionState", func() {
	requestBudget := newRunnerRequestBudgetState(2)
	run, controller := newRunnerTurnControllerFixture(&Runner{})
	run.state.turn.currentFingerprint = "stale|previous-request"
	controller.requestBudget = &requestBudget

	req := workspace.ToolRequest{Tool: "read_file", Path: "internal/runtime/agent/runner_core.go"}
	currentFingerprint := req.Tool + "|" + normalizedToolRequestRaw(req)

	answer, err, done := controller.rejectTool(2, nil, req, runnerToolRejection{Summary: "Read rejected", Error: "bad path"})
	if err != nil {
		ginkgo.Fail(fmt.Sprintf("rejectTool err = %v", err), 1)
	}

	if done {
		ginkgo.Fail("rejectTool done = true, want false", 1)
	}

	if answer != "" {
		ginkgo.Fail(fmt.Sprintf("rejectTool answer = %q, want empty", answer), 1)
	}

	if got := len(run.state.collectedResults); got != 1 {
		ginkgo.Fail(fmt.Sprintf("collected results = %d, want 1", got), 1)
	}

	if got := run.state.metrics.RejectedActions; got != 1 {
		ginkgo.Fail(fmt.Sprintf("RejectedActions = %d, want 1", got), 1)
	}

	if got := run.state.lifecycle.progress.consecutiveRejected; got != 1 {
		ginkgo.Fail(fmt.Sprintf("consecutiveRejected = %d, want 1", got), 1)
	}

	if got := run.state.lifecycle.progress.rejectedActions[toolActionClass(req)]; got != 1 {
		ginkgo.Fail(fmt.Sprintf("rejectedActions[%q] = %d, want 1", toolActionClass(req), got), 1)
	}

	if got := requestBudget.fingerprint.rejected[currentFingerprint].Summary; got != "Read rejected" {
		ginkgo.Fail(fmt.Sprintf("rejected fingerprint = %q, want %q", got, "Read rejected"), 1)
	}
	if _, ok := requestBudget.fingerprint.rejected["stale|previous-request"]; ok {
		ginkgo.Fail("rejection was recorded against the stale prior-request fingerprint", 1)
	}

	if run.state.turn.lastToolKey == "" {
		ginkgo.Fail("lastToolKey was not recorded", 1)
	}

	if run.state.turn.lastToolResult == nil || run.state.turn.lastToolResult.Error != "bad path" {
		ginkgo.Fail(fmt.Sprintf("lastToolResult = %#v, want recorded rejection", run.state.turn.lastToolResult), 1)
	}

	if got := len(run.state.turnMessages); got != 1 {
		ginkgo.Fail(fmt.Sprintf("turn messages = %d, want 1", got), 1)
	}
})

