var _ = ginkgo.It("FinalAnswerAcceptanceRejectsPendingPostWriteVerification", func() {
	runner := newRunnerRunFixture(&Runner{RuntimeBrief: workerruntime.WorkerRuntimeBrief{
		TaskFamily:           "implementation",
		Contract:             "implementation_result",
		PermissionProfile:    "guarded_workspace_write",
		RequiredEvidence:     []string{"changed_paths_or_noop_reason", "verification_status"},
		VerificationContract: "tests_passed_or_failed_or_skipped_with_blocker",
	}})
	results := []workspace.ToolResult{
		{Tool: "edit_file", Summary: "Edited internal/labels/labels.go", ChangedPaths: []string{"internal/labels/labels.go"}},
	}
	answer := strings.Join([]string{
		"Implemented the requested change.",
		"",
		"Changed paths:",
		"- internal/labels/labels.go",
		"",
		"Verification: blocked; workspace writes are still pending verification.",
	}, "\n")

	acceptance := runner.evaluateFinalAnswerAcceptance(answer, results)
	if acceptance.Decision != finalAnswerAcceptanceRejected ||
		acceptance.BlockerKind != string(turnViolationRequiredEvidenceUnmet) {

		ginkgo.Fail(fmt.Sprintf("pending post-write verification should block final acceptance, got decision=%q kind=%q reason=%q", acceptance.Decision, acceptance.BlockerKind, acceptance.Reason), 1)
	}
})

var _ = ginkgo.It("SourceEditsAreSemanticallyVerifiedAfterCompilerBackedSourceSanity", func() {
	brief := workerruntime.WorkerRuntimeBrief{
		TaskFamily:           "implementation",
		VerificationContract: "tests_passed_or_failed_or_skipped_with_blocker",
	}
	run := newRunnerRunFixture(&Runner{RuntimeBrief: brief})
	_, write := committedMutationResultForTest("internal/surfaces/tui/app/app.go")
	installMutationReceiptForTest(run, write)
	results := []workspace.ToolResult{
		write,
		shellCommandResultForTest("git diff --check -- internal/surfaces/tui/app/app.go", "", ""),
		{Tool: "source_sanity", Summary: "source sanity passed", Output: "internal/surfaces/tui/app/app.go: no warnings or errors via go_diagnostics", Facts: &toolfacts.ToolResultFacts{DiagnosticEvidencePaths: []string{"internal/surfaces/tui/app/app.go"}}},
	}

	latest, ok := run.latestVerificationAfterLatestSourceWrite(results)
	if !ok {
		ginkgo.Fail("expected source_sanity to be the latest verification after source write", 1)
	}

	if latest.Tool != "source_sanity" {
		ginkgo.Fail(fmt.Sprintf("latest verification: want source_sanity, got %s", latest.Tool), 1)
	}

	if run.sourceEditsNeedSemanticVerification(results) {
		ginkgo.Fail("compiler-backed source_sanity should satisfy source edit semantic verification", 1)
	}

	if !run.sourceEditsAreSemanticallyVerified(results) {
		ginkgo.Fail("compiler-backed source_sanity should mark source edits as semantically verified", 1)
	}
})

