var _ = ginkgo.It("PostWriteVerificationAcceptsFocusedHTMLSmokeCheck", func() {
	brief := workerruntime.WorkerRuntimeBrief{
		TaskFamily:           "implementation",
		Contract:             "implementation_result",
		VerificationContract: "tests_passed_or_failed_or_skipped_with_blocker",
	}
	htmlCheck := shellCommandResultForTest(
		"python3 -c \"import html.parser; html.parser.HTMLParser().feed(open('index.html').read()); print('HTML parsed OK')\"",
		"HTML parsed OK",
		"",
	)
	htmlCheck.Facts.VerificationEvidence = []toolfacts.VerificationEvidence{{
		Kind:  toolfacts.VerificationEvidenceHTMLParse,
		Paths: []string{"index.html"},
	}}
	if observation := workspace.AnalyzePostWriteVerificationResult(htmlCheck, []string{"index.html"}); !observation.Successful || !observation.RelevantToPendingWrites {
		ginkgo.Fail(fmt.Sprintf("structured HTML verification fixture did not cover index.html: %#v", observation), 1)
	}
	if evidence := completionGateVerificationEvidenceForResult(htmlCheck, []string{"index.html"}, nil); !evidence.Successful || !evidence.Relevant || !evidence.ClearsAll {
		ginkgo.Fail(fmt.Sprintf("structured HTML verification fixture did not clear the completion-gate obligation: %#v", evidence), 1)
	}
	results := []workspace.ToolResult{
		{Tool: "write_file", Summary: "Wrote index.html", ChangedPaths: []string{"index.html"}},
		{Tool: "source_sanity", Summary: "Source sanity unavailable", Error: "index.html is not a supported source file", Facts: &toolfacts.ToolResultFacts{DiagnosticEvidencePaths: []string{"index.html"}}},
		htmlCheck,
	}

	if ledger := postWriteVerificationLedgerForResults(results, brief); ledger.Pending() {
		ginkgo.Fail(fmt.Sprintf("focused HTML parser smoke check should satisfy post-write verification for index.html: %#v", ledger), 1)
	}

	if failed, ok := failedVerificationAfterLatestWrite(results, brief); ok {
		ginkgo.Fail(fmt.Sprintf("earlier unsupported source_sanity should not remain failed after HTML smoke check: %#v", failed), 1)
	}
})

